window.__D("text/torat-shmuel/c026",{"p":[[2000450105,"עלה ברצונו כו' מחמת כי טבע הטוב להטיב<sup data-n=\"490\">224</sup>, וכמ\"ש בע\"ח<sup data-n=\"491\">225</sup>. והפי' הב' בפי' כי אמרתי עולם חסד יבנה שבכדי להיות העולם שכולל בחי' מקום וזמן שעולם הוא בחי' מקום כנ\"ל בענין עולם שנה נפש, וגם כולל זמן ג\"כ כמו ועבדו לעולם שפי' עד זמן היובל<sup data-n=\"492\">226</sup> שהוא זמן ארוך שנק' עולם, ועכ\"ז הוא זמן כו'. ובכדי שיהי' העולם בבחי' מקום וזמן צריכים לבנות מדת החסד דאצי', והגם כי מתחילת הבריאה נברא העולם מצד כי חפץ חסד הוא שגם לפי' הב' כן הוא, עכ\"ז עכשיו באתעדל\"ת תלי' מילתא<sup data-n=\"493\">227</sup> שצריכים להמשיך ולבנות מדת החסד שתלוי במעשה התחתונים, וזהו כי אמרתי עולם זהו ע\"י חסד יבנה, שע\"י בנין החסד יתקיים העולם כו'.\n<b>ואמנם</b> צ\"ל שהרי ארז\"ל בפרק שנו חכמים, כל מה שברא הקב\"ה בעולמו<sup data-n=\"494\">228</sup> לא ברא<sup data-n=\"495\">229</sup> אלא לכבודו שנאמר כל הנקרא בשמי<sup data-n=\"496\">230</sup> ולכבודי בראתי<sup data-n=\"497\">231</sup> כו', וכתיב כל פעל ה' למענהו<sup data-n=\"498\">232</sup>, ולפי מה שנת\"ל בפי' כי אמרתי עולם חסד יבנה משמע להיפך שהוא רק חסד חנם להיטיב לברואיו לבד. אך הענין הוא דהנה קושי' זו עצמה יש ג\"כ במעשה המצות<sup data-n=\"499\">233</sup> שהרי ארז\"ל בילקוט האזינו רמז תתקמ\"ה בשם הפסיקתא בשעה שישראל ערש\"מ מוסיפים<sup data-n=\"500\">234</sup> כח וגבורה שנאמר ועתה יגדל נא כח אד'<sup data-n=\"501\">235</sup> שע\"י מעשה המצות נעשה הגדלה בבחי' כח אד' וכתיב הבו גודל לאלקינו, תנו עוז לאלקים<sup data-n=\"502\">236</sup>, שישראל ע\"י עבודתם במעהמ\"צ מוסיפים כח כו', ולהיפך ח\"ו כשמכעיסים אותו כביכול כתיב צור ילדך<sup data-n=\"503\">238</sup> תשי<sup data-n=\"504\">237</sup>, וכ\"ה במד\"ר איכה בפ' ויצא מבת ציון, רע\"ז בשם ר\"י בר' סימון בזמן שישראל ערש\"מ מוסיפים כח בגבורה ש\"מ כד\"א באלקים נעשה חיל (תילים ס') ובזמן שאערש\"מ כביכול מתישים כח ש\"מ דכתיב צור ילדך תשי (דברים ל\"ב) וכנ\"ל נמצא מובן היטיב שמעשה המצות פועלים שינוי למעליותא, ובמד\"ר בראשית ר\"פ מ\"ד<sup data-n=\"505\">239</sup> משמע להיפך דאיתא התם ע\"פ אמרת ה' צרופה (תילים י\"ח ל\"א) וכי מה איכפת לי' להקב\"ה אם שוחט מן",[["490","224","<b>טבע הטוב להטיב</b>: ראה עמק המלך שער שעשועי המלך בתחילתו. שומר אמונים ויכוח שני סי\"ד. שער היחוה\"א פ\"ד ובמ\"מ הגהות והע\"ק לשם. ולהעיר משו\"ת חכם צבי סי\"ח."],["491","225","<b>טבע הטוב להטיב וכמ\"ש בע\"ח</b>: ראה בסמוך בפנים על יד הערה 284. מאמרי אדה\"א קונטרסים ע' ה. וש\"נ. תורת חיים שמות ח\"א לד, ג הערה 375. סה\"מ תרס\"ה כאן ע' קמה."],["492","226","<b>ועבדו לעולם. . היובל</b>: משפטים כא, ו. מכילתא (ורש\"י) שם. קדושין טו, סע\"א."],["493","227","<b>באתעדל\"ת תלי' מילתא</b>: ראה ע\"ח שער דרושי נקודות ש\"ח, ספ\"ו. מאמרי אדה\"א בראשית ע' תקסו. וש\"נ."],["494","228","<b>כל מה שברא הקב\"ה בעולמו</b>: אבות פ\"ו, יא."],["495","229","<b>ברא</b>: כ\"ה בברייתא דקנין תורה שבמשניות. סה\"מ תרכ\"ז כאן ע' קמ. גי' אדה\"ז בסידורו: בראו."],["496","230","<b>כל הנקרא בשמי</b>: ישעי' מג, ז."],["497","231","<b>בראתי</b>: שם: בראתיו."],["498","232","<b>כל פעל ה' למענהו</b>: משלי טז, ד."],["499","233","<b>במעשה המצוות</b>: ראה גם אוה\"ת משפטים כאן ע' ג'כה. איוב כרך א ע' תרעט ואילך. סה\"מ תרכ\"ז ע' קמ. וש\"נ. תרכ\"ט ותרס\"ה שבהערה 218. תרס\"ב ע' רעג. תרע\"ח ע' רסב ואילך."],["500","234","<b>מוסיפים</b>: שם: הן מוסיפין."],["501","235","<b>ועתה יגדל נא כח אד'</b>: שלח יד, יז."],["502","236","<b>תנו עוז לאלקים</b>: תהלים סח, לה."],["503","238","<b>צור ילדך תשי</b>: האזינו לב, יח."],["504","237","<b>כשמכעיסים. . ילדך תשי</b>: ראה ילקוט שם."],["505","239","<b>ובמד\"ר בראשית ר\"פ מ\"ד</b>: בשינויים."]]],[2000450106,"הצואר או מן העורף, אלא שנתן הקב\"ה את המצות כדי לצרף בהם את הבריות הה\"ד אמרת ה' צרופה וכ\"ה בפ' שמיני<sup data-n=\"506\">240</sup>, וכן יש פסוקים בפירוש שאומרים אם חטאת מה תפעל בו<sup data-n=\"507\">241</sup> ורבו פשעיך מה תעשה לו, אם צדקת<sup data-n=\"508\">242</sup> מה תתן לו או מה מידך יקח, ונמצא לכאורה סותרים זא\"ז. אך הענין הוא דשניהם אמת, דהנה מה שע\"י המצות מוסיפים כח וגבורה זהו בבחי' ועל דמות הכסא דמות כמראה אדם כמראה אדם<sup data-n=\"509\">243</sup>, שבחי' אדם הוא בכלל בחי' ג' קווין חח\"ן בג\"ה דת\"י כנ\"ל, ובפרט בחי' אדם הוא רמ\"ח איברים דז\"א הוא בעל ט\"ס<sup data-n=\"510\">244</sup>, טפ\"ט הם פ\"א רת\"ס הם רמ\"ג וה\"ח המגדילים<sup data-n=\"511\">245</sup> הם רמ\"ח איברים דמלכא, וע\"י המצות נעשה תוס' אור כי רמ\"ח פקודין הם רמ\"ח איברים דמלכא<sup data-n=\"512\">246</sup> שכמו שהאבר ממשיך גילוי חיות הנפש<sup data-n=\"513\">247</sup> שמלבד שהוא כלי הנה הוא ממשיך גילוי אור הנפש כמ\"ש במ\"א, כמו\"כ ע\"י המצות שעושין רצוש\"מ, עי\"ז ממשיכים גילוי אוא\"ס בבחי' כמראה אדם שיהי' נמשך בחי' גילוי אור בבחי' תוס' מרובה על העיקר כידוע שתוספתו של הקב\"ה הוא מרובה על העיקר<sup data-n=\"514\">248</sup>, אבל כשמכעיסים ח\"ו, אזי אינו מאיר בהם גילוי אוא\"ס בבחי' גילוי כ\"א בבחי' העלם כו' וזהו שגלות מצרים נמשל לשינה<sup data-n=\"515\">249</sup> וכמ\"ש עורה למה תישן הוי'<sup data-n=\"516\">250</sup>, וכמו כמו<sup data-n=\"517\">251</sup> עד\"מ באדם כשהוא ישן יש בו כל כוחות הנפש ממש כמו שהוא בהיותו ער רק שהם בהעלם ואינם מאירים בו בגילוי בחי' כוחות הפנימי' כמו שכל ומדות, עד שבחלום יכול להיות דברים שלא יתכן כלל ע\"פ השכל כו', משא\"כ בהיותו ער מאירים בו בגילוי כוחותיו הפנימים שכל ומדות כו', ועד\"ז יובן למעלה ענין בחי' גלות מצרים שנמשל לשינה שאינו מאיר גילוי פנימיות אוא\"ס בבחי' ע\"ס, רק מה שצריך להיות לצורך קיום העולמות, וכמו שגם בעת השינה נשאר מה שנצרך בהכרח לצורך קיום חיות הגוף, וראיתי בכתבי דברי רבינו ז\"ל שא' לשון קיסטא<sup data-n=\"518\">252</sup>",[["506","240","<b>וכ\"ה בפ' שמיני</b>: ויק\"ר פי\"ג, ג בשינויים."],["507","241","<b>אם חטאת מה תפעל בו</b>: איוב לה, ו."],["508","242","<b>אם צדקת</b>: איוב שם, ז."],["509","243","<b>כמראה אדם כמראה אדם</b>: ב: כמראה אדם."],["510","244","<b>דז\"א הוא בעל ט\"ס</b>: בלקו\"ת שה\"ש יח, א מציין: ”כמ\"ש במ\"א בד\"ה אלפי שנאן בפ' יתרו [תו\"א יתרו עב, א] ועיין בזהר נח דס\"ה א' ובע\"ח שער א\"א פ\"ב\"."],["511","245","<b>רמ\"ג. . וה\"ח המגדילים</b>: ראה ע\"ח שער פרקי הצלם שכ\"ד, פ\"ו. סידור שער התפלה כה, ב. הנסמן בשע\"ת מב, ב הערה 13. לקמן מאמר ד\"ה וידבר וכו' אלה הם מועדי על יד הערה 52 ו(בחלק ההנחות) בהנחה שם על יד הערה 45."],["512","246","<b>רמ\"ח פקודין הם רמ\"ח איברים דמלכא</b>: ראה ת\"ז ת\"ל (עד, סע\"א). תניא רפכ\"ג. סידור שער החנוכה רפ, א. שע\"ת עב, ג הערה 17."],["513","247","<b>שהאבר ממשיך גילוי חיות הנפש</b>: ראה [בנוסף לסה\"מ תרכ\"ז־ תרכ\"ט (ובהערה שם)־ תרס\"ה שבהערה 218] מאמרי אדמו\"ר הצ\"צ תרט\"ו ע' סד (ובהנסמן בריש המאמר שם). ע' סט. סה\"מ תרכ\"ט ע' רט. וש\"נ. תרל\"ג ח\"ב ע' שנא. תרנ\"ט ע' ז ואילך."],["514","248","<b>שתוספתו של הקב\"ה. . העיקר</b>: ראה ב\"ר פס\"א, ד. לקו\"ש וישלח כרך ה ע' 422 הערה 3. ע' 423 הערה 10. ט-יוד כסלו כרך טו ע' 511 בהערה (ושם נדפס: פס\"ד וצ\"ל: פס\"א). י\"א ניסן כרך יז ע' 428 ובהערה 4. דברים כרך יט ע' 25."],["515","249","<b>שגלות. . שינה</b>: ראה תו\"ח שמות ח\"א לז, ד ובהערה 4. וראה גם סה\"מ תרכ\"ט ע' לג. וש\"נ."],["516","250","<b>עורה למה תישן הוי'</b>: תהלים מד, כד [ושם: אדני — ראה תו\"ח מקץ ריט, א ובהנסמן שם ריח, ד הערה 72. ויקהל ח\"ב שצט, ג. מאמרי אדה\"א נ\"ך ע' שב (ב\"פ). ס\"ע שג. ע' דש. אוה\"ת שמות כרך ח ע' ב'תתמג. סה\"מ תרכ\"ז כאן ע' קמ]."],["517","251","<b>וכמו כמו</b>: ב: וכמו."],["518","252","<b>וראיתי בכתבי דברי רבינו ז\"ל שא' לשון קיסטא דחיותא</b>: ראה גם מאמרי אדה\"ז תקס\"ה ח\"א ע' תקו. מאמרי אדה\"א הנחות תקע\"ז ע' קט ואילך."]]],[2000450107,"דחיותא<sup data-n=\"519\">253</sup> ע\"ז, אך הנה כ\"ז הוא רק בבחי' אדם לבד, אבל בבחי' עצמיות אוא\"ס שלמעלה מבחי' כמראה אדם, כחשוכה כאורה<sup data-n=\"520\">254</sup> שוין ואם צדקת כו', רק שכך עלה ברצונו ית' שיומשך אוא\"ס ע\"י בחי' מעשה המצות<sup data-n=\"521\">255</sup>, וזהו מ\"ש במד\"ר וכי מה איכפת לי' להקב\"ה אם שוחט כו' אלא שנתן את המצות כדי לצרף בהם את הבריות דהיינו שכך עלה ברצונו מחמת כי חפץ חסד הוא שימשיכו תוס' וריבוי אורות ע\"י מעהמ\"צ, ועפ\"ז יובן ג\"כ מ\"ש כי אמרתי עולם חסד יבנה, וכתי' כל הנקרא בשמי ולכבודי כו' וכל כל<sup data-n=\"522\">256</sup> פעל ה' למענהו, כי מ\"ש כל פעל ה' למענהו היינו בבחי' כבוד הנ\"ל שכל מה שברא כו' לא ברא אלא לכבודו, פי' כבוד עולה מספרו ל\"ב<sup data-n=\"523\">257</sup> הרומז לבחי' ל\"ב נת\"ח<sup data-n=\"524\">258</sup> שהם בחי' התפשטות החיות בעולמות כמ\"ש כולם בחכמה עשית<sup data-n=\"525\">259</sup>, אשר בבחי' חכ' שהיא ראשית ההשתלשלות<sup data-n=\"526\">260</sup>, שייך בחי' העלם וגילוי, וע\"י מעשה התחתונים ממשיכים גילוי אוא\"ס בבחי' חכ', וממילא נמשך למטה ג\"כ גילוי אוא\"ס, וזהו דכתיב מלא כל הארץ כבודו<sup data-n=\"527\">261</sup> שגילוי בחי' חכ' נמשך דוקא בארץ, והיינו ע\"י מעשה התחתונים שעוסקים במעשה המצות שניתנו בגשמיות דוקא כו', ולכן כשהמלאכים ביקשו התורה<sup data-n=\"528\">262</sup> לא ניתן להם, לפי שעיקר גילוי בחי' ח\"ע אינו נמשך אלא למטה דוקא ע\"י מעשה המצות של התחתונים דוקא, וכמו שהשיב להם משה כלום יצה\"ר יש בניכם<sup data-n=\"529\">263</sup> כו'.\n<span data-k=\"ks\"><b>קיצור.</b> ב' פי' בפסוק כי אמרתי כו' חפץ חסד, לבנות החסד, ולכאורה הלא כל פעל למענהו, במעהמ\"צ ג\"כ פעם אמרו מוסיפים כו' ופעם וכי מאי איכפת, ענין מוסיפים זהו בציור אדם, ולהיפך כענין שינה, אבל בעצמותו כחשוכה כאורה וכי מאי איכפת כך עלה ברצונו וזהו מצד חפץ חסד, ומ\"ש כל פעל, לא ברא אלא לכבודו פי' כבודו ל\"ב נתיבות חכ' שזהו בחי' אדם הנ\"ל, וזהו מכה\"כ ע\"י מעהמ\"צ של התחתונים דוקא כלום יצה\"ר יש בניכם. </span>",[["519","253","<b>קיסטא דחיותא</b>: ראה זהר לך פג, א. אור החמה־ רא\"ג־ מקדש מלך שם. שער הכוונת ענין דרושי הלילה דרוש ו [ושם: הנזכר בזוהר בכמה מקומות]. לקו\"ת אמור לא, ב ובנסמן במ\"מ לשם."],["520","254","<b>כחשוכה </b>[ב: כחשיכא]<b> כאורה</b>: ע\"פ תהלים קלט, יב. ראה לקו\"ת צו יב, א. סידור סדר הגדה רצז, רע\"ד. עט\"ר דרוש לעשי\"ת ע' נא. סה\"מ תרכ\"ז ע' תצד."],["521","255","<b>שכך עלה. . מעשה המצות</b>: ראה גם לקו\"ש תבוא כרך ד ע' 1133 הערה 13."],["522","256","<b>וכל כל</b>: ב: וכל."],["523","257","<b>כבוד עולה מספרו ל\"ב</b>: זהר רע\"מ צו לג, א."],["524","258","<b>כבוד. . ל\"ב נת\"ח</b>: ראה פרדס שעה\"כ שכ\"ג, פי\"א מערכת כבוד. מאמרי אדה\"א בראשית ע' ג ואילך. דברים ח\"ב ע' שפ. וש\"נ."],["525","259","<b>כולם בחכמה עשית</b>: תהלים קד, כד."],["526","260","<b>חכ' שהיא ראשית ההשתלשלות</b>: בלקו\"ת שה\"ש כו, ד מציין: כ\"ה בע\"ח שער מוחין דצלם פ\"ה [במהדורת שקלאב, ולפנינו: פ\"א] בשם ספר יצירה וכ\"כ עוד בשער כ\"ה דרוש ה' וכ\"כ הרמ\"ז פ' ואתחנן בדף רס\"ו [באוה\"ת יתרו ע' תתמ: דרס\"ה ע\"ב בד\"ה אבל צריך. בדפי הספר קצד, סע\"ב] ועיין בזהר ויקרא ד\"י סע\"ב קדמאה י\"ה ועיין מק\"מ שם."],["527","261","<b>מלא כל הארץ כבודו</b>: ישעי' ו, ג."],["528","262","<b>כשהמלאכים בקשו התורה</b>: שבת פח, ב."],["529","263","<b>כלום יצה\"ר יש בניכם </b>[ב: ביניכם]: ראה שם פט, א. מאמרי אדה\"א ויקרא ח\"ב ע' תסט בהערה. אוה\"ת בראשית כרך ג ע' תקסג."]]],[2000450108,"יג) <b>ועפ\"ז</b> יובן מארז\"ל חמשה קנינים קנה הקב\"ה<sup data-n=\"530\">264</sup> בעולמו שמים וארץ קנין א', דלכאורה אינו מובן שהרי כתיב בורא שמים וארץ<sup data-n=\"531\">265</sup>, אך הנה החילוק שבין בריאה לקנין היינו כי בריאה הוא מאין ליש, והיינו מצד בחי' כי חפץ חסד, עד שנעשה בחי' מציאות התהוות היש לבחי' יש ודבר נפרד, וע' בד\"ה ביום השמע\"צ והביאור שלא נדפס<sup data-n=\"532\">266</sup> שהתהוות היש הוא דוקא מבחי' אוא\"ס הסוכ\"ע, אבל ענין ופי' קנין זהו כענין מ\"ש כל פעל ה' למענהו, והיינו מה שנמשך גילוי אלקות נק' בשם קנין, וזהו שאומרים בשבת קונה שמים וארץ<sup data-n=\"533\">267</sup>, והיינו מפני שבשבת כתי' שבת וינפש<sup data-n=\"534\">268</sup> מבחי' בריאה כי שבת הוא בחי' עליות העולמות<sup data-n=\"535\">269</sup> שז\"ע שבת וינפש, ויובן ענין השביתה עד\"מ באדם השובת ונח ממלאכתו אשר עשה שבשעת מעשה הי' שכלו ומחשבתו ומחשבתו<sup data-n=\"536\">270</sup> מלובשים במעשה ההיא, ואח\"כ כששובת חוזר שכלו ומחשבתו למקורן והרי עולה החיות המתפשט ושכלו ומחשבתו שנתלבש במעשה ההיא להכלל במקורו הוא השכל והמחשבה, ועד\"ז יובן בענין דבורו של הקב\"ה שחשיב מעשה<sup data-n=\"537\">271</sup> הנה ארז\"ל בעשרה דברים ברא הקב\"ה<sup data-n=\"538\">272</sup> את עולמו בחכמה ובתבונה כו', ובשבת עולים כל בחי' אלו שהוא בחי' התפשטות החיות שנמשך להוות העולמות בששת ימי המעשה להכלל במקורו, וע\"כ אומרים אז קונה שמים וארץ, כי קנין הוא בחי' אצילות העליון, ולכן אומרים בשעת קידוש לבנה ברוך עושך ברוך יוצרך ברוך בוראך שזהו נגד בי\"ע ואח\"כ ברוך קונך<sup data-n=\"539\">273</sup> שהיא נגד האצי', בחי' ש' הוי' שעיקרו בחי' היו\"ד<sup data-n=\"540\">274</sup> כמ\"ש במ\"א, שהוא מאיר באצי'<sup data-n=\"541\">275</sup>, וגם ש' הוי' מקור האורות דאצי' כנ\"ל, משא\"כ בריאת העולם הי' מש' אלקים כמ\"ש בראשית ברא אלקים<sup data-n=\"542\">276</sup>, וכן בשבת מאיר ש' הוי'",[["530","264","<b>חמשה קנינים קנה הקב\"ה</b>: ראה אבות פ\"ו, י. ראה גם אוה\"ת כאן ע' ג'כו."],["531","265","<b>בורא שמים וארץ</b>: כ\"ה גם באוה\"ת כאן ע' ג'כו. תו\"ח משפטים ח\"ב רפד, ב ובהערה 9. סה\"מ תרל\"ו ח\"ב ע' תקכה. ראה ישעי סה יז [ושם: בורא שמים חדשים וארץ]. אבל בתרל\"ו שם ע' רנא: ”בורא השמי' (ישעי' מ\"ב ה')\"."],["532","266","<b>בד\"ה ביום השמע\"צ והביאור שלא נדפס</b>: דשנת תקע\"ב (ויודפסו בעז\"ה במאמרי אדה\"ז תקע\"ב). המאמר בתוס' הערות וכו' נדפס באוה\"ת שמ\"ע ע' (א'תשעט) א'תשפב. מאמרי אדה\"א דברים ח\"ד ע' א'רפו ואילך. והביאור — נדפס בתוס' הערות וכו' בסה\"מ תרל\"ג ח\"ב ע' תקלד ואילך. וש\"נ."],["533","267","<b>שאומרים בשבת קונה שמים וארץ</b>: בברכה מעין ז'. ראה גם תו\"א תרומה פ, ב. מאמרי אדה\"ז כתובים ח\"ב ס\"ע קפה ואילך."],["534","268","<b>שבת וינפש</b>: תשא לא, יז."],["535","269","<b>שבת. . עליות העולמות</b>: ראה ע\"ח שער פנימיות וחיצוניות ש\"מ, דרוש ג. ח. טו. תו\"ח בא ח\"א קכז, א הערה 667."],["536","270","<b>ומחשבתו ומחשבתו</b>: ב: ומחשבתו."],["537","271","<b>דבורו. . שחשיב מעשה</b>: ראה ב\"ר פמ\"ד, כב. רש\"י לך טו, יח."],["538","272","<b>בעשרה דברים ברא הקב\"ה</b>: ראה חגיגה יב, א."],["539","273","<b>קנין. . אצילות. . ברוך קונך</b>: סידור האריז\"ל במקומו. פע\"ח שער ר\"ח שי\"ט, פ\"ג. ראה מאמרי אדה\"ז תקס\"ה ח\"ב ע' רסט (נו\"ש). ע' רפח. תו\"ח משפטים ח\"ב רפד, ב. לקו\"ש לך כרך לה ע' 41 הערה 21. המשך תרס\"ו ס\"ע קס ואילך. לקמן המשך חייב אדם לברך פל\"ו ובהערה 1450."],["540","274","<b>ש' הוי' שעיקרו בחי' היו\"ד</b>: ראה גם אוה\"ת תשא ע' א'תתקצג. תצוה כרך ח ע' ג'עט. לקו\"ש כרך כ ע' 270. לעיל המשך וידבר וגו' ויצוום פי\"ג על יד הערה 247."],["541","275","<b>היו\"ד. . מאיר באצי'</b>: ראה ע\"ח שער סדר אצי' ש\"ג, פ\"א. תו\"ח ח\"ש קכח, ב הערה 21. שמות ח\"א כד, ד הערה 62."],["542","276","<b>בראשית ברא אלקים</b>: בראשית א, א."]]],[2000450109,"כמ\"ש שבת להוי'<sup data-n=\"543\">277</sup>, ולכן אומרים בשבת קונה שמים וארץ שבשבת מאיר בשמים ובארץ בחי' ש' הוי' שזהו בחי' קנין, וזהו דכתי' ישמחו השמים ותגל הארץ ר\"ת ש' הוי'<sup data-n=\"544\">278</sup>, והיינו כי בשבת מאיר בהם ש' הוי' ואז נק' קנין, ולכן בקידוש ליל שבת מתחילים יום השישי ויכולו השמים ר\"ת ש' הוי'<sup data-n=\"545\">279</sup> לרמז על בחי' ש' הוי' שמאיר בשבת עד שגם שמים וארץ נעשים בבחי' קנין כו', והנה בקנין יש בחי' משיכה וכסף<sup data-n=\"546\">280</sup>, ועד\"ז יובן בענין בחי' הקנין למעלה שמתחילה צ\"ל בחי' משיכה בחי' העלאה מלמטה למעלה, והוא ע\"י בחי' משכני אחריך נרוצה<sup data-n=\"547\">281</sup>, ואח\"כ נמשך מלמעלה בחי' כסף שהוא המשכת אלקות מלמעלה למטה כסף הוא בחי' גון לבן<sup data-n=\"548\">282</sup> בחי' חסד<sup data-n=\"549\">283</sup>, והיינו בחי' המשכת בחי' רב חסד הנ\"ל שנת' בענין גמ\"ח.\n<b>וז\"ע</b> כל פעל ה' למענהו, אבל בעצמיות אוא\"ס הוא רק בחי' כי חפץ חסד הוא שכך עלה במח' לפניו וכך עלה ברצונו לעשות חסד וכמ\"ש בע\"ח להטיב לברואיו<sup data-n=\"550\">284</sup>, וזהו מ\"ש כי אמרתי עולם חסד יבנה שבריאות העולמות הי' מצד בחי' כי חפץ חסד הוא, ואפי' כל המצות הנה כתי' כל מצותיך צדק<sup data-n=\"551\">285</sup> שכל בחי' המצות הם רק בדרך צדקה וחסד לבד כי באמת וכי מאי איכפת לי' וכנ\"ל, אלא שזהו בדרך צדקה וחסד מבחי' כי חפץ חסד, אך מ\"מ מאחר שעלה ברצונו שיהי' עולמות ע\"כ צריכין לבנות מדת החסד וזהו כפי' הב' בפי' חסד יבנה, וצ\"ל בנין החסד הכוונה על בחי' חסד דאצי', וגם י\"ל על בחי' רב חסד או חפץ חסד, רק שצריך לומר פי' בחי' בנין החסד הוא להמשיך בחי' החסד הנ\"ל, והיינו מאחר שכבר עלה ברצונו להיטיב לברואיו מצד טבע הטוב להיטיב, ונמשך בחי' זו מצד כי חפץ חסד הוא בתחילת הבריאה, ואח\"כ צריכים אנו להמשיך בחי' זו באתעדל\"ת אתעדל\"ע<sup data-n=\"552\">286</sup>, והגם כי בעצם בחי' הוא<sup data-n=\"553\">287</sup> למעלה מכדי שתוכל לפעול בבחי' אתעדל\"ת של הנבראים, אך באמת גם זה הוא מצד בחי' כי חפץ חסד הוא, ומחמת טבע הטוב להיטיב לברואיו שיפעול בחי' האתעדל\"ת של הנבראים להמשיך בחי' אתעדל\"ע מבחי' גבוה כזה, והיינו מצד שכבר עלה ברצונו כו', וע\"י מה ממשיכים את החסד הנ\"ל הוא ע\"י מה שהאדם עושה למטה צדקה וחסד שנותן לעני דלית לי'",[["543","277","<b>שבת להוי'</b>: יתרו כ, י. ואתחנן ה, יד. ראה גם תו\"ח יתרו ח\"ב רסו, ג."],["544","278","<b>ישמחו השמים. . ר\"ת ש' הוי'</b>: תהלים צו, יא. דהי\"א טז, לא. ת\"ז בהקדמה ט, ב. בעה\"ט שבהערה הבאה."],["545","279","<b>יום השישי. . ש' הוי'</b>: בראשית א, לא. ב, א. בעל הטורים שם. רמ\"א (ושו\"ע אדה\"ז) הל' שבת סרע\"א, ס\"י (סי\"ט)."],["546","280","<b>בקנין. . משיכה וכסף</b>: ראה לקו\"ת עקב טז, סע\"ג ואילך. סידור שער בהמ\"ז קיא, ב. ד. מאמרי אדה\"ז תקע\"א ע' קג. אוה\"ת עקב ע' תקלד. סהמ\"צ להצ\"צ לו, ב ואילך. סה\"מ תרל\"ב ח\"א ע' ע. וש\"נ. תרל\"ו ח\"ב ע' רנח."],["547","281","<b>משכני אחריך נרוצה</b>: שה\"ש א, ד."],["548","282","<b>כסף. . גון לבן</b>: ראה פרדס שער הגוונים ש\"י, פ\"ג."],["549","283","<b>כסף. . חסד</b>: ראה זהר רע\"מ תצא רעז, א. פרדס שם. לקו\"ש תרומה כרך ו ע' 159 הערה 51. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תתמג ובהנסמן במ\"מ לשם."],["550","284","<b>וכמ\"ש בע\"ח להטיב לברואיו</b>: ראה לעיל הערה 225."],["551","285","<b>כל מצותיך צדק</b>: תהלים קיט, קעב."],["552","286","<b>באתעדל\"ת אתעדל\"ע</b>: ראה זהר לך פח, א. תו\"ח שמות ח\"א מא, א ובהערה 189."],["553","287","<b>בחי' הוא</b>: כנצ\"ל: בחי' זו הוא."]]],[2000450110,"מגרמי' כלום<sup data-n=\"554\">288</sup> כו'. ועוי\"ל שע\"י שעושה גמ\"ח יתר מכפי כחו ויכולתו ממשיך מלמעלה ג\"כ אתעדל\"ע שלמעלה מכפי שאתעדל\"ת מגעת, כי במדה שאדם מודד<sup data-n=\"555\">289</sup> בה מודדין לו, ומאחר שפעל בעצמו יתר מכפי ההגבלה נותנין לו מלמעלה ג\"כ יתר מכפי ההגבלה כו', וזהו ג\"כ פי' הפסוק אם כסף תלוה את עמי רק גמ\"ח לחבירו בלי שום פני' לגרמי' כלל, עי\"ז נמשך מלמעלה ג\"כ בחי' חסד לעולמות בחי' כי אמרתי עולם חסד יבנה כו'.\n<span data-k=\"ks\"><b>קיצור.</b> חמשה קנינים, בריאה יש מאין מצד חפץ חסד קנין גילוי אלקות, ולכן בשבת אומרים קונה שבשבת גילוי ש' הוי' קנין אצי' משיכה וכסף בחי' רב חסד, אבל בעצמיות חסד יבנה ועכשיו צריכים להמשיך בחי' ע\"י<sup data-n=\"556\">290</sup> החסד שעושים למטה, וזהו ג\"כ מחמת טבע הטוב כו', וגם י\"ל ע\"י שעושה יתר מהגבלתו כו', וזהו אם כסף תלוה כו', גמ\"ח ע\"י נמשך בחי' חסד יבנה כו'.</span>",[["554","288","<b>לעני דלית לי' מגרמי' כלום</b>: ראה זהר בחוקותי קיג, ב."],["555","289","<b>במדה שאדם מודד</b>: סוטה ח, ב במשנה."],["556","290","<b>בחי' ע\"י</b>: כ\"ה גם בב."]]],[2000450111,"<h3>מלוה ה' חונן דל כו' את העני עמך</h3>\nיד) <b>ומעתה</b><sup data-n=\"557\">291</sup> יובן ענין מ\"ש את עמי שפי' במד\"ר את עמי בחיריק תחת העין, דהנה כתיב כי עמך מקור חיים פי' חיים הוא בחי' החיות של כל העולמות כו', והיינו בחי' חכ', כמ\"ש והחכ' תחי'<sup data-n=\"558\">292</sup> כו', ומקור חיים היינו למעלה מן החכ'<sup data-n=\"559\">293</sup>, וא\"כ פי' כי עמך מקור חיים שגם בחי' מקור חיים הוא ג\"כ בטל וטפל לך, אך מ\"מ הוא עמך, וזהו שא' בפדר\"א עד שלא נברא העולם הי' הוא ושמו בלבד<sup data-n=\"560\">294</sup> שהי' האור כלול במאור כו', והנה בחי' מקור חיים הנ\"ל נקרא מקור מים חיים, ועז\"נ אותי עזבו מקור מים חיים<sup data-n=\"561\">295</sup>, ונודע כי מים הם בחי' המשכה למטה כי מים יורדים כו', וזהו את עמי בחירק כו' שעי\"ז ממשיכים בחי' מקור מים חיים למטה, שהמקור מים חיים הוא עמי והוא בחי' עד שלא נברא העולם הי' הוא ושמו בלבד, וזהו גמ\"ח טוב לשמים וטוב לבריות<sup data-n=\"562\">296</sup> שטוב לשמים שעי\"ז מתמלא להיות דירתו בתחתונים שהוא מה שנתאוה הקב\"ה כו' ומאחר שממשיכים שיהי' נמשך מבחי' שמו כמו שהוא כלול בעצמותו למטה אין לך דירה בתחתונים יותר מזה, וטוב לבריות בשני",[["557","291","<b>ומעתה</b>: במפתח הבוך 1089 נרשם כאן מאמר ד\"ה: מלוה ה' חונן דל (לפרק יד) היינו שבעת אמירת הדרוש היתה פתיחא זו, ולע\"ע אין ידוע אם פתיחה זו נרשמה בפ\"ע גם ע\"י כ\"ק אדמו\"ר מהר\"ש.\nלמאמר זה ראה אוה\"ת משפטים כרך ח ע' ג'כז. ע' ג'כח. סה\"מ תרכ\"ז ע' קמב־ תרכ\"ט ע' עד־ תרס\"ה ע' קמו."],["558","292","<b>והחכ' תחי'</b>: קהלת ז, יב [ושם: החכמה — ראה לקמן המשך חייב אדם לברך פכ\"ה על יד הערה 962. פל\"ט ביו הערות 1688-1689. מאמר ד\"ה אני לדודי על יד הערה 72. ו(בחלק ההנחות) הנחה ד\"ה חייב אדם לברך על יד הערה 10. ד\"ה ביום ההוא יהי' על יד הערה 14. מאמרי אדה\"א דברים ח\"א ע' ש. וש\"נ. תו\"ח שמות ח\"א ב, ב הערה 84. סה\"מ שבהערה שלפנ\"ז. תרל\"ו ח\"ב ע' רצו]."],["559","293","<b>ומקור חיים. . החכ'</b>: ראה גם מאמרי אדה\"ז תקס\"ה ח\"ב ע' תרפב."],["560","294","<b>בפדר\"א. . ושמו בלבד</b>: ראה שם פ\"ג. תו\"ח וארא ח\"א נג, ב הערה 6."],["561","295","<b>אותי עזבו מקור מים חיים</b>: ירמי' ב, יג."],["562","296","<b>טוב לשמים וטוב לבריות</b>: קדושין מ, א. ראה לעיל פ\"ב."]]],[2000450112,"הענינים בהשפעת החסד והמשכת אלקות להיות את עמי בחירק (כי בריות קאי על נה\"ב שבאדם עצמו כמ\"ש בד\"ה מים רבים<sup data-n=\"563\">297</sup> באורך).\n<b>אך</b> ע\"י מה ממשיכים בחי' זו להיות את עמי זהו ע\"י את העני עמך, דהנה ארז\"ל אם הקב\"ה אוהב את העניים<sup data-n=\"564\">298</sup> למה אינו מפרנסן בעצמו ולמה להזהיר על הספקת העניים, ואמרו שם תירוץ ע\"ז, אך עיקר התירוץ הוא שעני ועשיר הם כנגד שמשא וסיהרא<sup data-n=\"565\">299</sup>, ונודע כי סיהרא לית לי' מגרמי' כלום<sup data-n=\"566\">300</sup> שאין לה אור בפ\"ע כלל<sup data-n=\"567\">301</sup> רק שמקבלת האור מבחי' שמש, ולכן יש בה שינוים שפעם היא מלא ופעם היא חסר, שבתחילת החודש כשמקבלת מהשמש היא בבחי' ביטול בחי' נקתה\"י<sup data-n=\"568\">302</sup>, ואח\"כ מתמלאת עד חצי החדש, לפי שמקבלת האור מהשמש, ומחצי החדש ואילך הולכת וחוסרת עד שמקבלת שנית, והמכוון מה שסיהרא לית לה מגרמה כלום, ושתהא צריכה לקבל אורה מהשמש דוקא לפי שעי\"ז היא בבחי' ביטול, וכתיב ואל זה אביט<sup data-n=\"569\">303</sup> אל עני ונכה רוח דוקא, וכשהלבנה צריכה לקבל אור מהשמש כשמתקרבת אל השמש היא בתכלית הביטול עד שנעשית נקודה חדא כנ\"ל, ונק' עני, וזהו שדהע\"ה אמר על עצמו כי עני ואביון אני<sup data-n=\"570\">304</sup>, אשר לכאורה נפלא איך אמר דוד ע\"ע<sup data-n=\"571\">305</sup> עני ואביון הלא הי' מלך ישראל, אלא לפי שדוד הי' מרכבה לבחי' המל'<sup data-n=\"572\">306</sup> שהיא בחי' סיהרא דלית לה מגרמה כלום ע\"כ אמר ע\"ע עני ואביון, והיינו שהי' בבחי' ביטול בתכלית לאלקות בכדי לקבל גילוי אוא\"ס ע\"ד בחי' ביטול הסיהרא שנעשית נקתה\"י כו', ולכן מ'<sup data-n=\"573\">307</sup> נקרא ג\"כ עני כמ\"ש עני ורוכב על החמור<sup data-n=\"574\">308</sup>, והיינו לפי שהביטול הוא הכלי לגילוי אוא\"ס, וכמ\"ש מרום וקדוש אשכון את דכא<sup data-n=\"575\">309</sup> כו', וזהו שפי' רש\"י ע\"פ את העני עמך<sup data-n=\"576\">310</sup> הוי מסתכל בעצמך כאילו",[["563","297","<b>בריות. . נה\"ב. . בד\"ה מים רבים</b>: תרל\"ו פק\"י ע' קטו."],["564","298","<b>אם הקב\"ה אוהב את העניים</b>: ראה ילקוט שמעוני משלי כא, כא (רמז תתקנט). ב\"ב י, א."],["565","299","<b>שעני ועשיר. . שמשא וסיהרא</b>: ראה ת\"ז תמ\"ד. אוה\"ת ר\"ה ע' א'שצד. עקב ע' תקנא. כאן ע' א'קסח. ע' ג'כז. סה\"מ תרכ\"ז כאן ע'קמב וע' תל."],["566","300","<b>סיהרא. . מגרמי' </b>[ב: מגרמה]<b> כלום</b>: ראה זהר בראשית לג, ב. תולדות קלה, סע\"ב. ויחי רלו, ב. רמט, ב. ויקהל רטו, א. בחוקותי קיג, ב. מאמרי אדה\"ז הקצרים ע' שפג."],["567","301","<b>שאין לה אור בפ\"ע כלל</b>: ראה סידור שחרית לשבת קפב, ד. מאמרי אדה\"א דברים ח\"ג ע' תתפג. וש\"נ. קונטרסים ע' רו. וש\"נ. תו\"ח בא ח\"א צו, ג. סה\"מ תרכ\"ז כאן. המשך והחרים תרל\"א ע' מא. פלח הרמון יתרו ע' ריח."],["568","302","<b>נקתה\"י</b>: נקודה תחת היסוד."],["569","303","<b>ואל זה אביט</b>: ישעי' סו, ב."],["570","304","<b>כי עני ואביון אני</b>: תהלים פו, א. ראה גם מאמרי אדה\"ז על פרשיות התורה ח\"א ע' ב. הקצרים ע' תקג. מאמרי אדה\"א בראשית ס\"ע סא ואילך. דברים ח\"ג ע' תתקסו. סה\"מ תרכ\"ז כאן וע' תלט. תרכ\"ח ע' סג. לקמן מאמר ד\"ה זה עני על יד הערה 8. וראה גם המשך מצה זו תר\"ם ע' מח."],["571","305","<b>ע\"ע</b>: על עצמו."],["572","306","<b>שדוד הי' מרכבה לבחי' המל'</b>: ראה פרדס שעה\"כ שכ\"ג, פ\"ד מערכת דוד. הנסמן במאמרי אדה\"א דברים ח\"ג ע' תתקט."],["573","307","<b>מ'</b>: משיח. ראה גם לקמן המשך כי תשא פ\"ג על יד הערה 76. מאמר ד\"ה וכל מאמינים על יד הערה 9. סה\"מ תרל\"ב ח\"א ע' סג."],["574","308","<b>מ'. . עני ורוכב על החמור</b>: זכרי' ט, ט. ראה סנהדרין צח, א. אוה\"ת בא ע' רס. ישעי' ע' צד. סה\"מ תרכ\"ז כאן ע' קמג וע' תלח."],["575","309","<b>מרום וקדוש אשכון את דכא</b>: ישעי' נז, טו [ושם: ואת — ראה סה\"מ תרכ\"ז כאן ע' קמג וע' רא]."],["576","310","<b>רש\"י ע\"פ את העני עמך</b>: משפטים כב, כד."]]],[2000450113,"את<sup data-n=\"577\">311</sup> עני, ובעבודה הוא שיהי' בבחי' ביטול לאלקות, ועי\"ז ממשיך בחי' מה שהוא עמך בחי' מקור מים חיים הנ\"ל, וזהו ג\"כ כוונת מארז\"ל יאי עניותא לישראל<sup data-n=\"578\">312</sup> שהכוונה היא על בחי' הביטול שהו\"ע היותו נכנע שהמקבל צ\"ל בתכלית הביטול לאלקות, ועי\"ז נמשך בחי' גילוי אלקות, וע\"פ פשוט את העני עמך שישפיע לעני גמ\"ח כו', והנה ע\"י השפעת העשיר לעני עי\"ז גורם למעלה בחי' יחוד שמשא וסיהרא, שהוא בחי' יחוד ה' ואלקים<sup data-n=\"579\">313</sup>, דהיינו שעי\"ז נמשך בחי' גילוי ש' הוי' שהוא בחי' שמש וכמ\"ש שמש כו' הוי'<sup data-n=\"580\">314</sup>, בשם אלקים שהוא בחי' ירח<sup data-n=\"581\">315</sup> ובאמת עי\"ז נמשך תוס' אור גם בש' הוי' כמ\"ש מלוה ה' חונן<sup data-n=\"582\">316</sup> משמע מזה שגם בבחי' שם הוי' נמשך ג\"כ המשכה בבחי' תוס' וריבוי אור והיינו מבחי' ש' הוי' דלעילא בחי' מקור מים חיים הנ\"ל. וזהו דכתיב והי' אור הלבנה<sup data-n=\"583\">317</sup> כאור החמה ואור החמה יהי' שבעתים, פי' ע\"י שאור הלבנה תהי' כאור החמה ע\"י בחי' יחוד שמשא וסיהרא עי\"ז תהי' אור החמה שבעתיים, כאור שבעת הימים שזהו תוס' מרובה כו'. וזהו אם כסף תלוה כו' את העני עמך שנעשה עי\"ז יחוד שמשא וסיהרא בחי' והי' אור הלבנה כאור החמה, עי\"ז את עמי בחירק שממשיכים מה שהוא עמי, והיינו שבחי' אור החמה תהי' שבעתיים כאור שבעת הימים, דהיינו המשכת בחי' כי עמך מקור חיים בחי' מקור מים חיים היינו בחי' עשנה\"ע הי' הוא ושמו בלבד כו', והענין הוא דהנה יש ב' שמות הוי'<sup data-n=\"584\">318</sup> כמ\"ש ויקרא הוי' הוי'<sup data-n=\"585\">319</sup> ופסיק טעמא בנייהו<sup data-n=\"586\">320</sup>, הא' הוא בחי' עד שנבה\"ע הי' הוא ושמו בלבד בחי' האור כמו שהוא כלול במאור שהוא ג\"כ ש' הוי'<sup data-n=\"587\">321</sup> כנודע, וש' הוי' שבסדר השתלשלות זהו בחי' ש' הוי' הב', וע\"י שנעשה יחוד שמשא וסיהרא משפיע ומקבל ע\"י השפעת העשיר לעני, עי\"ז נמשך למעלה ג\"כ שיהי' נמשך מש'",[["577","311","<b>את</b>: וכ\"ה בסה\"מ תרכ\"ז־ תרכ\"ט ותרס\"ה כאן. וברש\"י אתה."],["578","312","<b>יאי עניותא לישראל</b>: יל\"ש ישעי' מח, י (רמז תסו)־ כד הקמח מערכת עושר ע' שא [ושם: יאי — ראה גם תוד\"ה כברזא חגיגה ט, ב]. חגיגה ט, ב כגי' הע\"י [ושם: יאה]. ראה גם לקו\"ת ויקרא ו, ד. אוה\"ת כאן ע' א'קסח. ע' ג'כח [ושם: יאי]. ר\"ה ע' א'שצד. ישעי' ע' צד. סה\"מ תרכ\"ז כאן ע' קמג וע' תכט."],["579","313","<b>שמשא וסיהרא. . ה' ואלקים</b>: ראה זהר בראשית כ, א."],["580","314","<b>שמש כו' הוי'</b>: תהלים פד, יב."],["581","315","<b>אלקים. . ירח</b>: ראה גם תו\"ח בשלח ח\"א קסח, א. וש\"נ. אוה\"ת פינחס ע' א'קעד. בראשית ע' לז ואילך."],["582","316","<b>מלוה ה' חונן</b>: משלי יט, יז."],["583","317","<b>והי' אור הלבנה</b>: ישעי' ל, כו."],["584","318","<b>ב' שמות הוי'</b>: ראה הערה הבאה."],["585","319","<b>ויקרא הוי' הוי'</b>: תשא לד, ו. ראה גם לעיל על יד הערה 66. לקמן המשך חייב אדם לברך פ\"ד. מאמר ד\"ה אנכי אנכי על יד הערה 70. ד\"ה וידבר וכו' אלה הם מועדי על יד הערה 84 (ובהנסמן בריש המאמר שם). ו(בחלק ההנחות) בהנחה ד\"ה ב\"ה אלקי ישראל על יד הערה 19. ד\"ה וידבר וכו' אלה הם מועדי על יד הערה 61. לקו\"ת ר\"ה נט, א ובציון הצ\"צ שם. תו\"ח בשלח ח\"א קמט, ד ובהערה 9. אוה\"ת חוקת ע' תתיג. סה\"מ תרכ\"ו ס\"ע יח ואילך. ע' קטו. תרכ\"ז ע' קמג. תרל\"ב ח\"א ע' קכז. וש\"נ. ח\"ב ע' תקב. וש\"נ."],["586","320","<b>ופסיק טעמא בנייהו</b>: זהר אד\"ר נשא קלח, רע\"א. ראה גם לעיל הערה 66. לקמן מאמר ד\"ה על חומותיך על יד הערה 112. הנסמן במאמרי אדה\"א נ\"ך ע' תקעז. תו\"ח בשלח ח\"א קנז, ב הערה 361."],["587","321","<b>האור. . במאור. . ש' הוי'</b>: ראה גם לקמן מאמר ד\"ה וידבר וכו' אלה הם מועדי על יד הערה 83 (ובהנסמן בריש המאמר שם). סה\"מ תרל\"ב ח\"א ע' קכז. ס\"ע קל ואילך. ע' רפו. אוה\"ת חוקת ע' תתיג. תצא ע' תתקה. ר\"ה כרך ה ע' ב'צה."]]],[2000450114,"הוי' הא' שלמעלה מסדר השתלשלות בחי' שמו בלבד, בבחי' ש' הוי' הב' בחי' אור החמה דעכשיו, וזהו מלוה ה' חונן דל, שע\"י שחונן דל עי\"ז נמשך תוס' אור בשם הוי' כו', שז\"ע את עמי את העני עמך שע\"י שהעני עמך עי\"ז את עמי שממשיכים מה שהוא עמי היינו בחי' שמו בלבד האור כמו שהוא כלול במאור כו' שז\"ע עמי כו'.\n<span data-k=\"ks\"><b>קיצור.</b> כי עמך מקו\"ח בחי' מקור מ\"ח שמו בלבד מה שעמי שיומשך למטה והוא ע\"י את העני עמך שעי\"ז נמשך יחוד שמשא וסיהרא ועי\"ז מלוה הוי' שנמשך תוס' בש' הוי' מבחי' ש' הוי' דלעילא מה שהוא עמי כו'.</span>"],[2000450115,"<h3>כי תשא כו'</h3>\n<b>בס\"ד</b>\n<b></b>ענין המספר כו' ג' בחי' בכוכבים כו' שם ושמן (פרק א-ג)\nכי תשא<sup data-n=\"588\">1</sup> את ראש בנ\"י לפקודיהם, ונתנו איש כפר<sup data-n=\"589\">2</sup> כו' זה יתנו<sup data-n=\"590\">3</sup> כו'. ולכאורה צ\"ל מהו ענין המספר שציוה לפקוד אותם, רק לא אותם ממש, כ\"א שקליהם אשר יתנו, והא ארז\"ל פ\"ק דתענית ד\"ח סע\"ב ובפ\"ג דב\"מ דמ\"ב ע\"א שאין הברכה מצוי' אלא בדבר הסמוי מן העין ולא בדבר המדוד והמנוי, וכמ\"ש בש\"ע או\"ח סי' ר\"ל ס\"ב<sup data-n=\"591\">4</sup>, והגם כי לא ספרו אותם בעצמם עכ\"ז ידעו מספרם ע\"י שקליהם כו'. אך הענין הוא דצ\"ל שרש ענין המספר והמנין, דהנה ארז\"ל במד\"ר שה\"ש ע\"פ שררך אגן הסהר<sup data-n=\"592\">5</sup> בענין בטנך ערימת חיטים, מה החיטים הללו כשיוצאין<sup data-n=\"593\">6</sup> לזרע אין יוצאין אלא במנין, וכשנכנסין מהגורן נכנסין במנין, כך כשירדו ישראל למצרים ירדו במנין שנאמר בשבעים נפש ירדו אבותיך מצרימה<sup data-n=\"594\">7</sup>, וכשעלו עלו במנין שנאמר כשש מאות",[["588","1","<b>כי תשא</b>: מכאן מתחיל המשך ה' מאמרים (הכולל ט\"ו פרקים), והם: א) ד\"ה זה (הכולל פרקים א—ג). ב) ד\"ה מונה מספר לכוכבי' (ד—ו (או) ד—ח). ג) ד\"ה שאו מרום עיניכם (ז—יא (או) ט—יא). ד) ד\"ה והי' מספר בנ\"י (פי\"ב (או) יב—יד). ה) ד\"ה כל העובר על הפקודי' (יג—טו (או) פט\"ו).\nלמאמר זה ראה אוה\"ת תשא ע' א'תתכג וע' א'תתכט. שמות ע' לג — לה. לקו\"ת ויקרא (א, ד. ב, רע\"א) פ\"ד. כמצויין בפרטיות לקמן.\nמאמר ד\"ה זה מתחיל ”כי תשא\", וכן נרשם בגוכתי\"ק כ\"ק אדמו\"ר מהר\"ש בהמפתח שבריש בוך זה, ששם נרשמו התחלת ההמשכים. אמנם בצדו השני של העמוד ששם נרשמו המאמרים (ולע\"ע לא נתברר מי רשמם אם זהו גוכתי\"ק או בכת\"י ר\"ש סופר או מעתיק אחר ), הנה תחלה נרשם מאמר ד\"ה: כי תשא את ראש בנ\"י ועליו הועבר קו וממעל לשורה רשם: לריח שמניך טובים. וכן הוא הפתיחא לקמן (בחלק ההנחות) בהנחת כ\"ק אדמו\"ר מהורש\"ב.\nההמשך נדפס מגוכתי\"ק כ\"ק אדמו\"ר מהר\"ש הנמצא בבוך 1089. ונמצא גם בכת\"י מעתיק הר\"ש סופר בבוך 2083 ונרשם לקמן: ב."],["589","2","<b>כי תשא. . איש כפר</b>: תשא ל, יב."],["590","3","<b>זה יתנו</b>: תשא שם, יג."],["591","4","<b>ארז\"ל. . סי' ר\"ל ס\"ב</b>: בשינוי לשון. לשון אוה\"ת תשא ע' א'תתכט. לקמן פי\"ג."],["592","5","<b>במד\"ר שה\"ש ע\"פ שררך אגן הסהר</b>: שה\"ש ז, ג (ג). ראה אוה\"ת שם ע' א'תתכג."],["593","6","<b>כשיוצאין</b>: שם כשהן יוצאין."],["594","7","<b>בשבעים נפש. . מצרימה</b>: עקב י, כב."]]],[2000450116,"אלף רגלי<sup data-n=\"595\">8</sup> כו', וי\"ל שרש ענין בחי' המספר הוא כמ\"ש גבי כוכבים שאו מרום עיניכם כו' המוציא במספר צבאם (ישעי' סי' מ\"ם ך\"ו), דהנה מצינו בדרז\"ל<sup data-n=\"596\">9</sup> ברבות ר\"פ שמות<sup data-n=\"597\">10</sup> שהשוון לכוכבים שאמרו שם שקולים הם ישראל כצבא השמים נאמר כאן שמות ונאמר בכוכבים שמות שנאמר מונה מספר לכוכבים<sup data-n=\"598\">11</sup> לכולם שמות יקרא כו' ולפי שהם משולים לכוכבים קרא שמות לכולם הה\"ד ואלה שמות בנ\"י<sup data-n=\"599\">12</sup> כו' וע' עוד מזה ברבות ר\"פ ויקהל ע\"פ לכולם בשם יקרא<sup data-n=\"600\">13</sup> כו' ראו קרא ה' בשם בצלאל<sup data-n=\"601\">14</sup> כו'. והענין דהנה מבואר בזהר תרומה דקע\"א ב' בענין הכוכבים<sup data-n=\"602\">15</sup> שמהם עיקר ההשפעה בעולם שאין לך עשב מלמטה שאין עליו כוכב ומזל כו', וכן ההארה באבנים טובות הוא מהכוכבים יעו\"ש באריכות ודקע\"ב ב'<sup data-n=\"603\">16</sup>, וא\"כ יש בו ב' בחי' הא' מה שמשפיע למטה, הב' מה שמקבל תחילה מלמעלה, שא\"א שישפיע למטה בלתי שיקבל תחילה מלמעלה, וכמ\"ש במ\"א שיש בכל עילה ג' בחי'<sup data-n=\"604\">17</sup> הא' מה שמקבל מלמעלה, וזהו בחי' העליונה שבו כמו בחי' חב\"ד, הב' בחי' עצמותו והוא בחי' האמצעית כמו חג\"ת, הג' מה שמשפיע למטה והוא מבחי' נה\"י שבו שהם כלי ההשפעה, וז\"ע לכולם שמות יקרא, דהנה הרמ\"ז ר\"פ פקודי<sup data-n=\"605\">18</sup> ע\"פ לכולם בשם יקרא, פי' שהמלאכים דבי\"ע הם מקבלים כח לפעול פעולתם והיינו ענין הקראם בשם שהוא קבלת כל אחד השפע לפי בחינתו ושרשו ובג\"כ אלה פקודי עכ\"ל, נמצא ענין לכולם שמות יקרא היינו ההשפעה ההשפעה<sup data-n=\"606\">19</sup> הנמשך להם ע\"י השם והאותיות אלו, וכפי בחי' ההשפעה כך הוא השם, וכמו שארז\"ל ברבות וישלח פע\"ח<sup data-n=\"607\">20</sup> לא כשם שנקרא עכשיו הוא נקרא אחר זמן שנאמר למה זה תשאל לשמי והוא פלאי<sup data-n=\"608\">21</sup>, דהיינו שהמלאך שנתראה למנוח ולאשתו שהי' בענין נזירות שמשון לכך נקרא שמו פלאי ע\"ש הנזירות שנאמר בו כי<sup data-n=\"609\">22</sup> יפליא<sup data-n=\"610\">23</sup> כו', והיינו כידוע ענין פלא, שהוא מה שמופלא ונעלם מהשכל שהוא בחי' א\"א<sup data-n=\"611\">24</sup> שמשם שרש הנזירות כמ\"ש בזהר בפ' נשא<sup data-n=\"612\">25</sup>, לכן",[["595","8","<b>כשש מאות אלף רגלי</b>: בא יב, לז."],["596","9","<b>בדרז\"ל. . אותיות התורה</b>: לשון אוה\"ת שמות ע' לג (בשינויים קלים). צויין אליו באוה\"ת שבהערה 5."],["597","10","<b>ברבות ר\"פ שמות</b>: פ\"א, ג."],["598","11","<b>מונה מספר לכוכבים</b>: תהלים קמז, ד."],["599","12","<b>ואלה שמות בנ\"י</b>: שמות א, א."],["600","13","<b>לכולם בשם יקרא</b>: ישעי' מ, כו."],["601","14","<b>ראו קרא ה' בשם בצלאל</b>: ויקהל לה, ל."],["602","15","<b>בזהר תרומה. . הכוכבים</b>: ראה גם אוה\"ת (יהל אור) תהלים ע' תקע."],["603","16","<b>ודקע\"ב ב'</b>: וכ\"ה בגוכתי\"ק כ\"ק אדמו\"ר הצ\"צ בבוך 1071 ע' כה. אבל באוה\"ת שמות כאן נדפס: ”וק\"ע ע\"ב\" ובהערה לשם כותב אולי צ\"ל: ודקע\"ב, א."],["604","17","<b>וכמ\"ש במ\"א שיש בכל עילה ג' בחי'</b>: באוה\"ת כאן בהערה מציין: ראה פרדס שער ב' פ\"ז."],["605","18","<b>הרמ\"ז ר\"פ פקודי</b>: ראה גם אוה\"ת שבהערה 15."],["606","19","<b>ההשפעה ההשפעה</b>: ב: ההשפעה."],["607","20","<b>ברבות וישלח פע\"ח</b>: ס\"ד (בשינוי קל)."],["608","21","<b>למה זה תשאל לשמי והוא פלאי</b>: ס' שופטים יג, יח."],["609","22","<b>נקרא שמו פלאי. . כי יפליא</b>: פי' ידי משה בב\"ר שם. כלי יקר נשא ו, ב. ראה גם אוה\"ת (יהל אור) תהלים ע' תקע ד\"ה רבות."],["610","23","<b>כי יפליא</b>: נשא ו, ב."],["611","24","<b>פלא. . א\"א</b>: ראה קול ברמה לאד\"ר קלב, א [ד\"ה מע\"ח הנה] מד, סע\"ב. ולהעיר מלקמן מאמר ד\"ה שיר המעלות ממעמקים ובהערה 8. ובהנחה שם על יד הערה 11."],["612","25","<b>א\"א. . הנזירות. . בזהר בפ' נשא</b>: ראה לקו\"ת שה\"ש לו, ד. ויקרא לב א ושם: ”בזהר פ' נשא דקכ\"ז ע\"ב ובלק\"ת שם בטעמי המצות\". אוה\"ח־ מק\"מ לזהר שם. סהמ\"צ להצ\"צ ע' קה (האריז\"ל. . דע\"ק). ע' קיג [בהוצאת תנש\"א ואילך — האריז\"ל]. אוה\"ת בראשית כרך ז תתשעב, ב [פי' האריז\"ל]. חוקת ע' תתיא. סה\"מ תרכ\"ט ע' קכד."]]],[2000450117,"המלאך שהלך בשליחות זאת נמשך לו השם מבחי' פלאי כו', וכענין מ\"ש ברבות פ' שמות פ\"ג<sup data-n=\"613\">26</sup> לפי מעשי אני נקרא כו', והנה ע\"י שמות אלו מקבל, ונמשך ג\"כ ההשפעה מהכוכב למטה, וזהו לכולם שמות יקרא לפי ההשפעה שמשפיע להם, וע\"כ כוכבים יש להם שמות, שעי\"ז מפורסם ענינים בעולם שמהם בא כל ההשפעות למטה כו'.\n<span data-k=\"ks\"><b>קיצור.</b> מה\"ע המספר הלא אין הברכה מצוי' כו' י\"ל ענין המספר כמ\"ש בכוכבים שהשוון המד\"ר לישראל, מונה מספר לכוכבים כו' שמות כו' כל ההשפעות הוא ע\"י הכוכבים ויש בהם ג' בחי', והשם הוא לפי ערך קבלתם והשפעתן וכענין למה תשאל לשמי והוא פלאי, לפי מעשי אני נקרא, שמות הכוכבים שעי\"ז מפורסם ענינם בעולם כו'.</span>\nב) <b>והנה</b> בלקו\"ת בד\"ה ויקרא<sup data-n=\"614\">27</sup> נת' שכוכבים הם למעלה מבחי' חמה<sup data-n=\"615\">29</sup> והם בבחי' רקיע תמינאה<sup data-n=\"616\">28</sup>, וזהו שארז\"ל במד\"ר פ' דברים<sup data-n=\"617\">30</sup> הכוכבים אינם מתביישים לע\"ל, משא\"כ חמה ולבנה כו' וחפרה הלבנה ובושה החמה<sup data-n=\"618\">31</sup>, וע\"כ שמות בנ\"י משלן לכוכבים שנאמר בהם שמות, וע' מענין כוכב במאו\"א אות ך'<sup data-n=\"619\">32</sup> דפי' כוכב היינו ךו ךב, פי' ך\"ו הוא מספר ש' הוי', והוא נמשך ע\"י ך\"ב כמשרז\"ל במד\"ר ע\"פ נגילה<sup data-n=\"620\">33</sup> ונשמחה בך, בך\"ב אותיות התורה, ועפ\"ז יובן מה שבסוכה צ\"ל כוכבים נראים מתוכה<sup data-n=\"621\">34</sup>, דהנה כתיב ואשים דברי בפיך<sup data-n=\"622\">36</sup> ובצל ידי כסיתיך, צל היינו בחי' מקיף עליון, וכנודע מענין סוכות צלא דמהימנותא<sup data-n=\"623\">37</sup> שהוא המשכת מקיפים עליונים וסוכה שחמתה מרובה מצילתה פסולה<sup data-n=\"624\">38</sup>, כי זהו כענין ההמשכה מבחי' ישת חשך",[["613","26","<b>ברבות פ' שמות פ\"ג</b>: ס\"ו."],["614","27","<b>בלקו\"ת בד\"ה ויקרא</b>: א, ד. ראה גם לקו\"ת ראה כז, ג בהחצע\"ג ”(ועמ\"ש במ\"א\". מאמרי אדה\"א דברים ח\"ד ע' א'רלא ואילך."],["615","29","<b>מבחי' חמה</b>: ברקיע הד' — לקו\"ת ראה שם. ראה רמב\"ם רפ\"ג מהל' יסוה\"ת. חגיגה יב, ב. מהרש\"א שם. פרדס שער סדר עמידתן ש\"ו, פ\"ג. ע\"ח שער לאה ורחל של\"ח, פ\"ג. לקוטי הש\"ס להאריז\"ל חגיגה ד\"ה: דע כי ז' רקיעים. שיחת כ' כסלו תשי\"ז אות לא."],["616","28","<b>שכוכבים. . רקיע תמינאה</b>: ראה לקו\"ת ראה שם. זהר ויצא קסב, ב. רמב\"ם רפ\"ג מהל' יסוה\"ת. חגיגה יב, ב. שיחה ופרדס שבהערה הבאה."],["617","30","<b>במד\"ר פ' דברים</b>: פ\"א, יד בשינוי לשון. וראה גם אוה\"ת תשא ע' א'תתכה ושם מציין: ברבות במדבר פ\"ב דף ריב ע\"ב [והוא בדפוס אמשטרדם ת\"א, ולפנינו פ\"ב, יג]. מים רבים תרל\"ו ע' קמז. וראה לקמן בפנים פ\"ח על יד הערה 214."],["618","31","<b>וחפרה הלבנה ובושה החמה</b>: ישעי' כד, כג."],["619","32","<b>מענין כוכב במאו\"א אות ך'</b>: ס\"ב. ראה גם אוה\"ת שבהערה 15."],["620","33","<b>במד\"ר ע\"פ נגילה</b>: שה\"ש א, ד ובשהש\"ר שם ג."],["621","34","<b>שבסוכה צ\"ל כוכבים נראים מתוכה</b>: ראה שו\"ע אדה\"ז הל' סוכה סתרל\"א, ס\"ה ועה\"ג שם: ירושלמי סוכה פ\"ב, ה\"ג. וראה גם לקו\"ש ברכה כרך ט ע' 231 בשולי הגליון שם."],["622","36","<b>ואשים דברי בפיך</b>: ישעי' נא, טז."],["623","37","<b>סוכות צלא דמהימנותא</b>: ראה זהר אמור קג, א. סידור שער הסוכות רנז, א. מאמרי אדה\"א דברים ח\"ד ע' א'רל. ע' א'שלה."],["624","38","<b>וסוכה שחמתה מרובה מצילתה פסולה</b>: סוכה ב, א במשנה."]]],[2000450118,"סתרו<sup data-n=\"625\">39</sup> שאינו נמשך רק בבחי' צל ומקיף ולא בבחי' אור וגילוי, וזהו ענני הכבוד כענין כי שכן עליו הענן<sup data-n=\"626\">40</sup>, אלא שכוכבים נראים מתוכה שהארת המקיף נמשך בפנימיות, ועד\"ז בעסק התורה נאמר ג\"כ ובצל ידי כסיתיך כי היא מבחי' מקיף כמ\"ש במ\"א בלק\"ת בד\"ה ביום השמע\"צ<sup data-n=\"627\">41</sup> שענין<sup data-n=\"628\">42</sup> לפי שמהבל הדבור נעשה מקיף לנשמה<sup data-n=\"629\">43</sup> כו' ע\"ש ובד\"ה וארשתיך לי<sup data-n=\"630\">44</sup> שז\"ע את ה' האמרת היום<sup data-n=\"631\">45</sup>, וע' מזה בד\"ה וידבר דבמדבר סיני באוהל מועד<sup data-n=\"632\">46</sup>, אך ע\"י השגת ועיון התורה שמשיג ג\"כ וקולט ההלכה במוחו ותבונתו עז\"נ מגלה עמוקות מיני חשך<sup data-n=\"633\">47</sup>, דהיינו שממשיך המקיף דישת חשך סתרו שהוא חשך והעלם להיות נמשך בבחי' גילוי אור ועז\"נ ותורה אור<sup data-n=\"634\">48</sup>, להיות אור א\"ס שורה למטה כמו למעלה<sup data-n=\"635\">35</sup>, ואפ\"ל שזהו בחי' גבוה יותר מכוכבים נראים מתוכה דסוכה שהוא רק כוכבים ונצוצים לבד מהמקיף אבל בתורה נאמר ותורה אור ממש היינו שמעצמיות המקיף מאיר הארה גדולה ועצומה בבחי' פנימיות, וע\"ד מ\"ש במ\"א גבי קרי\"ס דכתיב ויהי הענן והחשך ויאר<sup data-n=\"636\">50</sup> שהענין<sup data-n=\"637\">51</sup> דישת חשך סתרו בעצמותו ומהותו ממש נמשך בבחי' אור וגילוי, ועד\"ז י\"ל בענין פי' מגלה עמוקות מני חשך, דגבי תורה, וכעין זה מצינו בשמע\"צ שהוא שמחת תורה שהמקיפים דסוכות נמשכים בבחי' פנימיות, וכמ\"ש במ\"א ע\"פ בצלו חמדתי<sup data-n=\"638\">52</sup> וישבתי ופריו מתוק לחכי שז\"ע סוכות ושמע\"צ<sup data-n=\"639\">49</sup>, וכן גם בכוכבים נראים מתוכה שהארת המקיף נמשך בפנימיות י\"ל ג\"כ כוכב כ\"ו הוא ש' הוי' מאיר ע\"י ך\"ב בחי' אותיות התורה שע\"י מאיר בחי' המקיף כו', ועד\"ז<sup data-n=\"640\">53</sup> יובן בישראל שנמשלו לכוכבים נאמר בהם ואלה שמות בנ\"י שכמו בכוכבים ענין השמות הוא מה שעי\"ז נמשך להם השפע מלמעלה, וגם עי\"ז הם משפיעים למטה, וז\"ע שם שנודע שמו, וכענין הנזכר במשנה רפ\"ז דפיאה כל זית שיש לו שם בשדה כו' בשמו שהי' שפכני<sup data-n=\"641\">54</sup> היינו ששופך שמן הרבה<sup data-n=\"642\">55</sup> כו' ע\"ש, נמצא מה שנמשך ממנו שפע השמן או הזתים<sup data-n=\"643\">56</sup> בשפע רב נקרא שיש לו שם ולכן אין לו שכחה, כך עד\"ז ענין לכולם שמות יקרא, שיש להם שם ע\"י",[["625","39","<b>ישת חשך סתרו</b>: תהלים יח, יב. ראה גם מאמר ד\"ה בסוכות תשבו תרכ\"ב בפלח הרמון ויקרא."],["626","40","<b>כי שכן עליו הענן</b>: פקודי מ, לה."],["627","41","<b>בלק\"ת בד\"ה ביום השמע\"צ</b>: פד, ב."],["628","42","<b>שענין</b>: בלקו\"ת כאן א, ד: שהענין."],["629","43","<b>שמהבל הדבור נעשה מקיף לנשמה</b>: בלקו\"ת שבהערה 41 מציין: סד\"ה וארשתיך לי [שבהערה הבאה] ובזח\"א (בראשית דף ד' ע\"ב) ע\"פ ואשים דברי בפיך ובפי' הרמ\"ז שם. ראה גם פע\"ח שער התפלה ש\"א, פ\"ד. תו\"ח בשלח ח\"א קפא, ב הערה 782."],["630","44","<b>ובד\"ה וארשתיך לי</b>: לקו\"ת במדבר ח, ד פ\"ד."],["631","45","<b>את ה' האמרת היום</b>: תבוא כו, יז."],["632","46","<b>בד\"ה וידבר.. באוהל מועד</b>: לקו\"ת במדבר ב, ד."],["633","47","<b>מגלה עמוקות מיני חשך</b>: איוב יב, כב."],["634","48","<b>ותורה אור</b>: משלי ו, כג."],["635","35","<b>כתיב. . כמו למעלה</b>: לשון הלקו\"ת ויקרא א, ד פ\"ד בשינוים קלים."],["636","50","<b>ויהי הענן והחשך ויאר</b>: בשלח יד, כ. ראה מאמרי אדה\"ז תקס\"ח ח\"א ע' קעו ואילך."],["637","51","<b>שהענין</b>: ב ובלקו\"ת כאן: שהענן."],["638","52","<b>וכמ\"ש במ\"א ע\"פ בצלו חמדתי</b>: שה\"ש ב, ג. ראה מאמרי אדה\"ז תקע\"א ס\"ע דש ואילך."],["639","49","<b>ואפ\"ל. . סוכות ושמע\"צ</b>: לקו\"ת ויקרא ב, רע\"א בשינוים קלים."],["640","53","<b>ועד\"ז</b>: מכאן ועד סיום הפרק הוא לשון אוה\"ת שמות ס\"ע לג בשינויים קלים."],["641","54","<b>שפכני</b>: באוה\"ת כאן ניתוסף: או ביישני. וראה בסמוך הערה 56."],["642","55","<b>ששופך שמן הרבה</b>: פי' הרע\"ב שם."],["643","56","<b>או הזתים</b>: באוה\"ת כאן ליתא. וראה לעיל הערה 54."]]],[2000450119,"השפע היוצא מהם, והיינו ג\"כ ע\"י השם שקוראו בו הקדב\"ה שהוא השפע שנמשך לו ע\"י שם זה כנ\"ל בענין והוא פלאי, וע\"י שם זה הוא ג\"כ משפיע כמו שעי\"ז נמשך ע\"י מלאך הנ\"ל ענין נזירות שמשון, ועמ\"ש בלק\"ת בשה\"ש בד\"ה באתי לגני<sup data-n=\"644\">57</sup>, גבי אכלתי יערי עם דבשי, שם נז' מענין מה שהמלאכים הם שלוחי השפע, ועד\"ז הו\"ע ואלה שמות בנ\"י, ר\"מ הוה דייק בשמא<sup data-n=\"645\">58</sup>, והיינו כמו ראובן נק' כן ע\"ש ראו בן<sup data-n=\"646\">59</sup> בחי' ראי'<sup data-n=\"647\">60</sup> שהוא העבודה ע\"ד לאסתכלא ביקרא דמלכא<sup data-n=\"648\">61</sup> לעורר את האהבה, וע\"ד שנק' החכמים עיני העדה<sup data-n=\"649\">62</sup>, ועי\"ז מעורר ההשפעה ג\"כ בבחי' ראיה כמ\"ש כי ראה ה' בעניי<sup data-n=\"650\">63</sup>, וכמ\"ש עיני ה' אל צדיקים<sup data-n=\"651\">64</sup>, כמ\"ש מזה בת\"א בד\"ה יהודא אתה<sup data-n=\"652\">65</sup> ובלק\"ת בד\"ה לבבתני<sup data-n=\"653\">66</sup> באחד מעיניך, ובד\"ה יונתי בחגוי שלא נדפס בלק\"ת<sup data-n=\"654\">67</sup>, וכעד\"ז ענין שמעון לוי ויהודה כמ\"ש בד\"ה יהודה אתה הנ\"ל, נמצא השמות נקראו בהן ע\"ש פעולתם כמו ראובן בחי' ראי' עיני תמיד אל ה'<sup data-n=\"655\">68</sup>, שעי\"ז המשיך אור מלמעלה הנה עין ה' אל יראיו<sup data-n=\"656\">69</sup>, ובחי' זו נתגלה ומאיר בו, ועז\"נ טוב שם<sup data-n=\"657\">70</sup> כו', ודוגמא לזה מ\"ש ראו קרא ה' בשם בצלאל, בצלאל על שם חכמתו נקרא כו' עד בצל אל היית וידעת<sup data-n=\"658\">71</sup> כו'.\n<span data-k=\"ks\"><b>קיצור.</b> כוכבים אינם מתביישים, כוכב ך\"ו כ\"ב, כוכבים נראים מתוכה בחי' הארת המקיף בפנימיות, ותורה גילוי אור ע\"ד החשך שהאיר בקרי\"ס מגלה עמוקות מני חשך, וכמו בכוכבים ע\"י השם מקבלים ומשפיעים למטה כן שמות בנ\"י ראובן ראי' עיני תמיד, ממשיך עין ה' אל יראיו כו'.</span>\nג) <b>וזהו</b><sup data-n=\"659\">72</sup> דכתיב שמן תורק שמך<sup data-n=\"660\">73</sup>, ובמד\"ר נשא<sup data-n=\"661\">74</sup> בקרבן נחשון בן עמינדב גבי שניהם מלאים סולת בלולה בשמן<sup data-n=\"662\">75</sup> דקאי על שלמה ועל מ'<sup data-n=\"663\">76</sup> שיצא שמם",[["644","57","<b>בלק\"ת בשה\"ש בד\"ה באתי לגני</b>: לב, ב."],["645","58","<b>ר\"מ הוה דייק בשמא</b>: יומא פג, ב. ראה גם לקוטי אמרים להה\"מ סרמ\"ד־ או\"ת בראשית ב, כ (ה, ב). לקו\"ש כ\"ד טבת כרך ו ע' 36 בהערות."],["646","59","<b>ראובן. . ראו בן</b>: ראה פדר\"א פל\"ו. ב\"ר פע\"א, ג. ספר הגלגולים פל\"ד. תו\"א ויחי מה, א. ד. תו\"ח וארא ח\"א פד, סע\"ד. וש\"נ."],["647","60","<b>ראובן. . ראי'</b>: ראה תו\"א ותו\"ח שבהערה שלפנ\"ז."],["648","61","<b>לאסתכלא ביקרא דמלכא</b>: ראה זהר מקץ קצט, א. בראשית לח, א-ב. פקודי רמז, ב. תרומה קלד, א."],["649","62","<b>החכמים עיני העדה</b>: שלח טו, ד. ראה לקמן המשך חייב אדם לברך פ\"ח על יד הערה 246 שמציין ללקו\"ת ואתחנן ב, סע\"ד. ג, ג. מאמרי אדה\"ז על פרשיות התורה ח\"א ע' רסד ובהנסמן במ\"מ לשם. תו\"ח בא ח\"א קב, א ובהערה 248."],["650","63","<b>כי ראה ה' בעניי</b>: ויצא כט, לב."],["651","64","<b>עיני ה' אל צדיקים</b>: תהלים לד, יז."],["652","65","<b>בת\"א בד\"ה יהודא אתה</b>: ויחי מה, ב. ד. — כאן כתב: ”יהודא\" באל\"ף לבסוף, ואילו בסמוך בפנים נכתב בה\"א."],["653","66","<b>ובלק\"ת בד\"ה לבבתני</b>: שה\"ש כט, ג."],["654","67","<b>ובד\"ה יונתי בחגוי שלא נדפס בלק\"ת</b>: ראה מאמרי אדה\"ז תקס\"ט ע' פג־ הנחות הר\"פ ע' קס."],["655","68","<b>עיני תמיד אל ה'</b>: תהלים כה, טו."],["656","69","<b>הנה עין ה' אל יראיו</b>: תהלים לג, יח."],["657","70","<b>טוב שם</b>: קהלת ז, א."],["658","71","<b>בצלאל על שם חכמתו. . וידעת</b>: ברכות נה, א."],["659","72","<b>וזהו. . טוב שם</b>: לשון אוה\"ת שמות כאן ס\"ע לד ואילך פי\"ב בשינויים."],["660","73","<b>שמן תורק שמך</b>: שה\"ש א, ג."],["661","74","<b>ובמד\"ר נשא</b>: פי\"ג, יד."],["662","75","<b>שניהם מלאים סלת בלולה בשמן</b>: נשא ז, יג."],["663","76","<b>מ'</b>: במדרש ובאוה\"ת כאן: [מלך ה] משיח. ראה גם לעיל המשך אם כסף תלוה פי\"ד ובהערה 307."]]],[2000450120,"בעולם, טוב שם משמן הטוב<sup data-n=\"664\">77</sup>, שמן תורק שמך ע\"ש, ולכאורה אינו מובן דשני הפסוקים אינם שוין, דאומרו שמן תורק שמיך משמע מעלת השם שוה למעלת השמן, ואומרו טוב שם משמן משמע שהשם טוב יותר מהשמן, ואפ\"ל ע\"ד<sup data-n=\"665\">78</sup> מ\"ש אל יתהלל חכם בחכמתו<sup data-n=\"666\">79</sup> כו' כ\"א בזאת יתהלל המתהלל<sup data-n=\"667\">80</sup> כו', ומבמ\"א הפי' דיש ב' מדריגות בחכ'<sup data-n=\"668\">81</sup> הא' כמו שהיא למעלה באצי', הב' בחי' התפשטותה בבי\"ע בתורה ומצות, והתפשטות זו באה מבחי' שלמעלה מהחכמה כמ\"ש בת\"א בד\"ה לך לך<sup data-n=\"669\">82</sup>, וכענין חכמות בחוץ תרונה<sup data-n=\"670\">83</sup>, חכמות תרי, שההמשכה למטה באה ע\"י ח\"ס כו'<sup data-n=\"671\">84</sup> וכמ\"ש מזה בת\"א בד\"ה זכור<sup data-n=\"672\">85</sup> את יום השבת לקדשו ע\"ש, וזהו שמן תורק שמך פי' שמן תורק מה שמריקין השמן מכלי אל כלי ז\"ע המשכת וגילוי החכמה למטה, ולכן נק' שמן תורק דוקא שהורק ונמשך מח\"ע להיות נמשך ומתלבש למטה בתורה ומצות מעשיות, וא\"כ ענין שמן תורק שמך דכמו\"כ השם היינו מה שיוצא שמו בעולם למטה ע\"ד כי אני ה' בקרב הארץ<sup data-n=\"673\">86</sup>, וזהו עצמו ענין טוב שם מה שנמשך ומתגלה למטה בחי' ותעש לך שם<sup data-n=\"674\">87</sup>, משמן הטוב בעוד<sup data-n=\"675\">88</sup> למעלה, אלא כשהוא שמן תורק שהורק ונמשך למטה, וזהו כ\"א בזאת יתהלל כו', וענין שמן תורק שעצמיות ח\"ע והשמן הטוב הורק ונמשך למטה ולא שנמשך רק הארה ממנו, וזהו ע\"ד והריקותי לכם ברכה (מלאכי ג'<sup data-n=\"676\">89</sup> ) דהיינו מה שנמשך השפע בריבוי עצום מאד, וכן המריקים מעליהם הזהב (זכרי' ד'<sup data-n=\"677\">90</sup> ), וכ\"ה בילקוט ר\"פ יתרו בשם תנחומא<sup data-n=\"678\">91</sup> כאדם שמערה מפי חביות היית מערה לנו, שמן תורק שמך כו' וא\"כ זה מורה על ההמשכה בגילוי ממש למטה ע\"ד ותעש לך שם כו' ולא כמו החכ' שנמשך בעשרה מאמרות במע\"ב שבאה בבחי' השתלשלות שהאור הולך ומתמעט עד כי ומשם יפרד<sup data-n=\"679\">92</sup> שנעשה עלמא דפרודא כו', אבל שמן תורק כמערה מפי חביות, היינו שעי\"ז יומשך הגילוי למטה כמו למעלה ממש וכמ\"ש מזה סד\"ה משה ידבר בת\"א<sup data-n=\"680\">93</sup> שזהו ההפרש בין מה",[["664","77","<b>הטוב</b>: בכתוב [שבהערה 70] ובמדרש שם: טוב. אבל כ\"ה גם באוה\"ת כאן. ראה גם תו\"ח פקודי ח\"ב תמז, ד ובהערה 88."],["665","78","<b>ואפ\"ל ע\"ד</b>: באוה\"ת כאן בהערה: ראה לעיל ס\"ד — ע' יד ואילך."],["666","79","<b>אל יתהלל חכם בחכמתו</b>: ירמי' ט, כב."],["667","80","<b>כ\"א בזאת יתהלל המתהלל</b>: שם ט, כג."],["668","81","<b>ומבמ\"א. . ב' מדריגות בחכ'</b>: לעיל ע' יד [ראה הערה 78] מציין בהערה: ”נמצא בבוך תקס\"ח\" [— ראה מאמרי אדה\"ז הנחות הר\"פ ע' עט־ תקס\"ח ח\"א ס\"ע מב ואילך. ח\"ב ע' תשכו ואילך. ע' תשכח. אוה\"ת ויצא רז, ב. ירמי' כרך ב' ע' תתעח. ע' תתפ]. ”וראה ג\"כ שער האמונה פכ\"ה\"."],["669","82","<b>בת\"א בד\"ה לך לך</b>: יא, ג."],["670","83","<b>חכמות בחוץ תרונה</b>: משלי א, כ. ראה זהר תולדות קמא, ב. לקמן הערה 85."],["671","84","<b>ע\"י ח\"ס כו'</b>: באוה\"ת כאן בהערה מציין: ראה בזה לקו\"ת ס\"פ בהעלותך (השני). פ' עקב ד\"ה ואכלת ושבעת פ\"ג. תו\"ח בתחלתו."],["672","85","<b>בת\"א בד\"ה זכור</b>: יתרו ע, א."],["673","86","<b>כי אני ה' בקרב הארץ</b>: וארא ח, יח."],["674","87","<b>ותעש לך שם</b>: נחמי' ט, י."],["675","88","<b>בעוד</b>: באוה\"ת כאן: בעודו."],["676","89","<b>(מלאכי ג')</b>: פסוק י."],["677","90","<b>(זכרי' ד')</b>: פסוק יב."],["678","91","<b>בשם תנחומא</b>: ראה תנחומא יתרו ג [ובאבער] ב. פ' תבוא ג. יל\"ש שה\"ש א, ג רמז תתקפא בשם התנחומא."],["679","92","<b>ומשם יפרד</b>: בראשית ב, י."],["680","93","<b>סד\"ה משה ידבר בת\"א</b>: פ' יתרו סח, א ואילך."]]],[2000450121,"שקיים אברהם כל התורה<sup data-n=\"681\">94</sup> כולה עד שלא ניתנה שעיקר ההמשכה הי' למעלה באצי', אבל למטה נמשך ההמשכה רק מעט לא בערך מההמשכה שלמעלה, אבל ע\"י מ\"ת נמשך ההמשכה למטה ממש כמו למעלה, וזהו ההפרש בין לריח שמניך שנמשך למטה רק הריח לבד ועיקר ההמשכה הוא למעלה, ובין שמן תורק שעיקר ההמשכה הוא למטה ונק' שמן תורק שמך שזהו בחי' טוב שם (והגם שגם עכשיו להוסיף אורות באצי'<sup data-n=\"682\">95</sup> מ\"מ זהו בכדי שלע\"ל יתגלו למטה כו').\n<span data-k=\"ks\"><b>קיצור.</b> ענין שמן תורק דשייך לענין טוב שם, ע\"ד אל יתהלל כו' כ\"א בזאת, חכמות בחוץ, תורק כמערה מפי חביות שהגילוי למטה כמו למעלה, וזהו שמן תורק שהוא כמו טוב שם כו'.</span>",[["681","94","<b>שקיים אברהם כל התורה</b>: ראה יומא כח, ב. לקו\"ש תולדות כרך לה ע' 107 ואילך."],["682","95","<b>עכשיו להוסיף אורות באצי'</b>: ראה פע\"ח בהקדמה. ע\"ח שער מ\"ן ומ\"ד של\"ט, דרוש יא כלל טז. מאמרי אדה\"א דברים ח\"ד ע' א'תסז. וש\"נ. תו\"ח בשלח ח\"א קנו, ב הערה 312."]]],[2000450122,"<h3>מונה מספר כו'</h3>\n<b></b>ענין השם כו' ספר ד' שרשים כו' גויל ואותיות - (ד-וא\"ו) (ד-ח)\nד) <b>ולהבין</b><sup data-n=\"683\">96</sup> בתוס' ביאור ענין בחי' השם, אם<sup data-n=\"684\">97</sup> היות כי השם<sup data-n=\"685\">98</sup> אשר יקראו לאדם עד\"מ אברהם אין ערוך כלל לגבי עצמותו ומהותו של האדם ולכאורה אינו נוגע לו כלל, שהרי בפ\"ע א\"צ להשם כלל, עכ\"ז מתלבש החיות באותיות השם, וכמ\"ש בכלליות ענין השמות גבי אדה\"ר, ויבא אל האדם לראות מה יקרא לו וכל אשר יקרא לו האדם נפש חי' הוא שמו, ויקרא האדם שמות כו', (בראשית ב' י\"ט ך') הרי יש שייכות להשם עם עצם הדבר ואינו הסכמה בעלמא, וכמארז\"ל במד\"ר בראשית פי\"ז<sup data-n=\"686\">99</sup>, אני הוי' הוא שמי<sup data-n=\"687\">100</sup> הוא שמי שקרא לי אדם הראשון, וכמשנ\"ת מזה בכ\"ד באורך<sup data-n=\"688\">101</sup>. והוא ע\"ד מ\"ש בסש\"ב שער היחוד והאמונה ספ\"א, וזה שמו אשר יקראו לו בלה\"ק הוא כלי לחיות המצומצם באותיות שם זה שנשתלשל מעשרה מאמרות כו', ע\"ש. ועד\"ז בשם האדם הנה הנשמה עצמה קודם בואה בגוף אינה נקראת בשם כלל וכמ\"ש מזה בלק\"ת פ' בלק<sup data-n=\"689\">102</sup> בד\"ה מי מנה בפי'",[["683","96","<b>ולהבין</b>: ברשימת המאמרים שמופיע בריש הבוך נרשם כאן מאמר (ב' מההמשך) והוא ד\"ה: מונה מספר לכוכבי' (פרקים ד—ח. או כפי הנרשם לעיל במפתח המאמרים שבריש הספר (כנראה ע\"פ ב) פרקים ד—ו).\nלמאמר זה לפ\"ד — ראה לקו\"ת בהר מא, ג. וראה גם מאמרי אדה\"ז על פרשיות התורה ח\"א ע' רכב. אוה\"ת שמות ע' קג. לפ\"ה — ראה לקו\"ת שם מג, ב. לפ\"ו — ראה אוה\"ת תשא ע' א'תתכג. ע' א'תתלא. לקו\"ת שה\"ש מו, ג. לפ\"ז — ראה אוה\"ת תשא ע' א'תתכד. תו\"א מקץ לא, ד. לקו\"ת שה\"ש מ, סע\"ב ואילך. אחרי כז, א. אוה\"ת בשלח ע' תלג."],["684","97","<b>אם</b>: כ\"ה בכ\"מ — ראה לעיל המשך וידבר וגו' ויצוום פ\"ג ובהערה 50."],["685","98","<b>השם</b>: מכאן ועד התיבות: ”ועצמותה כו'\" שבסיום הפרק הוא לשון לקו\"ת בהר מא, ג בשינויים."],["686","99","<b>במד\"ר בראשית פי\"ז</b>: ס\"ד."],["687","100","<b>אני הוי' הוא שמי</b>: ישעי' מב, ח."],["688","101","<b>וכמשנ\"ת מזה בכ\"ד באורך</b>: ראה גם של\"ה בהקדמה בית אחרון יד, א. לקוטי אמרים להה\"מ סרמ\"ד־ או\"ת בראשית ב, כ (ד סע\"ב ואילך). מאמרי אדה\"ז על פרשיות התורה ח\"א ע' של ובהנסמן במ\"מ לשם. תו\"ח בא ח\"א קיג, ג ובהנסמן שם. סה\"מ תרכ\"ט ע' קלו ואילך. וש\"נ. תר\"ל ס\"ע סז ואילך. ע' צז. ע' רלו. תרל\"ו ע' כט. לקמן המשך חייב אדם לברך פכ\"ח. וש\"נ."],["689","102","<b>בלק\"ת פ' בלק</b>: סז, ג."]]],[2000450123,"ולאדם לא מצא עזר, והוא מהרמב\"ן<sup data-n=\"690\">104</sup> שם, פי' עזר הוא בחי' שם והיינו שהנשמה קודם בואה לעולם לגוף אינה נקראת בשם כלל, לפי שמקור חוצבה הוא בבחי' מחשבה עלמין סתימין דלא אתגליין, ומה שנק' אברהם יצחק הוא אחרי התלבשות הנשמה בגוף, וזהו אחד הי' אברהם (יחזקאל ל\"ג ך\"ד) פי' שקודם ביאת הנשמה לגופו הי' בבחי' אחד דהיינו בבחי' המחשבה שמתאחד עם הנפש והן הם בחי' עלמין סתימין שהם מתייחדים באוא\"ס ב\"ה<sup data-n=\"691\">103</sup> כו', ונמצא שהשם אינה לבחי' הנשמה עצמה, והרי גם להגוף עצמו אין השם מועיל, אך השם מקשר הנשמה בגוף והחיות הנמשך מהנשמה ומחי' הגוף הוא נרשם בהשם, דהיינו ראובן החיות שלו באותיות ריש אלף כו' כי הוא מבחי' ראי', וכמשנת\"ל בענין השמות ראובן שמעון כו'. והענין הוא דהנה כל דבר הגדול הצריך לצמצם א\"ע להחיות שלמטה הימנו הוא רק בבחי' שמו שלעצמו א\"צ שום שם רק בכדי להתגלות לאחרים צריך להשם, שכשמתגלה לאחרים אינו מתגלה לו בבחי' העצמיות כמו השכל רק בבחי' השם לבד, והנה נראה שהאותיות השם הם חומרים ואינם כלום רק שבו יש חיות מעט שמחי' את הגוף, והיינו כנודע שהאור והחיות המתפשט מהנשמה בגוף דהיינו החיות המתפשט בכל רמ\"ח איברים<sup data-n=\"692\">105</sup> שבגוף אין זה מהות ועצמיות שבנשמה ממש, אלא רק בחי' גילוי והארה ממנו, וכמ\"ש בסש\"ב פנ\"א, והמשכת הארה זו נשרש באותיות השם, לכן השם שייך דוקא בהתלבשות הנשמה בגוף שאז נמשך הארה מהנשמה להתפשט בגוף, וזהו ע\"י בחי' השם, משא\"כ קודם ירידתה בגוף הי' הארה זו כלולה במהותה ועצמותה בבחי' ביטול ממש ע\"כ אינה נקראת בשם כי השם הוא רק בחי' הארה כו', משא\"כ מהותה ועצמותה כו'<sup data-n=\"693\">106</sup>.\n<span data-k=\"ks\"><b>קיצור.</b> אם היות שהשם אינו נוגע עכ\"ז מתלבש החיות באותיות השם וכמ\"ש בסש\"ב, והנשמה קודם בואה לגוף אין לה שם כמ\"ש הרמב\"ן, והגוף ג\"כ אינו שייך לשם כ\"א התקשרות הארת הנשמה עם הגוף ז\"ע השם שבו נשרש הארה זו כו'.</span>\nה) <b>ושרש</b> הענין הוא כי<sup data-n=\"694\">107</sup> הנה השמות הם המחברים האורות עם הכלים פי' עד\"מ שם האדם שבו ועל ידו הוא פונה לקוראיו בשמו, אבל כשהוא בפ\"ע א\"צ לשמו כלל, נמצא ענין בחי' השם הוא שבו וע\"י ממשיכים אותו שיהי' נמשך ומתגלה, כמ\"כ יובן למעלה ענין השמות שהם מחברים האורות עם הכלים, וזהו בבחי' ע\"ס, והגם שבת\"א פ' בא<sup data-n=\"695\">108</sup> נת' דשאר השמות מלבד ש' הוי' הם בהכלים דע\"ס, אך מבואר במ\"א בשם הבעש\"ט נ\"ע<sup data-n=\"696\">109</sup> דאין ר\"ל שהשמות הם הכלים עצמן",[["690","104","<b>ולאדם לא מצא עזר. . מהרמב\"ן</b>: בראשית ב, יח."],["691","103","<b>ולאדם. . ב\"ה</b>: לשון הלקו\"ת בלק שם בשינויים."],["692","105","<b>רמ\"ח איברים</b>: אהלות פ\"א, מ\"ח."],["693","106","<b>ועצמותה כו'</b>: ראה הערה 98."],["694","107","<b>כי</b>: מכאן ועד לקמן תיבת ”בהכלי\" שעל יד הערה 110 הוא לשון הלקו\"ת בהר מג, ב בשינויים."],["695","108","<b>שבת\"א פ' בא</b>: ס, א."],["696","109","<b>בשם הבעש\"ט נ\"ע</b>: ראה גם לקו\"ת בהר שם. הוספות לויקרא נא, ג. מאמרי אדה\"ז על ענינים ע' שיח. אוה\"ת שמות ע' קו. יתרו ס\"ע תתמט ואילך. ויקרא כרך ב ע' תרצט. ענינים ע' רלח. סה\"מ עזר\"ת ע' קלא. כתר שם טוב קה\"ת מהדורת תשנ\"ט בהוספות עה\"פ ואתחנן ד, ז. וש\"נ. ד\"ה באתי לגני תשכ\"א הא' פ\"ב ופ\"ג. הב' פ\"ד ופ\"ו (סה\"מ באתי לגני ח\"א ע' קלה וע' קלו. ע' קמה וע' קמז). ”היום יום\" י\"א תשרי. ולהעיר מסה\"מ תרנ\"ה ע' נא ואילך."]]],[2000450124,"דהא הכלים הם המדות והשם קאי על הבורא עצמו שהוא עצמו כביכול נק' אל, אלא מ\"ש שהשמות הם בכלים פי' שהם בחי' החיות וההארה מאוא\"ס המלובש בהכלי ומחי' את הכלי כי הכלים יש להם חיות מאוא\"ס לבד האור המלובש בהם, וז\"ע שאר השמות שאינם נמחקים, אמנם ש' הוי' הוא המשכת האור בהכלי שמחבר וממשיך האור בהכלי<sup data-n=\"697\">110</sup>, וזהו בע\"ס, ועד\"ז נבין בענין שמות המלאכים שהוא בחי' התחברות בחי' הנפש המחי' הגוף שלהם, כי גם המלאכים יש להם גוף<sup data-n=\"698\">111</sup> רק שהם מב' יסודות אש ורוח לבד כמ\"ש עושה מלאכיו רוחות<sup data-n=\"699\">112</sup> משרתיו אש לוהט כו', והתחברות החיות שלהם עם הגוף זהו ע\"ד אור וכלי שהחיבור הוא ע\"י בחי' השם שז\"ע השליחות שלפי השליחות משתנה השם כנ\"ל, וז\"ע לכולם שמות יקרא כו'.\n<span data-k=\"ks\"><b>קיצור.</b> שהשם הוא המחבר האור עם הכלי, ובע\"ס חיות המחי' את הכלים זהו שאר השמות לבד ש' הוי', וש' הוי' הוא המחבר האור עם הכלי, ועד\"ז הוא במלאכים בחי' התחברות הנפש והגוף זהו ע\"י השם שהוא לפ\"ע השליחות כו'.</span>\nוא\"ו) <b>ומעתה</b> יובן ענין מונה מספר לכוכבים, דהנה במאו\"א<sup data-n=\"700\">113</sup> אות מם סעי' מם מספר הדעת כו' וכל מספר במל' כו', ויש להעיר מענין ספירות שהם ג\"כ ל' מספר<sup data-n=\"701\">*114</sup>, ואמנם אם הריבוי הוא למעלה יותר או למטה יותר יש בזה הפרש בין ריבוי האורות לריבוי הכלים, שהאורות הם למעלה בריבוי יותר<sup data-n=\"702\">114</sup> ולמטה מתמעטים, ולכן רבבות קדש הם בכתר<sup data-n=\"703\">115</sup>, ואלפים בחו\"ב<sup data-n=\"704\">116</sup> אאלפך חכ'<sup data-n=\"705\">117</sup> כו',",[["697","110","<b>בהכלי</b>: ראה לעיל הערה 107."],["698","111","<b>המלאכים יש להם גוף</b>: ראה לקו\"ת בהר מא, ב. מאמרי אדה\"א בראשית ע' קיב. וש\"נ. קונטרסים ע' רצב. וש\"נ. שע\"ת ו, ב. סה\"מ תרכ\"ו ע' כה. תרכ\"ז ע' תנה. מים רבים תרל\"ו פקט\"ז ע' קכא. לקמן המשך חייב אדם לברך פי\"א על יד הערה 362. סה\"מ ליקוט ח\"ב ע' פ (נדפס גם בסה\"מ תרס\"ג מהדורת תשנ\"ד ע' רח)."],["699","112","<b>עושה מלאכיו רוחות</b>: תהלים קד, ד."],["700","113","<b>במאו\"א. . בע\"ס</b>: לשון אוה\"ת תשא ע' א'תתכג עם הוספות ושינויים."],["701","*114","<b>ספירות. . ל' מספר</b>: ראה לקמן הערה 138."],["702","114","<b>שהאורות הם למעלה בריבוי יותר</b>: ראה ביאוה\"ז ח\"ש קלא, ד. תו\"ח שם קכו, ד. וישב רה, ד. מאמרי אדה\"א ויקרא ח\"ב ע' תתצב ואילך."],["703","115","<b>רבבות קודש הם בכתר</b>: ברכה לג, ב. ראה כסא מלך סתי\"ג אות ק. מאמרי אדה\"ז תקס\"ב ח\"א ע' לו. ע' מא. תקס\"ח ח\"א ע' תקכו-ז [ושם: האלפי' והרבבו\"ת. . עתיק וע\"י]־ לקו\"ת ברכה צג, ג [ושם: תענוג. . רבבה. . הרצון. . לאלפים]. ביאוה\"ז שם קלא, ג [ושם: ע\"י בריבואות וכמ\"ש ואתא מרבבות קודש]. שם קלב, א [ושם: בכתר. . אלפים ורבבות]. תו\"ח ח\"ש שם [ושם: ואלפים ורבבות בפנימית הכתר]. וישב הנ\"ל [ושם: דהאלפים ורבבות בכתר]. מאמרי אדה\"א ויקרא ח\"ב ע' תתצב [ושם: ואלפים ורבבות בבחי' ע\"י וא\"א]. אוה\"ת תשא ע' א'תתלא. יוה\"כ ע' א'תקסג. סה\"מ תרכ\"ו ס\"ע רנח ואילך."],["704","116","<b>ואלפים בחו\"ב</b>: ראה מאמרי אדה\"ז תקס\"ב שם. אוה\"ת תשא ע' א'תתלא. יוה\"כ ע' א'תקסג. סה\"מ תרכ\"ו ר\"ע רנט."],["705","117","<b>אאלפך חכ'</b>: נסמן לקמן הערה 183."]]],[2000450125,"והכלים הוא להיפך<sup data-n=\"706\">118</sup> שכל שלמטה מתרבים יותר, וז\"ע ריבוי צירופי אותיות במל' ונק' עיר אלקינו<sup data-n=\"707\">119</sup>, ובפרדס ערך מספר<sup data-n=\"708\">120</sup> כי המל' נק' מספר, והטעם כי הוא<sup data-n=\"709\">121</sup> חשבון ומספר כו' והיא המגלה אותם כו', וזהו ג\"כ מ\"ש בס\"י בשלשה ספרים<sup data-n=\"710\">122</sup> ברא הקב\"ה עולמו כו', ופי' הפרדס בשער י\"ב הוא שער הנתיבות פ\"א שהם חב\"ד<sup data-n=\"711\">*123</sup> כו'.\n<b>והנה</b> בשרש ספר יש ד' שרשים דרך פרט, הא' לשון מספר, וספרתם לכם ממחרת השבת<sup data-n=\"712\">123</sup> כו', איה סופר<sup data-n=\"713\">124</sup> כו', הב' לשון ספר זה ספר תולדות אדם<sup data-n=\"714\">125</sup>, הג' לשון ספור והגדה ולמען תספר באזני בנך<sup data-n=\"715\">126</sup>, ואספר מעשי יה<sup data-n=\"716\">127</sup>, הד' שם אבן טוב כמ\"ש כמראה אבן ספיר<sup data-n=\"717\">128</sup>, וז\"ע ע\"ס שנקראים כן ע\"ש שיש בהם כל בחי' הנ\"ל הא' מלשון אבן ספיר<sup data-n=\"718\">129</sup> שהוא לשון בהירות שאינם מסתירים על האור המלובש בהן, רק שהם כלים שבהם ועל ידם מתגלה האור כו', הב' לפמ\"ש בפרדס שער מהות והנהגה פ\"ב נק' ספירות ע\"ש ענין סיפור והגדה כענין השמים מספרים<sup data-n=\"719\">130</sup>, ור\"ל כמו שהדבור מגלה העלם המחשבה, כן ע\"י ע\"ס נמשך גילוי ההעלם של א\"ס ב\"ה בחי' ישת חשך סתרו כו', ועפ\"ז יובן מה שאמרו מצוה לספר ביציאת מצרים<sup data-n=\"720\">131</sup>, להיות כי ע\"י סיפור זה ממשיכים אור א\"ס בע\"ס, ודבור העליון נעשה מחשבה לתחתון<sup data-n=\"721\">132</sup> כמ\"ש במ\"א בפי' כאשר דברת לאמר<sup data-n=\"722\">133</sup>, וזהו רבות עשית<sup data-n=\"723\">134</sup> כו' עצמו מספר, שבעצמיות אור א\"ס לו דומי' תהלה<sup data-n=\"724\">135</sup>, נורא תהילות<sup data-n=\"725\">136</sup>, ומה שע\"ס מגלות אין ערוך אליך<sup data-n=\"726\">137</sup>, הג' נק' ספירות לשון מספר כמש\"ש בפרדס<sup data-n=\"727\">138</sup>, וכמ\"ש בס\"י עשר ספירות כו' במספר עשר אצבעות<sup data-n=\"728\">139</sup> כו', והגם דכתיב ולתבונתו",[["706","118","<b>והכלים הוא להיפך</b>: ראה תו\"א וישב הובא לקמן פ\"י ד\"ה ולבאר. לעיל הערה 114."],["707","119","<b>במל' ונק' עיר אלקינו</b>: תהלים מח, ב. ראה גם לעיל המשך וידבר וגו' ויצוום פי\"ג על יד הערה 239. מן תיבת ”שהאורות\" שעל יד הערה 114 עד כאן הוא לשון אוה\"ת תשא ע' א'תתלא."],["708","120","<b>ובפרדס ערך מספר</b>: שעה\"כ שכ\"ג, פי\"ג."],["709","121","<b>הוא</b>: בפרדס שם: היא. אבל כ\"ה גם באוה\"ת כאן. וירא תשלח, ב."],["710","122","<b>בשלשה ספרים</b>: ראה ס\"י בתחילתו."],["711","*123","<b>בשלשה ספרים. . שהם חב\"ד</b>: ראה גם סידור שחרית לשבת קעט, א. הובא לקמן במאמר ד\"ה פי' פתחה בחכמה על יד הערה 102-3."],["712","123","<b>וספרתם לכם ממחרת השבת</b>: אמור כג, טו."],["713","124","<b>איה סופר</b>: ישעי' לג, יח."],["714","125","<b>זה ספר תולדות אדם</b>: בראשית ה, א."],["715","126","<b>ולמען תספר באזני בנך</b>: בא י, ב."],["716","127","<b>ואספר מעשי יה</b>: תהלים קיח, יז."],["717","128","<b>כמראה אבן ספיר</b>: יחזקאל א, כו."],["718","129","<b>ע\"ס. . אבן ספיר</b>: ראה גם פרדס שבהערה 138. שיעור קומה להנ\"ל ס\"ב. לקו\"ת אמור לה, ב."],["719","130","<b>השמים מספרים</b>: תהלים יט, ב."],["720","131","<b>מצוה לספר ביציאת מצרים</b>: ראה הגדה של פסח סיום פיסקא עבדים היינו ובהנסמן לשם בהגדה עם לקוטי טעמים ומנהגים ע' טו."],["721","132","<b>ודבור העליון נעשה מחשבה לתחתון</b>: ראה גם מאמרי אדה\"א קונטרסים ע' תקמז. וש\"נ. תו\"ח וארא ח\"א עו, א. וש\"נ. סה\"מ תרכ\"ט ע' קז. וש\"נ."],["722","133","<b>כאשר דברת לאמר</b>: שלח יד, יז. ראה לקו\"ת שלח לט, סע\"ב. סע\"ד ואילך."],["723","134","<b>רבות עשית</b>: תהלים מ, ו."],["724","135","<b>לו דומי' תהלה</b>: ע\"פ תהלים סה, ב."],["725","136","<b>נורא תהילות</b>: בשלח טו, יא."],["726","137","<b>אין ערוך אליך</b>: תהלים מ, ו."],["727","138","<b>ספירות לשון מספר כמש\"ש בפרדס</b>: שער מהות וההנהגה ש\"ח, פ\"ב."],["728","139","<b>עשר ספירות כו' במספר עשר אצבעות</b>: וכ\"ה באוה\"ת כאן. יתרו ע' תשעב [ושם: הפרדס בחיבורו עסיס רמונים על הפרדס ש\"א פ\"א — אמנם בעסיס רמונים שם: מספר]. ויקרא כרך ב ס\"ע תקנז. ס\"י פ\"א, מ\"ב מנטובא שכ\"ב בסופה ע' קב. נוסח הרס\"ג [קאפח ירושלים תשל\"ב]. ר' אבוסהל דונש בן תמים [לונדון תרס\"ב ע' ז, אבל בפירושו ע' כד: מספר]. פ\"א, מ\"ג עם פי' הרח\"ו [ירושלים תשמ\"ח בס' כתבים חדשים לרח\"ו]. ראה ס\"י פ\"א, מ\"ג [ושם: מספר — וכ\"ה בלקו\"ת תצא לח, ד]. מנטובא שכ\"ב פ\"א, מ\"ב [ושם: כמספר]."]]],[2000450126,"אין מספר<sup data-n=\"729\">140</sup>, הנה מזה עצמו מובן מאחר שכ' אין מספר מוכרח שהוא בגדר מספר, אלא שמ\"מ לא יספר מרוב כל<sup data-n=\"730\">*141</sup>, משא\"כ עצמיות אוא\"ס הוא חד ולא בחושבן<sup data-n=\"731\">141</sup>, לפני אחד מה אתה סופר<sup data-n=\"732\">142</sup> כמ\"ש בביאור ע\"פ מי מנה<sup data-n=\"733\">143</sup> עפר יעקב.\n<b>ועוי\"ל</b> שהם נק' מספר שהם שרש הגבול כמ\"ש בענין שיעור קומה של יוצר<sup data-n=\"734\">144</sup> כו' רל\"ו אלפים רבבות פרסאות, ע' מזה בבה\"ז פ' פנחס<sup data-n=\"735\">145</sup> ובאגה\"ק סי' ך' ד\"ה איהו וחיוהי, ועמ\"ש מזה בתוס' לק\"ת<sup data-n=\"736\">146</sup> ד\"ה להבין מ\"ש באוצ\"ח, וזהו המוציא במספר צבאם<sup data-n=\"737\">147</sup> כמשי\"ת לקמן אי\"ה.\n<b>הד'</b> לשון ספרים שייך ג\"כ על הע\"ס כנ\"ל בענין בשלשה ספרים שפי' הפרדס<sup data-n=\"738\">148</sup> חב\"ד, וכמו בספר צ\"ל גויל מקיף כו' כמ\"כ בע\"ס יש ג\"כ בחי' אלו, דהנה ארז\"ל<sup data-n=\"739\">149</sup> כל אות שאין גויל מוקף לה<sup data-n=\"740\">150</sup> מארבע רוחותי' פסולה, כי ענין האותיות הוא לשון אתא<sup data-n=\"741\">151</sup> שבא דבר חדש והתהוות חדשה דהיינו שיתהוה מבחי' חסד דאצי' יהי רקיע<sup data-n=\"742\">152</sup> או שיתהוה מחכ' מדות נק' אותיות, וכמ\"כ שיתהוה מלמעלה מהדעת בחי' חכ' נק' ג\"כ אותיות אך שם הוא רק בחי' שערות שאין ערוך לעצמותו כלל, כמו שאם חותך השער אינו נוגע לעצמותו כלל ולא איכפת לי' כלל, רק שאעפ\"כ השערות הוא המשכה כל שהוא ממהותו, וזהו אבא יונק ממזלא<sup data-n=\"743\">153</sup> מזל הח' בחי' שערות כו', ומקור שרשן הוא בחי' גלגלתא<sup data-n=\"744\">154</sup> לבנוניות חסד דעתיק ומשם נמשך",[["729","140","<b>ולתבונתו אין מספר</b>: בתהלים קמז, ה: לתבונתו. ראה הנסמן לעיל בהמשך וידבר וגו' ויצוום פ\"ד הערה 59."],["730","*141","<b>כל</b>: אינו ברור בגוכתי\"ק. ב: כל. באוה\"ת כאן: כו'."],["731","141","<b>חד ולא בחושבן</b>: נסמן לקמן הערה 162."],["732","142","<b>לפני אחד מה אתה סופר</b>: ראה ס\"י פ\"א, מ\"ז. מאמרי אדה\"ז תקס\"ג ח\"ב ע' תשכב."],["733","143","<b>בביאור ע\"פ מי מנה</b>: לקו\"ת בלק ע, א."],["734","144","<b>בענין שיעור קומה של יוצר</b>: מובא לעיל בהמשך וידבר וגו' ויצוום פ\"ד על יד הערה 60 בשם פרקי היכלות, ומובא גם בשם: ס' היכלות־ ס\"י־ במ\"ר — ראה הנסמן באוה\"ת ואתחנן כרך ו ע' ב'רלג. שערי אורה לו, ב הערה 48. מאמרי אדה\"א נ\"ך ע' רס."],["735","145","<b>בבה\"ז פ' פנחס</b>: קיד, סע\"ד ואילך."],["736","146","<b>בתוס' לקו\"ת</b>: ויקרא בהוספות נד, א."],["737","147","<b>המוציא במספר צבאם</b>: ישעי' מ, כו. לקמן רפ\"ז."],["738","148","<b>לשון ספרים. . הפרדס</b>: ראה גם שיעור קומה שבהערה 129."],["739","149","<b>ארז\"ל</b>: מכאן ועד בסמוך תיבת שערות שעל יד הערה 155 הוא לשון לקו\"ת שה\"ש מו, ג רפ\"ג בשינויים."],["740","150","<b>כל אות שאין גויל מוקף לה</b>: מנחות כט, א. לד, סע\"א."],["741","151","<b>האותיות הוא לשון אתא</b>: ישעי' כא, יב. ראה מאמרי אדה\"א שמות ח\"א ע' קנח. וש\"נ. תו\"ח שמות ח\"א כה, ג. וש\"נ."],["742","152","<b>חסד דאצי' יהי רקיע</b>: בראשית א, ו. ראה לקמן ס\"ח ובהערה 199. מאמרי אדה\"א בראשית ע' רלד."],["743","153","<b>אבא יונק ממזלא</b>: ראה זהר אד\"ז האזינו רפט, ב. ע\"ח שער הכללים פ\"ה. תו\"ח שמות ח\"א לו, א הערה 455."],["744","154","<b>שערות. . שרשן. . גלגלתא</b>: ראה לקו\"ת כאן מו, ג ובציון הצ\"צ. תצא לח, ד."]]],[2000450127,"הארת שערות שיתהוה מזה בחי' חכ' דאצי' ראשית ומקור ההשתלשלות, וכמו באדם הגולגלת בעצם היא לבונה ומקפת על המוחין ומשם צומח שערות<sup data-n=\"745\">155</sup>, וז\"ע<sup data-n=\"746\">156</sup> האותיות שבתפילין והגויל כי ד' פרשיות הם ד' מוחין<sup data-n=\"747\">157</sup> קדש לי כל בכור חכ'<sup data-n=\"748\">158</sup> להיות נמשך ומתגלה למטה בחי' חכ' כדכתי' למען תהי' תורת ה' בפיך<sup data-n=\"749\">159</sup> עוסק בתורה לשמה להמשיך אורות בכלים, והי' כי יביאך מוח בינה<sup data-n=\"750\">160</sup> כו' והגויל הלבן המקיף את האותיות הוא בחי' גלגלתא לבנוניות אשר הוא מקיף ומקור למוחין כו', ועד\"ז הוא בבחי' ההמשכה ממוחין למדות כו'.\n<span data-k=\"ks\"><b>קיצור.</b> ענין ע\"ס יש בהם ד' בחי' סופר ספור מספר ספר, וגויל ואותיות שבספר.</span>\nז) <b>ועפי\"ז</b><sup data-n=\"751\">*161</sup> יובן ענין המוציא במספר צבאם, כי ע\"י בחי' ע\"ס נמשך שיהיו בבחי' מספר וגבול ותכלית, דהנה אנת הוא חד ולא בחושבן<sup data-n=\"752\">162</sup> כו' אנת הוא דאפיקת עשר תיקונין וקרינן להון עשר ספירין, דהנה ע\"ס הם ג\"כ רק בחי' כלים רק שהם בבחי' בהירות, וכנ\"ל בפי' ספירה ל' אבן ספיר, אבל אין ערוך כלל לבחי' אור א\"ס ב\"ה, וזהו ענין נפלאותיך ומחשבותיך אלינו<sup data-n=\"753\">163</sup>, אין ערוך אליך<sup data-n=\"754\">161</sup>, ופי'<sup data-n=\"e3\">*</sup> רבינו ז\"ל<sup data-n=\"755\">164</sup> רבות<sup data-n=\"756\">165</sup> כל דבר שהוא רב ועצום דהיינו עולמות העליוני' הגדולות והנוראות עשית בבחי' עשיי' גשמיות שנשתלשלו מעילה לעלול במדריגות רבות ושונות כמ\"ש בפסוק אגידה ואדברה עצמו מספר עד שנתהוה בחי' עשייה גשמיות, וכמ\"ש (תילים קל\"ה)<sup data-n=\"757\">166</sup> למה יאמרו איה אלקיכם<sup data-n=\"758\">167</sup> שהוא בבחי' איה, שהוא מובדל ומכוסה ורחוק מהם כמ\"ש רם על<sup data-n=\"759\">168</sup> כו', ולא ידעו ולא יבינו כי כל אשר",[["745","155","<b>שערות</b>: עכ\"ל הלקו\"ת. ראה הערה 149."],["746","156","<b>וז\"ע</b>: מכאן ועד סיום הפיסקא הוא לשון לקו\"ת שה\"ש כאן בשינוי."],["747","157","<b>ד' פרשיות הם ד' מוחין</b>: ראה זהר רע\"מ בא מג, ב. הנסמן במאמרי אדה\"א דברים ח\"ד ע' א'רמא."],["748","158","<b>קדש לי כל בכור חכ'</b>: בא יג, ב. ראה זהר ואתחנן רסב, א."],["749","159","<b>למען תהי' תורת ה' בפיך</b>: בא יג, ט."],["750","160","<b>והי' כי יביאך מוח בינה</b>: בא יג, יא. ראה זהר שם."],["751","*161","<b>ועפ\"ז</b>: ראה לקמן הערה 233."],["752","162","<b>אנת הוא חד ולא בחושבן</b>: ת\"ז בהקדמה יז, א. ראה שעה\"י קטז, ב. סה\"מ תרכ\"ז ע' קמז. וש\"נ."],["753","163","<b>נפלאותיך ומחשבותיך אלינו</b>: תהלים מ, ו."],["754","161","<b>המוציא. . אליך</b>: לשון אוה\"ת תשא ע' א'תתכד בשינויים."],["755","164","<b>ופי' רבינו ז\"ל</b>: בצד שמאלי של העמוד עה\"ג כאן נרשם בגוכתי\"ק [הובא בשולי היריעה כאן]: ”בת\"א ד\"ה מקץ השני\" לא, רע\"ד."],["756","165","<b>רבות</b>: מכאן ועד סיום הפיסקא בתיבת ”אלינו\" הוא לשון התו\"א הנ\"ל בשינויים."],["757","166","<b>(תילים קל\"ה)</b>: וכ\"ה גם בתו\"א כאן. בתהלים עט, י [ושם: למה יאמרו הגוים אי' אלקיהם]. שם קטו, ב [ושם: כנ\"ל, אי' נא]. יואל ב, יז [ושם: למה יאמר בעמים אי' אלקיהם]. ב: כתבו ומחקו."],["758","167","<b>למה יאמרו איה אלקיכם</b>: ראה הערה שלפנ\"ז. ב: מתחילה כתב כנ\"ל, והוסיף בין השיטין תיבת: ”הגוים\" ותיקן תיבת אלקיכם ”אלקיהם\"."],["759","168","<b>רם על</b>: תהלים קיג, ד. ראה גם מאמרי אדה\"ז על פרשיות התורה ח\"א ע' רל. ובהנסמן במ\"מ לשם. מאמרי אדה\"א דברים ח\"ג ס\"ע לג ואילך. וש\"נ."],["e3","*","<b>בצד השמאלי של הע' בשורה ראשונה שבה מופיעים התיבות ”ופי' רבינו ז\"ל\" נרשם</b>: בת\"א ד\"ה מקץ השני."]]],[2000450128,"חפץ ה'<sup data-n=\"760\">169</sup> עשה שנשתלשל בחי' חפץ ה' כ\"כ עד שהוא בעשייה גשמיות, וכ\"כ למה כדי שיהי' ה' אלקי פי' אלקה שלי ע\"י כי נפלאותיך ומחשבותיך אלינו כי אורייתא מחכמה נפקת<sup data-n=\"761\">170</sup> פי' עיקר התגלותה הוא מחכמה, אבל באמת הוא רצונו<sup data-n=\"762\">171</sup> של מקום והוא ורצונו אחד<sup data-n=\"763\">172</sup>, וזהו נפלאותיך מה שהוא מופלא ומובדל ומכוסה שאין בו השגה כלל בחי' פלא עליון, ומחשבותיך שהוא בחי' חכ' עילאה נמשך אלינו על ידי התורה, אין ערוך אליך אגידה ואדברה עצמו מספר כי להיות השתלשלות וירידה גדולה כ\"כ מבחי' גבוה ונעלה מאד, עד בחי' מטה מטה מאד הוצרך להיות כמה מיני עולמות אין מספר מינים ממינים שונים, וכמ\"ש היש מספר לגדודיו<sup data-n=\"764\">173</sup> וכתי' אלף אלפים ישמשוני'<sup data-n=\"765\">174</sup> וריבוי רבבין קדמוהי כו' והוא מספר גדוד והיכל אחד, והיכלות אין מספר, ואעפ\"כ כולם אין ערוך אליך שאפי' בחי' הגבוה מאד שהוא שרש התחלות ההתהוות מ\"מ לגבי מהותו ועצמותו ית' אין ערוך לו כלל שאינו מערכו ולא ממהותו כלל מאחר שהוא בבחי' נברא או נאצל ויש לו התחלת גבול, משא\"כ בבורא ית' דכולא קמי' כלא ממש חשיבא<sup data-n=\"766\">175</sup>, ואצלו נחשב הכל כאין בחי' הראשונה ובחי' האחרונה שבמדריגה התחתונה הכל שוה אצלו, ואעפ\"כ להיות השתלשלות העולמות וירידות המדריגות הוצרך להיות מדריגות עצמו מספר, שלא יבטלו ממציאותן, וכ\"ז הוא בשביל שיהי' ה' אלקי, ונפלאותיך ומחשבותיך אלינו כו'.\n<b>ובמ\"א</b><sup data-n=\"767\">176</sup> פי'<sup data-n=\"e4\">*</sup> לענין שהבריאה אינו עו\"ע ח\"ו שע\"ז<sup data-n=\"768\">177</sup> אמר דהע\"ה רבות עשית כו' אין ערוך אליך, כי כל העולמות אינם פועלים שום שינוי בו ית', וכמאמר אתה הוא קודם שנה\"ע<sup data-n=\"769\">178</sup> ואתה הוא משנברא כו', ר\"ל בשוה בלי שינוי כמ\"ש אני הוי' לא שניתי<sup data-n=\"770\">179</sup>, והיינו משום שהעולמות אין ערוך כלל להבורא ית',",[["760","169","<b>כל אשר חפץ ה' עשה</b>: תהלים קלה, ו."],["761","170","<b>אורייתא מחכמה נפקת</b>: זהר בשלח סב, א. יתרו פה, א. רע\"מ משפטים קכא, א. קדושים פא, א. חוקת קפב, א. ואתחנן רסא, א."],["762","171","<b>אורייתא. . הוא רצונו</b>: ראה גם לקמן המשך חייב אדם לברך פכ\"ב: ויהי קול. . שבועות תקנ\"ה. מאמר ד\"ה ואשא אתכם על יד הערות 37-8. ד\"ה פי' פתחה בחכמה על יד הערה 19. ובחלק ההנחות ד\"ה ואשא אתכם על יד הערה 90-1. ד\"ה פי' פתחה בחכ' על יד הערה 23. מאמרי אדה\"א ויקרא ח\"ב ע' תסא. וש\"נ. דברים ח\"ג ע' תתנ. (נ\"ך ע' רסג)."],["763","172","<b>והוא ורצונו אחד</b>: ראה תניא פל\"ח [נ, ב]. פ\"מ [נד, ב. נה, סע\"א]."],["764","173","<b>היש מספר לגדודיו</b>: איוב כה, ג."],["765","174","<b>אלף אלפים ישמשוני'</b>: דניאל ז, י. ראה חגיגה יג, ב. לקמן בפנים על יד הערה 209."],["766","175","<b>דכולא קמי' כלא ממש חשיבא</b>: ראה זהר בהקדמה יא, ב. ראשית חכמה שער היראה ש\"א, פ\"ז [ז, רע\"א]. מאמרי אדה\"ז תקס\"ו ע' שמא. מאמרי אדה\"א דברים ח\"ב ע' תרנג."],["767","176","<b>ובמ\"א</b>: בצד הימיני של העמוד עה\"ג כאן נרשם בגוכתי\"ק [הובא בשולי היריעה כאן]: ”בד\"ה ששים המה דה\"ש\" לקו\"ת שה\"ש מ, סע\"ב ואילך."],["768","177","<b>שע\"ז</b>: מכאן ועד סיום הפיסקא הוא לשון הלק\"ת הנ\"ל בשינוי."],["769","178","<b>אתה הוא קודם שנה\"ע</b>: ראה תפלת השחר. של\"ה ג, ב. מאמרי אדה\"ז מארז\"ל ע' שלו."],["770","179","<b>אני הוי' לא שניתי</b>: מלאכי ג, ו."],["e4","*","<b>בצד הימין של העמוד אצל הפיסקא ובמ\"א נרשם בגוכתי\"ק</b>: בד\"ה ששים המה דה\"ש."]]],[2000450129,"ואפי' לגבי החיות הנמשך להן ממחשבתו ית' והתהוותם ע\"י בחי' דילוג וצמצום ולא בבחי' עו\"ע ח\"ו, ולכן כלא ממש חשובים קמי' ית' וכמו קודם שנה\"ע ממש, וזהו נפלאותיך ומחשבותיך אלינו, פי' שע\"י מחשבתו ית' נעשה התהוות והשתלשלות העולמות, וז\"ש רבות עשית אתה ה' אלקי נפלאותיך ומחשבותיך אלינו ר\"ל שריבוי העולמות והברואים כולם נתהוו ע\"י מחשבתו ית', אך אעפ\"כ אין ערוך אליך ממש היינו שהתהוות העולמות ממחשבתו ית' אינו בבחי' עו\"ע רק שהם אין ערוך ממש לגבי מחשבתו ית' המהוה ומחי' אותם מאין ליש, אגידה ואדברה עצמו מספר פי' כי מאחר שהוא ית' אין סוף א\"כ אם הי' התהוות העולמות ממחשבתו ית' ע\"י השתלשלות עו\"ע לא הי' כלל העולמות בבחי' גבול ותכלית כמו שהן עתה אלא הי' הכל א\"ס בלי גבול, וזהו נפלאותיך ומח' אלינו אין ערוך אליך אגידה ואדברה כו' שההמשכה ממחשבתו ית' אלינו הוא ע\"ד שאין ערוך ממש ולא בבחי' עו\"ע ח\"ו.\n<b>ובמ\"א</b><sup data-n=\"771\">180</sup> פי' על התו' שכל פרטי ההלכות שבתורה הם<sup data-n=\"772\">181</sup> המשכות מבחי' שערות בלבד שהם הארה מצומצמת ומועטת מעט מזעיר ע\"י צמצומים רבים כמ\"ש נפלאותיך ומחשבותיך אלינו אין ערוך אליך אגידה ואדברה עצמו מספר שלהיות המשכת נפלאותיך ומחשבותיך אלינו בעסק התורה שלפנינו המלובשת בגשמיות עצמו מספר הצמצומים רבים ריבוא רבבות מדריגות עד אין מספר, כי אין ערוך אליו ית' כלל, וכמו שנודע פי' ערך במספר שאפילו אחד לגבי אלף אלפים וריבוא רבבות נק' בשם ערך שהם מסוג אחד שהכל נופל תחת סוג המספר, משא\"כ לגבי אוא\"ס ב\"ה שכשמו כן הוא אין לו סוף כו' לא שייך ערך כלל.\n<b>ובמ\"א</b><sup data-n=\"773\">182</sup> פי' נפלאותיך המה המשכות חו\"ב שמופלאים הם ונמשכים מפלא עליון בחי' כתר כמ\"ש אאלפך חכ'<sup data-n=\"774\">183</sup>, ומחשבותיך הם המשכות חו\"ב למדות דאצי' כו' הכל הוא רק בשביל צמצום הנבראים בגין דישתמודעין לי'<sup data-n=\"775\">184</sup>, וזהו נפלאותיך ומחשבותיך אלינו שלגבי ערכינו השפל נקראים נפלאותיך ומחשבותיך, אבל לגבי בחי' העצמיות אוא\"ס ה\"ה אין ערוך כלל, וזהו אין ערוך אליך לפי<sup data-n=\"e5\">*</sup><sup data-n=\"e6\">*</sup>",[["771","180","<b>ובמ\"א</b>: בצד הימיני של העמוד בסופו עה\"ג כאן נרשם בגוכתי\"ק [הובא בשולי היריעה כאן]: ”כי ביום הזה דה\"ש באחרי\" לקו\"ת אחרי כז, א."],["772","181","<b>הם</b>: מכאן ועד סיום הפיסקא הוא לשון לקו\"ת הנ\"ל בשינוי."],["773","182","<b>ובמ\"א</b>: בצד שמאלי של העמוד עה\"ג כאן נרשם בגוכתי\"ק [הובא בשולי היריעה כאן]: ”בד\"ה וירא ישראל את היד שלא נדפס\" אוה\"ת בשלח ע' תלג בשינויים."],["774","183","<b>אאלפך חכ'</b>: איוב לג, לג [ושם: ואאלפך — ראה אוה\"ת כאן. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תתקמו הובא לקמן במאמר ד\"ה שיר המעלות ממעמעקים על יד הערה 18. הנסמן במאמרי אדה\"א ויקרא ח\"א ע' טו]."],["775","184","<b>בגין דישתמודעין לי'</b>: ראה זהר רע\"מ בא מב, ב."],["e5","*","<b>נרשם בשולי העמוד כאן בגוכתי\"ק</b>: כי ביום הזה דה\"ש באחרי."],["e6","*","_<b>נרשם בצד שמאלי של העמוד כאן בגוכתי\"ק</b>: בד\"ה וירא ישראל את היד שלא נדפס."]]],[2000450130,"שבאמת הוא מובדל בערך מבחי' חו\"ב כו' דהא לית מח' תפיסא בי' כלל<sup data-n=\"776\">185</sup>, וכידוע דבראשית נמי מאמר הוא<sup data-n=\"777\">186</sup>, וע' בלק\"ת בד\"ה האזינו דרוש הראשון<sup data-n=\"778\">187</sup>, וזהו משארז\"ל בגמ' רפ\"ב דחגיגה<sup data-n=\"779\">188</sup> בעשרה דברים נבה\"ע בחכמה ובתבונה כו' שנאמר ה' בחכמה יסד ארץ<sup data-n=\"780\">189</sup> כונן שמים כו' פי' ביו\"ד ספירות העליונות דאצי' חכ' ותבונה נבראו העולמות דבי\"ע, וע' בפרדס שער השני פ\"ד וספ\"ה מענין ע\"מ, אך גם יו\"ד מאמרות אלו נאצלו מעצמיות בחי' אוא\"ס ב\"ה בריבוי צמצומי' מפני שאין ערוך להם אליך כו', ולהיות כן ניתנו יו\"ד הדברות כללות המצות להיות מחמתם סיבה לבוא לידי צמצומים להאציל אורות הי\"ס הנ\"ל הנק' יו\"ד מאמרות בכלים שונים כו' תמיד וכולם להיות נפלאותיך ומח' אלינו כו', וז\"ע עשרה עשרה הכף שעשה\"ד מכוון כנגד ע\"מ<sup data-n=\"781\">190</sup> כמ\"ש במ\"א, וע' בזח\"ג ויקרא די\"א סע\"ב.\n<span data-k=\"ks\"><b>קיצור.</b> ע\"ס כדי שיהי' בחי' מספר, כלים רק שהם בהירות אבל אין ערוך, וזהו נפלאותיך כו' אלינו רבות עשית קאי על כל העולמות עליונים ותחתונים שאין ערוך אליך ועצמו מספר הצמצומים וכ\"כ למה בכדי שיהי' נפלאו' ומח' אלינו ע\"י התורה, וכל ריבוי העולמות אינם פועלים שום שינוי ח\"ו שאינם בחי' עו\"ע כ\"א ע\"י מח' לבד ולכן אין ערוך אליך, ובמ\"א פי' גם על הלכות שבתו' שלהיות המשכת נפלאו' כו' אלינו עצמו מספר הצמצומי', וגם מה שהם נפלאותיך כו' זהו רק אלינו ר\"ל לגבינו אבל אין ערוך אליך כו'.</span>\nח) <b>והנה</b> מה<sup data-n=\"782\">191</sup> שנמשכו בחי' עשר ספירות דוקא זהו מפני שכך עלה ברצונו, אבל בעצמותו ית' לפני אחד מה אתה סופר כו', והכתר הוא הממוצע המחבר א\"ס ב\"ה לע\"ס, ויש בו שני בחי' היינו בחי' תחתונה שבמאציל ושרש הנאצלים<sup data-n=\"783\">192</sup>, שמצד פנימיותו שהוא הבחי' תחתונה שבמאציל אומר חד ולא בחושבן כו' ופשוט בתכלית, ולכן זה שיומשך ריבוי הנבראים זהו לפי שנמשכו ע\"י ע\"ס, וכמ\"ש מה רבו מעשיך ה' כולם בחכמה עשית<sup data-n=\"784\">193</sup> והיינו כי מחכמה נמשך ע\"י המדות חסד דרועא ימינא גבורה דרועא שמאלא<sup data-n=\"785\">194</sup> שהן בחי' מחולקות ושונות, ות\"ת מכריע<sup data-n=\"786\">195</sup> בינתיים,",[["776","185","<b>לית מח' תפיסא בי' כלל</b>: ת\"ז בהקדמה יז, א."],["777","186","<b>דבראשית נמי מאמר הוא</b>: בראשית א, א. ר\"ה לב, א."],["778","187","<b>בלק\"ת בד\"ה האזינו דרוש הראשון</b>: עב, ג."],["779","188","<b>בגמ' רפ\"ב דחגיגה</b>: יב, א."],["780","189","<b>ה' בחכמה יסד ארץ</b>: משלי ג, יט."],["781","190","<b>שעשה\"ד מכוון כנגד ע\"מ</b>: ראה זהר יתרו צג, ב. ויקרא יא, ב. מאמרי אדה\"א דברים ח\"א ע' רפ. וש\"נ. תו\"ח וארא ח\"א פא, ג ובהערה 636. סה\"מ תרכ\"ו ע' קלח. תרכ\"ז ע' רמח. מאמר ד\"ה וידבר אלקים. . אנכי ב' דשבועות תשכ\"ב. ד\"ה וכל בניך ש\"פ וישלח תשכ\"ז."],["782","191","<b>מה</b>: מכאן ועד רפ\"ט לשון אוה\"ת תשא ע' א'תתכד-ה בשינוי."],["783","192","<b>והכתר הוא הממוצע. . הנאצלים</b>: ראה ע\"ח שער דרושי אבי\"ע שמ\"ב, פ\"א. מאמרי אדה\"א ויקרא ח\"ב ע' תס. וש\"נ. תו\"ח שמות ח\"א יא, ג. וש\"נ. סה\"מ תרכ\"ז ע' שמח."],["784","193","<b>מה רבו. . בחכמה עשית</b>: תהלים קד, כד."],["785","194","<b>חסד דרועא. . שמאלא</b>: ת\"ז בהקדמה יז, א."],["786","195","<b>ות\"ת מכריע</b>: ראה ע\"ח שער פרטי עי\"מ שכ\"ז, פ\"ב. שעה\"י קכד, ב ובהערה 32."]]],[2000450131,"ולכן נק' ספירות לשון מספר שהרי הן בחי' שונות שיפול עליהם המספר חסד בחי' אחת גבורה בחי' שנית כו', ומהתכללות הו\"ק נעשה י\"ב גבולי אלכסון<sup data-n=\"787\">196</sup> כו', ולכן מזה נמשך ריבוי ההתחלקות הנבראים כי מן החסד נמשך אור<sup data-n=\"788\">197</sup> מים<sup data-n=\"789\">198</sup> כו' ומבחי' גבורה נמשך יהי רקיע<sup data-n=\"790\">199</sup> כו', וכן שרש ז' כוכבי לכת שרשן משבעה מדות<sup data-n=\"791\">200</sup> כו', וכן שרש י\"ב מזלות שרשן מי\"ב גבולי אלכסון כמ\"ש בפרדס שך\"א פ\"ז<sup data-n=\"792\">201</sup> בענין י\"ב גבולי אלכסון שכנגדן י\"ב מזלות בעולם וי\"ב חדשים בשנה וכן י\"ב כוחות בנפש<sup data-n=\"793\">202</sup> והם עולם שנה נפש וסימנך עש\"ן כמ\"ש בס\"י עכ\"ל<sup data-n=\"794\">203</sup>. וזהו כי אראה שמיך<sup data-n=\"795\">204</sup> מעשה אצבעותיך כמו המחלק דבר או כותב אותיות שונות זמ\"ז שהוא ע\"י האצבעות והן ע\"ס במספר עשר אצבעות<sup data-n=\"796\">205</sup> כו', ועמ\"ש מזה בת\"א פ' וארא בד\"ה וידבר אלקים וארא<sup data-n=\"797\">206</sup> כו', ובמ\"א בביאור ע\"פ ואלה שמות בנ\"י<sup data-n=\"798\">207</sup>.\n<b>והנה</b> בזח\"א בהקדמה דף ב' סע\"א במספר ס\"ר אינון דקיימין כחדא ואפיקו חילין לזינייהו דלית לון חושבנא כו', ופי' בסה\"מ סי' ס\"ח דששים רבוא הם ו\"ק דז\"א והחיילים הם כל שאר הנמצאים שלמטה הימנו כו' והוא ע\"ד מ\"ש במ\"א ע\"פ גדול אדונינו<sup data-n=\"799\">208</sup> ורב כח ולתבונתו אין מספר, אלף אלפים מספר גדוד אחד ולגדודיו אין מספר<sup data-n=\"800\">209</sup>, שכל גדוד יניקתו ממדה א' פרטית מו\"ק דז\"א מה שמתכללים זע\"ז כמו חסד שבחסד שבגבורה כו', ומגדוד ומדה זו כשנמשכה ע\"י הדבור שהוא מל'<sup data-n=\"801\">210</sup> נעשה בבי\"ע אלף אלפים מלאכים כו', ופי' ולגדודיו אין מספר היינו ע\"ד",[["787","196","<b>ומהתכללות. . י\"ב גבולי אלכסון</b>: ראה ס\"י פ\"ה, מ\"א. ס' הבהיר סמ\"ב. ונמנו בפרדס שער פרטי השמות שכ\"א פ\"ו-ח. שה\"א עג, א. שע\"ת צב, ג הערה 34. מכתב כ\"ח טבת תש\"ח נדפס באג\"ק כ\"ק אדמו\"ר ח\"ב ס\"ע רצ ואילך."],["788","197","<b>החסד נמשך אור</b>: ראה גם אוה\"ח לזהר בראשית מו, א. מאמרי אדה\"א דברים ח\"ד ע' א'תמו. וש\"נ. תו\"ח תצוה ח\"ב שיט, א. וש\"נ."],["789","198","<b>החסד. . מים</b>: ראה זהר תרומה קסז, א. קעה, ב. שמיני מא, א. מאמרי אדה\"א דברים ח\"ד ע' א'שצב."],["790","199","<b>גבורה נמשך יהי רקיע</b>: ראה לעיל ס\"ו ובהערה 152. המשך מים רבים תרל\"ו ע' כו. לקמן (בחלק ההנחות) מאמר ד\"ה כי המצוה על יד הערה 25."],["791","200","<b>ז' כוכבי לכת שרשן משבעה מדות</b>: ראה ס\"י פ\"ד, מ\"ד ואילך הובא באוה\"ת חנוכה ח\"ב רעח, ב. כסא מלך לת\"ז תי\"ח [נז, ב ואילך] אות ה ואילך."],["792","201","<b>י\"ב מזלות. . בפרדס שך\"א פ\"ז</b>: אוצ\"ל: פ\"ו. באוה\"ת כאן: ”ש\"ך, פ\"ד\". בראשית טו, א: ”שער כ' פרק שביעי\". טז, א: שער פרטי השמות — הוא שער כ\"א. וראה אוה\"ת ויצא ע' ריב. וארא ע' רכב. מסעי ע' א'שסז: בפרדס שער עשרים הוא שער השמות."],["793","202","<b>י\"ב כוחות בנפש</b>: מובא גם באוה\"ת כאן. בראשית טז, א."],["794","203","<b>עכ\"ל</b>: ראה הערות ותיקונים לתניא לדף פג, א."],["795","204","<b>כי אראה שמיך</b>: תהלים ח, ד. ראה גם אוה\"ת שה\"ש ח\"ב ע' תקמט ואילך וע' תקנד. סה\"מ תרכ\"ו ע' רכב. תר\"ל ע' רסו."],["796","205","<b>ע\"ס במספר עשר אצבעות</b>: ס\"י פ\"א, מ\"ג."],["797","206","<b>בת\"א. . וארא</b>: נו, ב."],["798","207","<b>בביאור ע\"פ ואלה שמות בנ\"י</b>: ראה תו\"א שמות נ, א ואילך. אוה\"ת שם ע' מב ואילך. כרך ז שם ע' ב'תפג ואילך."],["799","208","<b>גדול אדונינו</b>: תהלים קמז, ה. ראה מאמרי אדה\"ז תק\"ע ע' קטז ואילך. סהמ\"צ להצ\"צ קכה, ב ואילך. אוה\"ת בלק ע' א'תרסז."],["800","209","<b>אלף אלפים. . ולגדודיו אין מספר</b>: ראה חגיגה יג, ב."],["801","210","<b>הדבור שהוא מל'</b>: ראה זהר לך פו, ב. ע\"ח שער מוחין דצלם שכ\"ג, ספ\"ה. מאמרי אדה\"א דברים ח\"ב ע' שפב. וש\"נ."]]],[2000450132,"ולתבונתו אין מספר שבאצילות יוכל להיות התכללות המדות לאין קץ כו', כי באצי' איהו וגרמוהי חד<sup data-n=\"802\">211</sup> כו', ועוי\"ל אין מספר ע\"ד ילכו מחיל אל חיל<sup data-n=\"803\">212</sup> שיש עליות לאין קץ בבחי' המדות כו', וע' בשל\"ה דשמ\"ז ע\"ב, וזהו מונה מספר לכוכבים ופי' בזח\"ב משפטים<sup data-n=\"804\">213</sup> שבחי' מספר שהוא ז\"א הוא המונה את הכוכבים כו', אשר ז\"א נק' מספר מטעם הנ\"ל שהם המדות שהם בחי' התחלקות חו\"ג כו', ומתכללים זע\"ז ונעשה מספר ס\"ר, ואזי נמשך מזה השפעה למטה בכוכבים שהם צבא השמים, ומה שנז' לכוכבים דוקא י\"ל ע\"פ המד\"ר במדבר פ\"ב דף רי\"ב ע\"ב הנ\"ל<sup data-n=\"805\">214</sup> משלן לכוכבים כו' וחפרה הלבנה ובושה החמה כו' והכוכבים אינם בושים כו', והיינו לפי שהכוכבים נראים קטנים ביותר והוא ענין קטנתי מכל החסדים<sup data-n=\"806\">215</sup> כו' כי כל הקרוב יותר קמי' הוא יותר כלא חשיב, ולכן הכוכבים שהם ברקיע תמינאה שהוא בינה<sup data-n=\"807\">216</sup> עלמא דאתכסיא<sup data-n=\"808\">217</sup> הנה שם היש ולמטה אין ע\"כ הם קטנים, משא\"כ חמה ולבנה זו\"נ<sup data-n=\"809\">218</sup> המתלבשים ביצי' ועשי' נראים גדולים, והו\"ע ריבוי הכלים ומזה נמשך להיות נראה למטה היש ולמעלה אין כו', נמשך לבחי'<sup data-n=\"810\">219</sup> בנה הגדול<sup data-n=\"811\">220</sup>, וע' זח\"ב פקודי רל\"ג ב' בענין כל המוסיף גורע כו' וע' בת\"א פ' נח<sup data-n=\"812\">221</sup> בענין אחות לנו קטנה<sup data-n=\"813\">222</sup> ולכן לע\"ל אשר יגלה כבוד ה' אזי החמה ולבנה בושים מה שמהם נשתלשל היש ודבר נפרד משא\"כ הכוכבים כו', ולכן בכוכבים נז' מונה מספר לכוכבים שמספר הוא בחי' חשיבות כמשי\"ת לקמן אי\"ה בענין את שדרכו למנות<sup data-n=\"814\">223</sup> כו' שהוא דבר החשוב מאד, שעי\"ז איש מהם לא נעדר<sup data-n=\"815\">224</sup> כו', וכמו\"כ נמשלו<sup data-n=\"816\">225</sup> לכוכבים וזהו ומצדיקי הרבים ככוכבים<sup data-n=\"817\">226</sup> כו' וע' ברבות סדר בא ס\"פ ט\"ו אבל לע\"ל מוסר להם הכל שנאמר והמשכילים יזהרו<sup data-n=\"818\">228</sup> ככוכבים<sup data-n=\"819\">229</sup><sup data-n=\"820\">227</sup> דקל\"ג ג'<sup data-n=\"821\">230</sup>, ומ\"ש במאו\"א מספר הוא הדעת<sup data-n=\"822\">231</sup>, זהו לפי שהדעת כולל ה\"ח וה\"ג<sup data-n=\"823\">232</sup>, וא\"כ הוא שרש לחו\"ג שמהם נמשך המספר וההתחלקות לכמה מדרגות, ועיקר המספר במל' שהוא הדבור כו'.",[["802","211","<b>איהו וגרמוהי חד</b>: ראה ת\"ז בהקדמה ג, ב."],["803","212","<b>ילכו מחיל אל חיל</b>: תהלים פד, ח."],["804","213","<b>ופי' בזח\"ב משפטים</b>: קה, רע\"ב."],["805","214","<b>המד\"ר במדבר פ\"ב דף רי\"ב ע\"ב הנ\"ל</b>: ראה לעיל רפ\"ב ובהערה 30."],["806","215","<b>קטנתי מכל החסדים</b>: וישלח לב, יא. ראה אגה\"ק ס\"ב."],["807","216","<b>ברקיע תמינאה שהוא בינה</b>: ראה זהר ויצא קסב, ב ובמפרשים שם. ויקהל ריג, א ובהגהות מהרח\"ו שם."],["808","217","<b>בינה עלמא דאתכסיא</b>: ראה לקו\"ת שמ\"ע פח, ד."],["809","218","<b>חמה ולבנה זו\"נ</b>: ראה זהר שמות ב, א ובהגהות הרח\"ו אות ד. ת\"ז בהקדמה ח, סע\"ב ואילך."],["810","219","<b>נמשך לבחי'</b>: באוה\"ת כאן: ויש יניקה לעשו."],["811","220","<b>בנה הגדול</b>: תולדות כז, טו."],["812","221","<b>בת\"א פ' נח</b>: ט, ג."],["813","222","<b>אחות לנו קטנה</b>: שה\"ש ח, ח."],["814","223","<b>כמשי\"ת לקמן. . את שדרכו למנות</b>: בפ\"ט. וש\"נ."],["815","224","<b>איש מהם לא נעדר</b>: ע\"פ ישעי' מ, כו."],["816","225","<b>נמשלו</b>: באוה\"ת כאן: זרע יעקב נמשל."],["817","226","<b>ומצדיקי הרבים ככוכבים</b>: דניאל יב, ג."],["818","228","<b>יזהרו</b>: באוה\"ת כאן: יזהירו. והם שתי נוסחאות בתיבה זו."],["819","229","<b>ככוכבים</b>: באוה\"ת כאן: כו'."],["820","227","<b>והמשכילים יזהרו ככוכבים</b>: התחלת הכתוב ומצדיקי הרבים בדילוג. הובא לקמן בפ\"ט."],["821","230","<b>דקל\"ג ג'</b>: בדפוס אמשטרדם ת\"א, והוא השמו\"ר בא ס\"פ טו שהובא בפנים בשורה שלפנ\"ז."],["822","231","<b>במאו\"א מספר הוא הדעת</b>: לעיל רפ\"ו."],["823","232","<b>שהדעת כולל ה\"ח וה\"ג</b>: ראה ע\"ח שער לידת המוחין שכ\"א, פ\"ב. מאו\"א מערכת דעת אות כג."]]],[2000450133,"<span data-k=\"ks\"><b>קיצור.</b> שסיבת ההתחלקות וריבוי הנבראים מא\"ס ב\"ה הפשוט לפי שנמשכו ע\"י ע\"ס שהם בחי' שונות חו\"ג והתכללות י\"ב ג\"א ומזה נמשך י\"ב מזלות, ו\"ק מתחלקים לס\"ר ומכל א' מהס\"ר הנ\"ל נמשך ע\"י הדבור גדוד א' אלף אלפים מספר גדוד א', וזהו מונה מספר שהוא ז\"א הוא מונה לכוכבים, ולגדודיו אין מספר ע\"ד ולתבונתו אין מספר כו'.</span>\n<b>"],[2000450134,"<h3>שאו</b> מרום עיניכם כו' נפלאותיך ומח' כו' עצמו מספר כו' מרוב אונים כו'</h3>\nט) <b>וסיום</b><sup data-n=\"824\">233</sup> הפסוק מרוב אונים ואמיץ כח איש לא נעדר<sup data-n=\"825\">234</sup>, ופי' הראב\"ע והרד\"ק ר\"ל איש מהכוכבים לא נעדר שכולם קיימים ועומדים ברום עולם משי\"ב ולא כמו הנבראים בארץ שהם מתים כו', ומה שהם נצחים אין זה מפאת עצמן כ\"א מפאת סבתם הוא הבורא ית' הבבע\"ג שמכח<sup data-n=\"826\">235</sup> בראם נצחיים וזהו מרוב אונים ואמיץ כח השי\"ת איש לא נעדר כו', ותכלית כוונת הפסוקים האלה להודיע כח ויכולת אלקי לקיים כל הבטחותיו, ואע\"פ שיפלא מהעם כו' כן פי' בפי' כלי פז<sup data-n=\"827\">236</sup> במקראות גדולות<sup data-n=\"828\">237</sup>, והיינו מ\"ש לע\"ל והמשכילים יזהרו כזהר הרקיע ומצדיקי הרבים ככוכבים, ר\"ל כמו שהם איש לא נעדר כמ\"כ המשכילים יזהרו כו' לנצח, ובת\"ז תיקון מ\"ט פי' מרוב אונים דא כתר עילאה ואמיץ כח דא חכ' מאי כח דילי' אימא עילאה כו' כי כולם בחכ' עשית בבינה<sup data-n=\"829\">238</sup>, והנה כתר בחי' סוכ\"ע כותרת<sup data-n=\"830\">239</sup> ומקיף, וחו\"ב שרש או\"פ ממכ\"ע כו', ולפ\"ז ענין מרוב אונים ע\"ד כל אשר חפץ ה' עשה, ולפ\"ז פי' המוציא במספר צבאם כו' מקושר עם מ\"ש אח\"כ איש לא נעדר, שלכן נק' במספר שהדבר שהוא נספר ונמנה תמיד זהו מורה על חשיבותו, וכמ\"ש ברבות ע\"פ שררך כו' הנ\"ל שהחיטי' אין יוצאין אלא במנין משא\"כ התבן והקש אין משגיח עליהם כו' ע\"ש. וז\"ע המוציא במספר צבאם שהוא לגודל חשיבותם עד שאיש מהם לא נעדר וע\"כ מונה מספר לכוכבים כו', וזהו ע\"ד מארז\"ל רפ\"ק דביצה דף ד' ע\"ב<sup data-n=\"831\">240</sup> את שדרכו למנות הוא דבר חשוב ואינו בטל כו', ואף שבאמת השגחתו ית' הוא על כל פרטי האישים ממש עכ\"ז ודאי יש כמה חילוקי מדריגות בענין ההשגחה וכמ\"ש ברבות משפטים פל\"ב<sup data-n=\"832\">241</sup> ע\"פ הנה אנכי שולח מלאך<sup data-n=\"833\">242</sup> אלו זכיתם",[["824","233","<b>וסיום</b>: ברשימת המאמרים שמופיע בריש הבוך נרשם כאן מאמר (ג' מההמשך והוא) ד\"ה: שאו מרום עיניכם (פרקים ט—יא. או כפי הנרשם לעיל במפתח המאמרים שבריש הספר (כנראה ע\"פ ב) פרקים ז—יא).\nלמאמר זה ראה אוה\"ת תשא ע' א'תתכה ואילך בשינויים. לפי\"א ראה גם תו\"א וירא יג, ג."],["825","234","<b>מרוב אונים. . איש לא נעדר</b>: ישעי' מ, כו."],["826","235","<b>שמכח</b>: באוה\"ת כאן: שמכחו."],["827","236","<b>בכלי פז</b>: לר' שמואל לאנייאדו. באוה\"ת ישעי' ע' רפג: ”הוא בעהמ\"ס עוללות אפרים\" אבל ראה סדה\"ד ושם הגדולים בערכו."],["828","237","<b>במקראות גדולות</b>: [ועד\"ז מובא באוה\"ת נ\"ך ע' קט במקראות. ע' רו במקראות] קהלת משה אמשטרדם תפ\"ד — תפ\"ח פז, ג תוך ד\"ה הלא תדעו וגו' היושב וד\"ה ולעד\"ן (בשינוי קל)."],["829","238","<b>כולם בחכ' עשית בבינה</b>: תהלים קד, כד. זהר תזריע מג, א."],["830","239","<b>כתר. . כותרת</b>: ראה ע\"ח שער דרושי הצלם שכ\"ה, פ\"ה. מבוא שערים ש\"ג, ח\"ב פ\"א. מאמרי אדה\"א דברים ח\"ד ע' א'שכז. וש\"נ. וראה גם לקמן (בחלק ההנחות) הנחה ד\"ה על חומותיך על יד הערה 40."],["831","240","<b>דף ד' ע\"ב</b>: וכ\"ה באוה\"ת כאן ע' א'תתכו. ראה שם ג, ב."],["832","241","<b>ברבות משפטים פל\"ב</b>: ס\"ב."],["833","242","<b>הנה אנכי שולח מלאך</b>: משפטים כג, כ."]]],[2000450135,"אני בעצמי נעשיתי לכם שליח כדרך שעשיתי לכם במדבר שנאמר וה' הולך לפניהם יומם<sup data-n=\"834\">243</sup>, ועכשיו שלא זכיתם הרני מוסר אתכם לשליח שנאמר הנה אנכי שולח מלאך וגו'<sup data-n=\"835\">244</sup>, ועו\"ש ס\"פ הנ\"ל<sup data-n=\"836\">245</sup> ד\"א הנה אנכי שולח מלאך הה\"ד חונה מלאך ה'<sup data-n=\"837\">246</sup> סביב ליראיו ויחלצם עשה אדם מצוה אחת הקב\"ה נותן לו מלאך אחד לשומרו שנאמר חונה מלאך ה', עושה<sup data-n=\"838\">247</sup> שתי מצות הקב\"ה נותן לו שני מלאכים לשמרו שנאמר כי מלאכיו<sup data-n=\"839\">248</sup> יצוה לך לשמרך כו' חצי מחנהו כו' ע\"ש. הרי יש מדריגות רבות בענין ואופן השמירה וההשגחה וכמ\"ש ג\"כ בפ' שמות וישמע אלקים את נאקתם<sup data-n=\"840\">249</sup> כו' וידע אלקים<sup data-n=\"841\">250</sup> ופי' רש\"י נתן עליהם לב ולא העלים עיניו, והבחיי פי' וירא אלקים<sup data-n=\"842\">251</sup> הוא כענין יאר ה' פניו אליך<sup data-n=\"843\">252</sup> וידע אלקים הוא מענין עץ הדעת כי נמשך שפע מן הרחמים אל הדעת לרחם על ישראל כו', הרי מכ\"ז מובן שלפעמים שייך כביכול שמעלים עניו<sup data-n=\"844\">253</sup> ר\"ל משום שמושלים עליהם מצרים כו', נק' זה תעלים לעתות בצרה<sup data-n=\"845\">254</sup>, ונק' שינה כו' אף שזה גופא הוא בהשגחה פרטיות, מ\"מ אצלינו זה העלם שנראה עולם כמנהגו נוהג<sup data-n=\"846\">255</sup>, משא\"כ וידע אלקים המשכה פנימיות לעשות נסים ונפלאות כו', וכ\"כ הרמב\"ן בפ' שמות שם כי מתחלה<sup data-n=\"847\">256</sup> הי' מסתיר פניו מהם והי' לאכול<sup data-n=\"848\">*257</sup>, ועתה שמע אלקים את נאקתם וראה אותם ר\"ל<sup data-n=\"849\">257</sup> שלא הסתיר פניו מהם<sup data-n=\"850\">258</sup> כו', נמצא מה שמסתיר פניו אף שזהו בהשגחה מ\"מ לעין הרואה נראה כאילו אינם מושגחים ח\"ו והי' לאכול, משא\"כ כשקרבם למאור פניו נק' וידע אלקים, ועד\"ז יש לפרש מ\"ש המוציא במספר צבאם, שהוא ית' סופר ומונה אותם תמיד עד שלכן איש לא נעדר, וז\"ע החשיבות של הדבר שבמנין שמחמת שהוא חשוב ויקר אצלו ית' עד שנק' דבר שדרכו למנות ע\"כ נותן לו קיום באיש שיהי' קיים לעד לעולם כמ\"ש ויעמידם לעד לעולם<sup data-n=\"851\">259</sup>, ובחי' זו בנשמות ג\"כ שהנשמה עצמה היא נצחיות<sup data-n=\"852\">260</sup>, וזהו ומספר את רובע ישראל<sup data-n=\"853\">261</sup> וכדפרש\"י בחומש, והיינו מ\"ש המאו\"א שהמספר הוא הדעת שהרי בחי' מספר זה זהו כענין וידע אלקים.\n<span data-k=\"ks\"><b>קיצור.</b> ענין איש לא נעדר, שעומדים ברום עולם משי\"ב, והיינו מרוב אונים כו', ועד\"ז והמשכילים יזהירו לע\"ל, וזהו המוציא במספר צבאם, שהם דבר </span>",[["834","243","<b>וה' הולך לפניהם יומם</b>: בשלח יג, כא."],["835","244","<b>וגו'</b>: כ\"ה גם באוה\"ת ובמדרש ליתא."],["836","245","<b>ס\"פ הנ\"ל</b>: פל\"ב, ו."],["837","246","<b>חונה מלאך ה'</b>: תהלים לד, ח."],["838","247","<b>עשה. . עושה</b>: כ\"ה גם באוה\"ת כאן. ובמדרש (אמשטרדם שנת ת\"א-ב): עושה. . עשה. ובדפוסים הנפוצים: עושה."],["839","248","<b>כי מלאכיו</b>: תהלים צא, יא."],["840","249","<b>וישמע אלקים את נאקתם</b>: שמות ב, כד."],["841","250","<b>וידע אלקים</b>: שמות שם, כה."],["842","251","<b>וירא אלקים</b>: התחלת הכתוב וידע אלקים."],["843","252","<b>יאר ה' פניו אליך</b>: נשא ו, כה."],["844","253","<b>עניו</b>: ב: עיניו."],["845","254","<b>תעלים לעתות בצרה</b>: תהלים י, א."],["846","255","<b>עולם כמנהגו נוהג</b>: ע\"ז נד, ב."],["847","256","<b>מתחלה</b>: וכ\"ה באוה\"ת כאן. וברמב\"ן: בתחילה."],["848","*257","<b>והי' לאכול</b>: וילך לא, יז."],["849","257","<b>ר\"ל</b>: וכ\"ה באוה\"ת כאן. וברמב\"ן: לומר."],["850","258","<b>מהם</b>: וכ\"ה באוה\"ת כאן. וברמב\"ן: עוד מהם."],["851","259","<b>ויעמידם לעד לעולם</b>: תהלים קמח, ו."],["852","260","<b>שהנשמה עצמה היא נצחיות</b>: ראה תו\"א מקץ לח, ג. לט, ד. לקו\"ת בהר מא, סע\"א. תצא לד, ג. אוה\"ת כאן. שלח כרך ו ע' א'תתטז. מטות כרך ו ס\"ע א'תתקנד ואילך. תשובות וביאורים ס\"ח (אג\"ק שלו ח\"א ספ\"ה)."],["853","261","<b>ומספר את רובע ישראל</b>: בלק כג, י."]]],[2000450136,"<b>שבמנין</b> שמשגיח עליהם וסופר ומונה אותם, ע\"ד וידע אלקים, הארת פנים היפך הסתר פנים, וכן מספר הוא הדעת.\nיו\"ד) <b>ועד\"ז</b> יש לפרש ענין כי תשא את ראש בנ\"י כו' וכתיב שאו את ראש כו' תפקדם<sup data-n=\"854\">262</sup>, שזהו העלאה ורוממות שיהיו ספורים ומנויים ככוכבים שנאמר בהם המוציא במספר צבאם, וכמ\"ש לע\"ל ומצדיקי הרבים ככוכבים כו', והיינו שיהיו מרכבה לבחי' ו\"ק דז\"א דאצי' שהם בחי' מספר ששים ריבוא כיוצאי מצרים כו', וזהו ומספר את רובע ישראל, והי' מספר בנ\"י, וכן נאמר עוד תעבורנה הצאן<sup data-n=\"855\">263</sup> ע\"י מונה, ואפ\"ל שזהו למעלה מו\"ק דז\"א כ\"א ו\"ק דא\"א ואז יהי' מספר בנ\"י אשר לא יספר כו'.\n<b>ולבאר</b> הדברים ע\"ד החסידות והעבודה, הענין הוא דכבר מבואר למעלה שענין מספר נמשך מבחי' ע\"ס, אשר הם ג\"כ מלשון מספר, וכמו שהדבר הנספר חשוב ביותר, כך עד\"ז מעלת הע\"ס חשוב אין שיעור יותר על כל הנמצאים, שהרי כל דבר שמציאותו מועט יותר הוא יקר, כמו יוקר הזהב על הכסף מפני שהוא מועט יותר, וכענין מ\"ש ברבות ויקרא ר\"פ ב' עשרה נק' יקרים כו' הבן יקיר לי אפרים<sup data-n=\"856\">264</sup> כו' אדם אחד מאלף מצאתי<sup data-n=\"857\">265</sup> כו' ע\"ש. והנה סדר השתלשלות מלמעלה למטה כל מה שנמשך למטה מתרבה המספר וכמ\"ש בתו\"א וישב<sup data-n=\"858\">266</sup> ע\"פ והנה אנחנו מאלמים אלומים, והו\"ע מספר של ריבוי הכלים והאותיות, עד\"מ נהר היוצא מעדן הוא נהר אחד, ומתפרד אח\"כ לד' נהרות, או ד' דגלים הם כלל מנשמת<sup data-n=\"859\">267</sup> יהודה עד\"מ הי' כולל כלליות הדגל שלנו<sup data-n=\"860\">268</sup>, ובפרטיות אתה מספרן<sup data-n=\"861\">269</sup> רב, וזהו בבריאה, ובבחי' הרוח דיצי' נתרבו עוד יותר, ובבחי' הנפש דעשייה נתרבו עוד יותר הרבה כו', משא\"כ הספירות הם שהם<sup data-n=\"862\">*270</sup> קרובין יותר לא\"ס ב\"ה הם רק עשר ספירות, עשר ולא תשע<sup data-n=\"863\">270</sup> עשר ולא אחד עשר, והם ע\"ס הכללים, ומה שו\"ק דז\"א מתחלקים לס\"ר זהו בחי' חיצוני' הכלים וכמ\"ש במ\"א בענין פי' כן רעייתי בין הבנות<sup data-n=\"864\">271</sup>, לכן ע\"ס שהם קרובין ממש אליו ית' הם רק במספר עשר כו'.\n<span data-k=\"ks\"><b>קיצור.</b> ענין מספר בנ\"י ע\"ד המוציא במספר, מרכבה לז\"א שרש מספר, ע\"ס ל' מספר, שכל שלמטה נעשה הריבוי ביותר, משא\"כ בחי' ע\"ס לפי שהם קרובים יותר הם עשר לבד, ולפ\"ז בחי' עקודים שעקוד בכלי א'<sup data-n=\"865\">272</sup> זהו לפי שבחי' </span>",[["854","262","<b>שאו. . תפקדם</b>: כ\"ה גם באוה\"ת כאן ע' א'תתכז. במדבר א, ב-ג [ושם: תפקדו אותם]."],["855","263","<b>עוד תעבורנה הצאן</b>: ירמי' לג, יג."],["856","264","<b>הבן יקיר לי אפרים</b>: ירמי' לא, יט."],["857","265","<b>אדם אחד מאלף מצאתי</b>: קהלת ז, כח."],["858","266","<b>בתו\"א וישב</b>: כז, ג ואילך."],["859","267","<b>מנשמת</b>: ב: שנשמת."],["860","268","<b>שלנו</b>: ב ניתוסף ממעל לשיטה: שלו."],["861","269","<b>אתה מספרן</b>: אוצ\"ל: אתה מוצא מספרן."],["862","*270","<b>הם שהם</b>: כ\"ה גם בב."],["863","270","<b>עשר ולא תשע</b>: ס\"י פ\"א, מ\"ג מהדורת מנטובא שכ\"ב."],["864","271","<b>כן רעייתי בין הבנות</b>: ראה ביאוה\"ז להצ\"צ ח\"ב ע' תקפו."],["865","272","<b>עקודים שעקוד בכלי א'</b>: ראה ע\"ח שער העקודים ש\"ו, פ\"א. תו\"א נח י, ג ואילך. תו\"ח וארא ח\"א נב, ד. וש\"נ. סה\"מ תרנ\"ב ע' ק ואילך."]]],[2000450137,"<b>עוד</b><sup data-n=\"866\">273</sup> קרובה יותר מע\"ס, וי\"ל עקוד בכלי אחד שגם הכלי היא אחד<sup data-n=\"867\">274</sup>, שהריבוי שנעשה למטה זהו מצד הכלים כנ\"ל, אבל בעקודים שגם היא היא<sup data-n=\"868\">*275</sup> אחד לכן שם הוא בבחי' מיעוט היותר אחרון היינו אחד כו', ומ\"ש במ\"א ע\"ס הגנוזות<sup data-n=\"869\">275</sup> במאצילן מספר עשר בשם<sup data-n=\"870\">276</sup> זהו לפי שהם כח הע\"ס העתידים להתגלות, והם בכח לבד ולא בפועל, שהרי הם גנוזות בא\"ס המאצילן שהוא אח\"פ כו'.\nיא) <b>והנה</b><sup data-n=\"871\">277</sup> יש ע\"ס שנק' עשר תיקונין, ויש בחי' לבושים<sup data-n=\"872\">278</sup>, ושרש ההפרש הוא שבע\"ס איהו וגרמוהי ג\"כ חד משא\"כ בלבושים ממש, ויובן זה דהנה הנפש<sup data-n=\"873\">279</sup> מצד עצמה הוא<sup data-n=\"874\">280</sup> אור פשוט<sup data-n=\"875\">281</sup> בלי התחלקות שכל ומדות, והשכל והמדות שלה הן בחי' לבושין לנפש, שהנפש יש לה שכל ומדות אבל אינם מהות ועצמיות הנפש<sup data-n=\"876\">282</sup>, ומ\"ש בסש\"ב שהנפש עצמה מתחלקת לשכל ומדות<sup data-n=\"877\">283</sup> שהם נק' עצמיות הנפש אין זה אלא לגבי מחשבה דו\"מ שהם לבושי' נפרדי' ממש ממהות הנפש שהן בחי' בי\"ע שע\"ז אמר לבושין תקינת לון כו', דאינון בי\"ע, אבל השכל ומדות אם<sup data-n=\"878\">284</sup> היות שהם בחי' לבושי' אינם לבושי' נפרדים ממש אלא כמו כלים דאצילות שבהון<sup data-n=\"879\">285</sup> איהו וגרמוהי חד, ולכן נק' בשם עצמיות ולא עצמיות ממש, אלא שהם נק' בשם תיקונין שהנפש מתתקנת ומתלבשת בהון<sup data-n=\"880\">286</sup>, וכמו שת\"א ע\"פ ולא ילבש גבר<sup data-n=\"881\">287</sup> שמלת אשה לא<sup data-n=\"882\">288</sup> יתקן גבר בתיקוני איתתא, ולבושי' ותיקוני' אלו הם כמו לבוש הגוף שעם היות שהגוף הוא לבוש לנפש, מ\"מ הרי הנפש מתפעלת ממקרי הגוף שכשהגוף נוקף אצבעו מרגשת הנפש, וכן מה שעולה ברצון הנפש לפעול איזה פעולה באיברים האיברים נשמעין לרצון זה תומ\"י כשעולה ברצונו לעשות הפעולה כו', בלי שום קדימת התפשטות והמשכת המחשבה מהמוח ברגל שא\"כ הי' איזהו",[["866","273","<b>עוד</b>: ב: עקוד."],["867","274","<b>שגם הכלי היא אחד</b>: ראה גם לקמן המשך חייב אדם לברך פי\"ט על יד הערה 687. מאמר ד\"ה אני לדודי על יד הערה 112. אוה\"ת נח כרך ו ע' תתרס\"ח בחצאי עיגול (שזהו הגהת כ\"ק אדמו\"ר מהר\"ש)."],["868","*275","<b>היא היא</b>: כ\"ה גם בב."],["869","275","<b>ע\"ס הגנוזות</b>: ראה פרדס שער סדר האצי' ש\"ה, פ\"ד. שער הצחצחות שי\"א. וראה שם פ\"ג. הנסמן במאמרי אדה\"א דברים ח\"א ע' שמו־ שעה\"י — לקו\"ב — קפט, ג-ד הערה 2. המשך מים רבים תרל\"ו ע' ע."],["870","276","<b>בשם</b>: ב: דשם."],["871","277","<b>והנה</b>: לפרק זה ראה גם תו\"א שבהערה 279."],["872","278","<b>ע\"ס שנק' עשר תיקונין. . לבושים</b>: ת\"ז בהקדמה יז, א."],["873","279","<b>דהנה הנפש. . הנפש</b>: לשון התו\"א וירא יג, ג בשינויים."],["874","280","<b>הוא</b>: ב ובתו\"א: היא."],["875","281","<b>הנפש. . אור פשוט</b>: ראה תניא פנ\"א."],["876","282","<b>שכל ומדות. . אינם מהות ועצמיות הנפש</b>: ראה לקו\"ת ויקרא ד, ב. סה\"מ תרכ\"ז שבהערה הבאה."],["877","283","<b>בסש\"ב שהנפש. . לשכל ומדות</b>: פ\"ג ופי\"ב — לקו\"ת שם. ועייג\"כ קו\"א ד [להבין מ\"ש בפע\"ח קנז, א] והשכל הוא הארה ולבוש — תניא מ\"מ הגהות והע\"ק פ\"ג. סה\"מ תרכ\"ז ע' תנז. וש\"נ."],["878","284","<b>אם</b>: בתו\"א: עם. ראה לעיל הערה 97."],["879","285","<b>שבהון</b>: ראה הערה הבאה."],["880","286","<b>בהון</b>: בתו\"א: בהן. ראה הערה שלפנ\"ז."],["881","287","<b>שת\"א ע\"פ ולא ילבש גבר</b>: תצא כב, ה."],["882","288","<b>לא</b>: וכ\"ה בתורה אור. ובת\"א: ולא. וכ\"ה במאמרי אדה\"ז על פרשיות התורה ח\"א ע' קלא. ושם ע' צז — שהוא הנחת כ\"ק אדה\"א מדרוש זה — איתא: לא — כבפנים. אבל שם מעתיק הכתוב ”לא\" ילבש. בתקס\"ו ע' לא — שהוא הנחת הר\"מ מדרוש זה — כותב: דלא. . דלא."]]],[2000450138,"שיהוי זמן מה והרי אינו שוהה אפי' רגע אלא מיד שעולה ברצונו כו', אין זה אלא מפני שהגוף מתאחד עם הנפש, והנפש פועלת בה כרצונה כאילו הי' עצמותה ומהותה ממש, ואף שהגוף הוא לבוש הנפש מ\"מ הוא מתאחד עם הנפש, ועד\"ז יובן למעלה ענין ע\"ס שנק' בשם תיקונין שנמשלים לאיברי האדם חסד דרועא ימינא גבורה דרועא שמאלא, ת\"ת גופא, ומתייחדים עם בחי' אוא\"ס ע\"ד יחוד הגוף עם הנפש, ויותר עד דאיהו וגרמוהי חד בהון, משא\"כ בחי' הלבושים שהם כמשל לבושי הגוף שאינם מתאחדים עם הגוף וכ\"ש עם הנפש כו', וע' בת\"א פ' יתרו בד\"ה זכור<sup data-n=\"883\">289</sup> את יום השבת דרוש השני, שמבואר שם ששרש הנשמות אף שעלו במח' הוא רק מבחי' הלבושים וע\"י ירידתן והתלבשותן בגוף ונה\"ב וקיום התומ\"צ עי\"ז מתעלים לאשתאבא בגופא דמלכא<sup data-n=\"884\">290</sup> ממש, כי רמ\"ח מ\"ע הם רמ\"ח איברין דמלכא<sup data-n=\"885\">291</sup> ממש שנמשכו מט\"ס דז\"א טפ\"ט הוא פ\"א ובכ\"א יש רת\"ס הרי רמ\"ג ועם ה\"ח<sup data-n=\"886\">292</sup> המגדילים הוא רמ\"ח נמצא הם נק' כבי' גופא דמלכא, וזהו ועשיתם אותם וארז\"ל כאילו עשאוני<sup data-n=\"887\">293</sup>, ולכן ע\"י קיום התומ\"צ נעשה בחי' לאשתאבא בגופא דמלכא, היינו ע\"י הצדקה וחסד נכלל בבחי' חסד דרועא ימינא ממש, וע\"י סור מרע בבחי' איזהו גבור<sup data-n=\"888\">294</sup> הכובש את יצרו נכלל בבחי' גבורה דרועא שמאלא, וזהו כי לא ידח<sup data-n=\"889\">295</sup> ממנו נדח, ממנו ממש שנכללו באלקות ממש בבחי' ע\"ס שבהן מלובש אוא\"ס ב\"ה, ומ\"מ היינו ג\"כ ע\"י התפילה שהיא במקום קרבן<sup data-n=\"890\">296</sup> לברר נה\"ב שעי\"ז הוא ע\"ד והחיות נושאות את הכסא<sup data-n=\"891\">297</sup> כו' שמעלים את בחי' הכסא שמשם שרש נש\"י שחקוקי' תחת כסה\"כ<sup data-n=\"892\">298</sup>, וגם בחי' אדם שעל הכסא לקשרו ולחברו לבחי' אוא\"ס ממש, ועי\"ז נעשה עלייתם לאשתאבא בגופא דמלכא, וכמ\"ש במ\"א ע\"פ מקושש עצים<sup data-n=\"893\">299</sup>, וע\"פ וארא אל אברהם<sup data-n=\"894\">300</sup>, וז\"ע כי תשא את ראש בנ\"י לפקודיהם שיהיו בבחי' המוציא במספר צבאם דהיינו ההתכללות בע\"ס המתחלקים לששים רבוי כו' ולי\"ב גבולי אלכסון כו', וכן ארז\"ל ע\"פ מי ברא אלה<sup data-n=\"895\">301</sup> המוציא כו' בזכות מי נבראו בזכות",[["883","289","<b>בת\"א פ' יתרו בד\"ה זכור</b>: עא, א."],["884","290","<b>לאשתאבא בגופא דמלכא</b>: זהר ויחי ריז, ב. ראה הנסמן במאמרי אדה\"א ויקרא ח\"א ע' מה. תו\"ח בראשית מ, ב הערה 25."],["885","291","<b>רמ\"ח מ\"ע. . דמלכא</b>: ראה ת\"ז ת\"ל (עד, סע\"א). תניא רפכ\"ג. סידור שער החנוכה רפ, א. שע\"ת עב, ג הערה 17."],["886","292","<b>טפ\"ט. . ועם ה\"ח</b>: ראה ע\"ח שער פרקי הצלם שכ\"ד, פ\"ו. שע\"ת מב, ב ובהנסמן במ\"מ לשם."],["887","293","<b>ועשיתם. . כאילו עשאוני</b>: בחוקותי כו, ג. ראה זהר שם קיג, סע\"א. הנסמן במאמרי אדה\"א הנחות תקע\"ז ע' רלה."],["888","294","<b>איזהו גבור</b>: אבות פ\"ד, מ\"א."],["889","295","<b>כי לא ידח</b>: שמו\"ב יד, יד [ושם: לבלתי ידח — ראה גם לקמן (בחלק ההנחות) ד\"ה ביום ההוא יהי' על יד הערה 24. וש\"נ]."],["890","296","<b>התפילה שהיא במקום קרבן</b>: ברכות כו, א-ב. ראה מאמרי אדה\"א ויקרא ח\"א ע' ד. וש\"נ. אוה\"ת תשא ע' א'תתפג."],["891","297","<b>והחיות נושאות את הכסא</b>: ראה בחיי תרומה כה, י בשם הפדר\"א ספ\"ד. הנסמן במאמרי אדה\"א בראשית ע' שעג."],["892","298","<b>נש\"י שחקוקי' תחת כסה\"כ</b>: ראה ת\"ז תכ\"ב סה, ב [ובהנסמן בניצוצי זהר שם]. סו, א. רע\"מ צו כט, רע\"ב: גזורות מתחת כסא הכבוד. מאמרי אדה\"א דברים ח\"ב ע' תצט [ושם: ובל' הגמרא וראה בהנסמן שם]."],["893","299","<b>ע\"פ מקושש עצים</b>: ראה מאמרי אדה\"א במדבר ח\"ג ע' א'רמד ואילך. אוה\"ת שלח כרך ו ע' א'תתטז. סה\"מ תרל\"ג ח\"ב ע' שמ."],["894","300","<b>וע\"פ וארא אל אברהם</b>: מאמרי אדה\"ז על פרשיות התורה ח\"א ע' רלט. שם ע' 26."],["895","301","<b>ארז\"ל ע\"פ מי ברא אלה</b>: שמו\"ר פמ\"ח, ב."]]],[2000450139,"ואלה<sup data-n=\"896\">302</sup> שמות בנ\"י ה\"ה בחי' פנימיות של תולדות השמים וארץ<sup data-n=\"897\">303</sup>, שנאמר בהם המוציא במספר צבאם איש לא נעדר, שכמ\"כ וכ\"ש בבחי' אלה שמות בנ\"י כו' והיינו כי יש ע\"ס דאבי\"ע, ואלה תולדות השמים אף שנאמר בהם המוציא במספר, היינו המוציא מרה\"י שהוא אצי' לרה\"ר בבי\"ע, ובמספר היינו ע\"ס דבי\"ע, <sup data-n=\"898\">304</sup> אבל המספר דנש\"י הוא בע\"ס דאצי' המיוחדים בא\"ס ב\"ה כו'.\n<span data-k=\"ks\"><b>קיצור.</b> שיש ע\"ס שנק' תיקוני' לבושי' כמו הגוף, ויש לבושי' ממש, ושרש הנשמות מלבושי', וע\"י התומ\"צ מתעלים לאשתאבא בגופא דמלכא וז\"ע כי תשא את ראש והיינו לפקודיהם ע\"י המספר מספר ישראל שנכללו בע\"ס.</span>",[["896","302","<b>ואלה</b>: בשמו\"ר שם־ באוה\"ת כאן ע' א'תתכח־ ישעי' כרך ב ס\"ע תשצח: אלה."],["897","303","<b>תולדות השמים וארץ</b>: בראשית ב, ד."],["898","304","<b>מרה\"י שהוא אצי' לרה\"ר בבי\"ע</b>: ראה לקוטי הש\"ס להאריז\"ל ריש מס' שבת ד\"ה ארבע. לקו\"ת במדבר טז, א. מאמרי אדה\"ז תקס\"ח ח\"א ע' רכח [וכן צ\"ל בשע\"ת נג, ב הערה 23]. הנסמן במאמרי אדה\"א דברים ח\"ב ע' תעט הערה הקליפות."]]],[2000450140,"<h3>והי' מספר בנ\"י כו'</h3>\nיב) <b>אך</b><sup data-n=\"899\">305</sup> עדיין צ\"ל מה שהקשה השל\"ה פ' במדבר דשמ\"ז ע\"א, וז\"ל וענין המספר שגורם להשראות שכינה אף שלכאורה הוא להיפך, כי בדבר המדוד והמנוי אין הברכה שורה כמשארז\"ל פ\"ג דב\"מ וכנ\"ל<sup data-n=\"900\">306</sup>, דע כי יש שני עניני מספר, המספר של עניני עוה\"ז כו', אמנם ענין המספר של<sup data-n=\"901\">307</sup> השגת עוה\"ב כו', ודשמ\"ח ע\"ב פי' שזהו מארז\"ל פ\"ק דביצה<sup data-n=\"902\">308</sup> בענין את שדרכו למנות שנינו, או כל שדרכו למנות שנינו, דבחי' את שדרכו למנות ז\"ע המספר של עוה\"ב הנמשך מבחי' את היינו אותיות התורה מאלף ועד תיו כו'. ושרש<sup data-n=\"903\">309</sup> ההפרש בין מספר דעוה\"ז ובין מספר דעוה\"ב ע\"פ מארז\"ל שתי' קושי' דוהי' מספר<sup data-n=\"904\">310</sup>, על אשר לא יספר כאן בזמן שערש\"מ, וכאן בזמן שאערש\"מ, והענין הוא דמספר עוה\"ז הוא דבר המדוד ומנוי ויש לו קצבה כו' ויוכל להיות בו שליטת ע\"ה, משא\"כ מספר עוה\"ב הגם כי הוא ע\"ד מספר אבל אין לו קצבה ע\"ד שארז\"ל ת\"ח אין להם מנוחה<sup data-n=\"905\">311</sup> לא בעוה\"ז ולא בעוה\"ב שנאמר ילכו מחיל אל חיל<sup data-n=\"906\">312</sup> שהוא בחי' עליות המדריגות עד אין שיעור כלל, וכן ארז\"ל שכאו\"א נכוה מחופתו של חבירו<sup data-n=\"907\">313</sup> שהם מדריגות רבות עד אין שיעור כלל",[["899","305","<b>אך</b>: ברשימת המאמרים שמופיע בריש הבוך נרשם כאן מאמר (ד' מההמשך והוא) ד\"ה: והי' מספר בנ\"י (פרקים יב—יד). או כפי הנרשם לעיל במפתח המאמרים שבריש הספר (כנראה ע\"פ ב) פי\"ב).\nלמאמר זה ראה אוה\"ת תשא ע' א'תתכח ואילך בשינויים. המשך תער\"ב ח\"א ע' קעא ואילך. לפי\"ג ראה גם לק\"ת שה\"ש לט, א."],["900","306","<b>פ\"ג דב\"מ וכנ\"ל</b>: [תיבות אלו אינם בשל\"ה] צויין לעיל בריש ההמשך על יד הערה 4."],["901","307","<b>ענין המספר של</b>: וכ\"ה באוה\"ת כאן. ובשל\"ה: המספר של ענין."],["902","308","<b>פ\"ק דביצה</b>: ראה לעיל פ\"ט על יד הערה 240."],["903","309","<b>ושרש</b>: מכאן ועד תיבת ואמנם שעל יד הערה 319 לא נמצא באוה\"ת כאן. ראה גם המשך תער\"ב שבהערה 305."],["904","310","<b>מרז\"ל. . דוהי' מספר</b>: הושע ב, א. יומא כב, ב. הובא בשל\"ה כאן שמז, ב."],["905","311","<b>ת\"ח אין להם מנוחה</b>: ברכות בסופה (הובא בשל\"ה שם). ראה גם תו\"ח שמות ח\"א ד, ג. וש\"נ."],["906","312","<b>ילכו מחיל אל חיל</b>: תהלים פד, ח."],["907","313","<b>שכאו\"א נכוה מחופתו של חבירו</b>: ב\"ב עה, א (הובא בשל\"ה שם)."]]],[2000450141,"וכ\"א הוא דבר שבמנין שאין לו ביטול כלל להיותו דבר חשוב ונעלה, וזהו שבזמן שאעשרש\"מ אז המספר ע\"ד עוה\"ז שיש קץ וגבול להמספר שהמספר הוא לגריעותא אבל המספר דעוה\"ב אם כי בגדר מספר הוא מ\"מ אין קץ למספרו והיינו מפני כח המספר הסופר המספר שיש במספר שמצד בחי' המספר<sup data-n=\"908\">314</sup> הסופר אין בבחי' המספר בחי' גבול כלל, וע\"ד שנת' בד\"ה ויצום<sup data-n=\"909\">315</sup> אל בנ\"י כו' שהגם שהספירות הם בבחי' מדה וגבול עכ\"ז כל ספי' מתפשטת עד אין סוף ושיעור מפני כח הא\"ס שבה כו', וזהו ההפרש בין כל שדרכו למנות ובין את שדרכו למנות, שבחי' כל הוא מספר העוה\"ז, כי בהבראם בה' בראם<sup data-n=\"910\">316</sup> שעוה\"ז נברא בה'<sup data-n=\"911\">317</sup> וה' פעמים יוד עולה כל, משא\"כ את הוא ל' ריבוי<sup data-n=\"912\">318</sup> שמרבה מספר עוה\"ב שאין להמספר שיעור מחמת כח המספר הסופר א\"ס ב\"ה כו'. ואמנם<sup data-n=\"913\">319</sup> אינו מובן איך כל שדרכו למנות זהו המספר של עוה\"ז הרי כי כל בשמים ובארץ<sup data-n=\"914\">320</sup> זהו בחי' צדיק דאחיד בשמיא ובארעא, וע' במאו\"א אות כף סמ\"ב בענין כל, ונראה עפמ\"ש בישעי' סי' מ\"ה ז' יוצר אור ובורא חשך עושה שלום ובורא רע, וארז\"ל פ\"ק דברכות די\"א ע\"ב כתי' רע וקרינן הכל היינו מה שאנו אומרים בברכת יוצר המאורות עושה שלום ובורא את הכל, לשנא מעליא, הרי עכ\"פ כינו את רע בשם הכל שהוא כל, וכן משמע הפי' ברבות סדר אחרי ר\"פ ך\"ב<sup data-n=\"915\">321</sup> ע\"פ ויתרון ארץ בכל היא<sup data-n=\"916\">322</sup>, אפי' דברים שאתה רואה מיותרין בעולם<sup data-n=\"917\">323</sup> כגון זבובים ופרעושים<sup data-n=\"918\">324</sup> ויתושים אף הן בכלל ברייתו של עולם דכתיב ויכולו השמים<sup data-n=\"919\">325</sup>, וכן איתא בקהלת רבה דצ\"ו ע\"ד<sup data-n=\"920\">326</sup>, הרי גם יתושים נק' בכל, וענין שהם בכלל ברייתו של עולם היינו ע\"ד טוב מאד זה יצה\"ר<sup data-n=\"921\">327</sup>, וע\"ד אלמלא דינא<sup data-n=\"922\">328</sup> כו', וע' ברבות כי תשא פמ\"ג<sup data-n=\"923\">329</sup> בענין מים דמרה כו', ואפשר עד\"ז ג\"כ מאמר הנשים הארורות שאמרו ומן אז חדלנו לקטר למלכת השמים חסרנו כל (בירמי' סי' מ\"ד י\"ח) דהפי' כל היינו על השפעת הגשמיים הנמשכים מק\"נ כו', וע' מזה בעקרים מ\"ג פי\"ח ובעקידה שמ\"ז, וע' בהרמב\"ן פ' חיי שרה<sup data-n=\"924\">330</sup>, וזהו מ\"ש יראו מה' כל הארץ<sup data-n=\"925\">331</sup>, כל הארץ דוקא אף",[["908","314","<b>בחי' המספר</b>: כ\"ה גם בב."],["909","315","<b>בד\"ה ויצום</b>: ראה לעיל שם פ\"ג."],["910","316","<b>בהבראם בה' בראם</b>: בראשית ב, ד. ראה מנחות כט, ב. ב\"ר פי\"ב, ב."],["911","317","<b>שעוה\"ז נברא בה'</b>: מנחות שם."],["912","318","<b>את הוא ל' ריבוי</b>: ראה ירושלמי ברכות פ\"ט, ה\"ה. פסחים כב, ב."],["913","319","<b>ואמנם</b>: מכאן נמצא באוה\"ת כאן ע' א'תתכח — ראה הערה 309. המשך תער\"ב ח\"א ע' קעא."],["914","320","<b>כי כל בשמים ובארץ</b>: דהי\"א כט, יא. ראה זהר בראשית לא, א. ת\"ז תמ\"ז פד, א: ותרגום יונתן. לקמן (בחלק ההנחות) הנחה ד\"ה גדול יהי' על יד הערה 106: ות\"א. מאמרי אדה\"א ויקרא ח\"ב ע' תשמב. וש\"נ."],["915","321","<b>ר\"פ ך\"ב</b>: ס\"ב."],["916","322","<b>ויתרון ארץ בכל היא</b>: קהלת ה, ח."],["917","323","<b>שאתה. . בעולם</b>: וכ\"ה באוה\"ת ובהמשך תער\"ב שבהערה 319. ובויק\"ר שם: שאתם רואים בעולם מיותרים."],["918","324","<b>ופרעושים</b>: וכ\"ה באוה\"ת. ובויק\"ר שם: פרעושים."],["919","325","<b>ויכולו השמים</b>: בראשית ב, א."],["920","326","<b>בקהלת רבה דצ\"ו ע\"ד</b>: והוא בדפוס אמשטרדם ת\"א, ולפנינו פ\"ה, ח (א)."],["921","327","<b>טוב מאד זה יצה\"ר</b>: ראה ב\"ר פ\"ט, ז [ושם דורש מתיבת והנה]. לקמן המשך חייב אדם לברך פי\"ט ד\"ה אמנם (ובהנסמן שם)."],["922","328","<b>אלמלא דינא</b>: זהר קרח קעח, ב."],["923","329","<b>פמ\"ג</b>: ס\"ג."],["924","330","<b>בהרמב\"ן פ' חיי שרה</b>: כד, ב."],["925","331","<b>יראו מה' כל הארץ</b>: תהלים לג, ח. ראה גם אוה\"ת בשלח (כאן ו) ע' תלב. ע' תסא. סה\"מ תרכ\"ז ע' קעו. ע' רמז וע' שנט. תרכ\"ט ע' לח."]]],[2000450142,"מבחי' כל שדרכו למנות שאפי' המזיקים יראים מהשי\"ת, וכמארז\"ל אלמלא ניתנה רשות<sup data-n=\"926\">332</sup> לעין לראות כו', ואעפ\"כ אין עושים כלום מפני מורה שמים כ\"כ עד שלא יוכל לעבור את פי הוי'<sup data-n=\"927\">333</sup>, וכמ\"ש מזה בד\"ה וכל העם רואים את הקולות בת\"א פ' יתרו<sup data-n=\"928\">334</sup>, אך יראה זו היא מרחוק וזהו מה', וצ\"ל בבחי' יראו את הוי' קדושיו<sup data-n=\"929\">335</sup> בבחי' ביטול ממש שזהו פי' את הוי' להיות בבחי' את הטפל<sup data-n=\"930\">336</sup> ממש לש' הוי' שלא להיות לו שום רצון בפ\"ע ועז\"נ אל תיראו<sup data-n=\"931\">337</sup> בבחי' יראה דערב רב דכתיב וירא העם<sup data-n=\"932\">338</sup> וינועו ויעמדו מרחוק כמ\"ש בת\"א סד\"ה וכל העם הנ\"ל<sup data-n=\"933\">339</sup> כ\"א למען תהי' יראתו<sup data-n=\"934\">340</sup> על פניכם, דר\"ל שלא להיות בבחי' ויעמדו מרחוק וייראו מה', כ\"א בבחי' יראו את הוי' כו', וזהו ענין את שדרכו למנות שנינו שהוא המספר העליון ע\"ד ע\"ס שהם בבחי' את הוי' איהו וגרמוהי חד כו', וחכמה היא כח מה<sup data-n=\"935\">341</sup> בחי' ביטול כו', ואפ\"ל כי ב' בחי' מנין אלו שרשם מנין ריבוי הכלים ומנין רבוי האורות, וזהו כי תשא את ראש בנ\"י פי' את ראש שיהיו בבחי' יראו את הוי' כו'.\n<span data-k=\"ks\"><b>קיצור.</b> שיש ב' בחי' מנין הא' כל שדרכו למנות, בחי' כל היינו כמו בורא<sup data-n=\"936\">342</sup> הכל אומרים עמ\"ש ובורא רע, וזהו יראו מה' כל הארץ, הב' את שדרכו למנות יראו את הוי' קדושיו, וזהו כי תשא את ראש בנ\"י, את דוקא.</span>\nיג) <b>ונתנו</b><sup data-n=\"937\">*343</sup> איש כופר נפשו לה' ולא יהי' בהם נגף בפקוד אותם, והענין יובן ע\"פ מארז\"ל פ\"ק דתענית ד\"ח סע\"ב ובפ\"ג דב\"מ דמ\"ב ע\"א הובא לעיל שאין הברכה מצויה אלא בדבר הסמוי מן העין ולא בדבר המדוד והמנוי, וכמ\"ש בש\"ע או\"ח סי' ר\"ל ס\"ב והיינו כי דבר הסמוי מן העין ז\"ע עלמא דאתכסיא אשר שם בחי' הברכה העליונה, כי חו\"ב תרין רעין<sup data-n=\"938\">343</sup> דלא מתפרשין איהו ברוך ואיהי ברכה כמ\"ש בזח\"ב תרומה קס\"ב א' ובפ' ואתחנן דף רס\"ד ע\"ב, וע' בסידור בדרוש ברכת הזימון בענין פי' נברך<sup data-n=\"939\">344</sup>, ובמאו\"א אות ב' סל\"ה, ברכה מצד אימא עילאה כו', ובזח\"ג במדבר קי\"ז ב' דברכתא לא שריא במנינא, ופי' הרמ\"ז ברכתא דלעילא הוא מצד או\"א שבהם כח ונהר יוצא מעדן דלא פסיק לעלמין כו', ושעיקר המספר והמנין הוא בעה\"ד טו\"ר, והיינו בעלמא דאתגליין ולכן שם אין הברכה",[["926","332","<b>אלמלא ניתנה רשות</b>: ראה ברכות ו, א."],["927","333","<b>שלא יוכל לעבור את פי הוי'</b>: ע\"פ בלק כב, יח."],["928","334","<b>בד\"ה וכל העם. . יתרו</b>: עד, ד. וראה גם מאמרי אדה\"א במדבר ח\"ב ע' תתו ואילך."],["929","335","<b>יראו את הוי' קדושיו</b>: תהלים לד, י. ראה הערה 331."],["930","336","<b>את הטפל</b>: ראה ברכות לו, ב."],["931","337","<b>אל תיראו</b>: [תוקן ע\"פ ב] יתרו כ, יז."],["932","338","<b>וירא העם</b>: שם כ, טו."],["933","339","<b>בת\"א. . הנ\"ל</b>: עד, ג."],["934","340","<b>למען תהי' יראתו</b>: ועד\"ז באוה\"ת כאן. יתרו כ, יז [ושם: ובעבור תהי' יראתו]."],["935","341","<b>וחכמה היא כח מה</b>: זהר רע\"מ צו כח, א. לד, א."],["936","342","<b>בורא</b>: באוה\"ת כאן: ובורא."],["937","*343","<b>ונתנו</b>: ראה לקמן הערה 370."],["938","343","<b>חו\"ב תרין רעין</b>: ראה זהר בשלח נו, א. ויקרא ד, א. מאמרי אדה\"א דברים ח\"ב ע' שסו. וש\"נ. תו\"ח בראשית כא, ב ובהערה 8."],["939","344","<b>בסידור. . פי' נברך</b>: שער בהמ\"ז קב, ד."]]],[2000450143,"מצויה כ\"א בעלמא דאתכסיא ששם עה\"ח ובבינה התגלות עתיק<sup data-n=\"940\">345</sup> שהוא ראש ומקור כל ברכה וכמ\"ש בזח\"ב פ' בשלח דס\"ג ע\"ב, וע' בת\"א פ' לך לך בד\"ה לך לך מארצך ענין אברם אברהם ע\"י ההא שניתוסף לו שהוא הבינה בא לו הברכה, וענין הברכה שבבינה זהו ע\"ד נהרא מכיפא מבריך<sup data-n=\"941\">346</sup> ונהר יוצא מעדן הוא בינה<sup data-n=\"942\">347</sup> כו', ופי' וענין מכיפא מבריך ולא חיישינן שמא ירבה נוטפי' כו', שהתוס' והרבוי שלה שמתרבה כשנעשה נהר מכמו שהיתה תחילה בהמעיין שממנו יוצא הנהר הוא ממקורו ומאיליו ומעצמו מתרבה, ובערוך בשם רבינו גרשם מכפיא<sup data-n=\"943\">348</sup> מבריך מגדודותיו<sup data-n=\"944\">349</sup> מתברך שאינו מתגדל מימי<sup data-n=\"945\">350</sup> הגשמים אלא מעצמו וכן פי' רש\"י בנדרים ד\"מ סע\"א, וע' בפרש\"י בשבת דס\"ה ב' משפתו כו' והוא כי תרגום והירדן מלא על כל גדודותיו<sup data-n=\"946\">351</sup> מלא על כל כפוהי (יהושע סי' ג'<sup data-n=\"947\">352</sup> ) שפת הנהר<sup data-n=\"948\">353</sup> כיף נהרא וביחזקאל מ\"ז<sup data-n=\"949\">354</sup> על שפתו על כיפיה, ולא ממי הגשמים, ואף שהמעין אינו בהתפשטות מרובה כ\"כ עכ\"ז אחר שיוצא מהעלם של המעיין לידי גילוי והתפשטות יותר להיות נהר נעשה מאיליו ומעצמו בתוס' מרובה, ויובן זה יותר מבחי' שכל ומדות שהנה עיקר הולדת והמשכת המדות הם מהשכל שכל דבר שיעמוק<sup data-n=\"950\">355</sup> בשכלו ויבין שטוב הוא, יתעורר ממילא אהבה ותשוקה לדבר ההיא<sup data-n=\"951\">356</sup> אשר לזאת בקטן ששכלו קטן מאד מלהכיל ולהבין אזי גם מדותיו הם ג\"כ לדברים קטנים וכמ\"ש לפי שכלו יהולל איש<sup data-n=\"952\">357</sup>, שהמדות שנק' איש נולדים ונמשכים לפי ערך השכל, ונמצא מובן מכל הנ\"ל שכל עיקר המשכת המדות הם מהשכל ואעפ\"כ נראה בחוש שלאחר שבאו מהשכל לידי גילוי בלב נעשו בחוזק ותוס' וריבוי הרבה יותר מכמו שהיו תחילה בעודם בשכלו כו', כמו הכעס וכדומה כו', והיינו כנ\"ל מפני שבשכל עדיין המדה היא בבחי' העלם בתכלית, ולזאת אינה בהתפשטות מרובה כ\"כ, אכן כשבא מהעלם השכל לידי גילוי בלב נעשה ממילא בריבוי התפשטות וחוזק האהבה או הכעס כו', וכיוצא בזה מבואר בע\"ח שכ\"ה דרוש וא\"ו, ובשער תיקון הנוקבא פ\"ה כי כאשר יצאו מהיסוד דאימא ונתגלו כו' ע\"ש, וכמ\"כ הנהר אף שכל עיקר המשכתו מהמעיין, עכ\"ז אחר שיוצא מהעלם המעיין לידי גילוי הנהר מתפשט מאיליו בתוספת מרובה כו', וזהו נהרא מכפי' מבריך, ויובן בעומק יותר עד\"מ בריקת וסקירת השכל ה\"ה עדיין בקיצור נמרץ, וכשמתבונן ומעמיק בבחי' ברק המבריק<sup data-n=\"953\">358</sup> אזי",[["940","345","<b>ובבינה התגלות עתיק</b>: ראה זהר קרח קעח, ב. מאמרי אדה\"א הנחות תקע\"ז ע' ד. וש\"נ. תו\"ח לך פא, ב. ביאוה\"ז להצ\"צ אחרי ע' שסד."],["941","346","<b>נהרא מכיפא </b>[באוה\"ת כאן: מכיפי', וכ\"ה לקמן בהמשך חייב אדם לברך רפכ\"א]<b> מבריך</b>: שבת סה, ב. וראה גם אמ\"ב שער התפילין קכא, סע\"ג ואילך."],["942","347","<b>ונהר יוצא מעדן הוא בינה</b>: בראשית ב, י. ראה תו\"א משפטים עה, ד: כמ\"ש בזהר פ' אמור [צט, א]."],["943","348","<b>מכיפא. . מכפי' מבריך</b>: לשון לקו\"ת [ושם: מכיפי'] שה\"ש לט, א בשינויים."],["944","349","<b>מגדודותיו</b>: ב ובלקו\"ת: מגדותיו."],["945","350","<b>מימי</b>: ב ממי. בלקו\"ת: ממימי."],["946","351","<b>גדודותיו</b>: שם: גדותיו."],["947","352","<b>מלא. . ג'</b>: שם: מלי. . פסוק טו."],["948","353","<b>שפת הנהר</b>: בלקו\"ת: שפת היאור — מקץ מא, ג. יז."],["949","354","<b>וביחזקאל מ\"ז</b>: פסוק יב."],["950","355","<b>שיעמוק</b>: ב ובלקו\"ת: שיעמיק."],["951","356","<b>ההיא</b>: בלקו\"ת: ההוא."],["952","357","<b>לפי שכלו יהולל איש</b>: משלי יב, ח."],["953","358","<b>ברק המבריק</b>: ראה גם בענין ברק המבריק אגה\"ק סוסט\"ו. תו\"א ולקו\"ת כמצויין במפתח ענינים בערכו. תו\"ח בשלח ח\"א קצז, ב. וש\"נ. לקמן מאמר ד\"ה ישמח משה על יד הערה 29. ובחלק ההנחות מאמר ד\"ה היום גלותי על יד הערה 21. ד\"ה ביום ההוא יהי' על יד הערה 11. ד\"ה ישמח משה על יד הערה 44. ד\"ה בנים אתם על יד הערה 83."]]],[2000450144,"מתגדל להיות בבחי' השגה והבנה באורך ורוחב בטוב טעם ודעת, ואם היות מקור כל אריכות ההשגה הלזה באה מהתעוררות ברק המבריק, אמנם באמת ע\"י אורך ורוחב ההבנה מלבד מה שבחי' ברק זה מתבאר היטיב הנה מתוסף הרבה ביתר שאת ג\"כ על בחי' ברק המבריק שהי' תחילה וזהו מעלת הבינה עצמה ואשר בבינה היא בחי' התגלות עתיק לכן ע\"י הבנת הבינה מתוסף הרבה מכמו שהי' תחילה בבחי' ברק המבריק, ומזה יובן ענין נהרא מכפיא מבריך שמתברך מעצמו ומכח ההתגלות שבה לבד מה שנתבאר בחי' ברק המבריק בהרחב הביאור וההשגה, והגם שכל עיקר ענין בחי' הרחב ביאור והבנת הדברים בא מהתעוררות ברק המבריק כו', הלא התחלת הנהר בא ג\"כ מבחי' המעיין כמו שהתחלת ההבנה בא מבחי' ברק המבריק, וההוספה עם בחי' ביאור הדברים באים מעצם בחי' הבינה ומעלתה שבה התגלות עתיק כו', כמו שנהרא מכיפי' מבריך כו'.\n<span data-k=\"ks\"><b>קיצור.</b> הברכה באסמיך עלמא דאתכסי', איהי ברכה ונהר יוצא מעדן ע\"ח והתגלות סוכ\"ע, ונהרא מכיפי' מבריך, ע\"ד שתוקף המדות בהתגלותן דוקא, ובבחי' ההבנה מתוסף מה שלא הי' בבחי' ברק המבריק כו'.</span>\nיד) <b>והנה</b> על בחי' בינה נאמר ולתבונתו אין מספר, והיינו מאחר ששם שורה הברכה, א\"כ יוכל המספר להתרבות בבחי' אין מספר, וכענין מאה שנה דחיי שרה<sup data-n=\"954\">359</sup> שמצד א\"א בא המספר בריבוי יותר בבחי' מאה משא\"כ למטה כו', וז\"ע הברכה להיות התכללות יו\"ד מיו\"ד ואותן היו\"ד ג\"כ מיו\"ד כו', משא\"כ בעלמא דאתגלי' שם לא יוכל להשתנות דבר, וכמ\"ש במ\"א בלק\"ת בד\"ה צו את בנ\"י<sup data-n=\"955\">360</sup> כו' את קרבני לחמי, שמצד בחי' ממכ\"ע אין יוכל להשתנות דבר, אלא כמו שהוא כך נשאר כמו שמהרגל אי אפשר להעשות יד, ולא מהיד רגל כו' כ\"א דוקא מבחי' סוכ\"ע יוכל להשתנות הדבר מן הקצה אל הקצה, וז\"ע ההפרש בין עלמא דאתגליא שכבר הוברר כל דבר על מקומו בהתחלקות כל בחי' בפ\"ע ע\"כ לא יוכל להשתנות ולהתברך, אבל בעלמא דאתכסיא שם השראת סוכ\"ע יוכל להיות תוס' ברכה וריבוי כו'. אמנם מבואר במ\"א ענין קי\"ס הפך ים ליבשה<sup data-n=\"956\">362</sup>, הוא שעלמא דאתכסי' יומשך בגילוי ממש כמו עלמא דאתגלי', והוא שינוי סדר ההשתלשלות כדי להיות גילוי המשכת התורה במ\"ת, כי כל עיקר התומ\"צ הוא להמשיך גילוי סוכ\"ע בממכ\"ע והיינו שמעלמא דאתכסיא יאיר בגילוי בעלמא דאתגליא, וזהו ענין דירה בתחתונים, וכדי להיות גילוי זה הוצרך להיות ע\"י המשכה מעצמיות בחי' אוא\"ס ב\"ה השוה ומשוה כו' כמ\"ש כ\"ז בת\"א פ' בשלח<sup data-n=\"957\">361</sup>",[["954","359","<b>מאה שנה דחיי שרה</b>: חיי שרה כג, א. ראה גם מאמרי אדה\"א בראשית ע' רלג. וש\"נ."],["955","360","<b>בלק\"ת בד\"ה צו את בנ\"י</b>: פינחס עה, ג."],["956","362","<b>הפך ים ליבשה</b>: תהלים סו, ו."],["957","361","<b>ענין קי\"ס. . בת\"א פ' בשלח</b>: סג, א."]]],[2000450145,"בד\"ה אשירה להוי' כי גאה גאה, וכיון שגם בעלמא דאתגליא מאיר ממש בחי' עלמא דאתכסיא א\"כ אזי גם שם מאיר ומתגלה בחי' סוכ\"ע, ועז\"נ והי' מספר בנ\"י כחול הים אשר לא יספר כו', שגם בחי' המספר שהוא עלמא דאתגלי' יהי' בו ברכה עצומה כמו בבחי' אשר לא יספר בחי' ולתבונתו אין מספר, והיינו שיהי' בבחי' חול הים ים הוא עלמא דאתכסיא, וזהו עצמו ההפרש בין מספר ומנין דבחי' את שדרכו למנות ובין מנין בבחי' כל שדרכו למנות, כי הנה בקרי\"ס כתיב ויראו העם את הוי'<sup data-n=\"958\">363</sup> שאזי דוקא באו העם לבחי' ויראו את הוי' ע\"ד יראו את הוי' קדושיו, את דוקא שהוא בחי' ביטול ממש, את הטפל כו', וכמו הברואים שבים שאינם יכולים להיות נפרד מהים, ולא כמו ברואים שביבשה שנראים ליש ודבר נפרד כו', כי הים מכסה עליהם, וחיותם וקיומם הוא בתוך הים דוקא, וכך במשה כתיב כי מן המים משיתיהו<sup data-n=\"959\">364</sup> שהי' בטל במציאות במקורו בחי' סוכ\"ע דכולא קמי' כלא חשיב, וזהו ענין ויראו<sup data-n=\"960\">365</sup> את הוי', שזכו לזה נש\"י בקי\"ס דוקא, וא\"כ המספר והמנין בבחי' זו נק' את שדרכו למנות, ולכן בבחי' מספר זה שורה בו הברכה ע\"ד חול<sup data-n=\"961\">366</sup> אשר לא יספר כו', כיון שאם היותן בבחי' מספר הם בבחי' ביטול לגמרי, וביטול זה הוא ליחידו של עולם, וע\"כ נק' בלשון יחיד כמו שבעים נפש דיעקב<sup data-n=\"962\">367</sup> שאם היותן שבעים נקראו נפש לשון יחיד מצד הביטול, ועד\"ז נאמר ויחן שם ישראל<sup data-n=\"963\">368</sup> ועמ\"ש מזה ע\"פ וקבל היהודים<sup data-n=\"964\">369</sup> וקבל לשון יחיד כו', וזהו את שדרכו למנות שאם היותן דבר שבמנין הם בבחי' את הטפל ממש כביטול זיו השמש בשמש, וע\"כ ממספר זה אין שום יניקה לחיצונים להיות נגף ח\"ו, שהרי הוא אחדות גמור כו'.\n<span data-k=\"ks\"><b>קיצור.</b> ולתבונתו אין מספר, כי מצד ממכ\"ע לא יוכל להשתנות דבר, אבל סוכ\"ע כל יכול, ולכן בעלמא דאתגליא אין הברכה מצויה, אך קרי\"ס גילוי עלמא דאתכסיא בעלמא דאתגלי' ע\"י כי גאה גאה, ואזי כחול הים אשר לא יספר, ומספר זה נק' את שדרכו למנות, כי בקרי\"ס ויראו העם את הוי', וא\"כ המספר דבוק בבחי' אין מספר ואינו נפרד בפ\"ע וכמו מאה שנה, ושבע שנים, שבבחי' כתר כל המאה שהם מספר רב הם לשון יחיד, שנה ע\"י בחי' הביטול לבחי' חד ולא בחושבן כו'.</span>",[["958","363","<b>ויראו </b>[ב ובאוה\"ת: וייראו]<b> העם את הוי'</b>: בשלח יד, לא."],["959","364","<b>כי מן המים משיתיהו</b>: שמות ב, י. ראה גם לקמן המשך חייב אדם לברך פל\"ב על יד הערה 1280."],["960","365","<b>ויראו</b>: ב: ייראו. באוה\"ת כאן ע' א'תתל: יראו."],["961","366","<b>חול</b>: באוה\"ת כאן: חול הים."],["962","367","<b>שבעים נפש דיעקב</b>: ויגש מו, כז. ראה ויק\"ר פ\"ד, ו. רש\"י ויגש מו, כו. סה\"מ תרל\"ג ח\"ב ע' תקלד בשם הה\"מ. תרכ\"ז ע' ריח. שע\"ת עג, ד ובהערה 87."],["963","368","<b>ויחן שם ישראל</b>: יתרו יט, ב."],["964","369","<b>ע\"פ וקבל היהודים</b>: אסתר ט, כג. ראה תו\"א מג\"א צז, סע\"ד ואילך. מאמרי אדה\"ז תק\"ע ע' לט. מאמרי אדה\"א נ\"ך ע' תנז. שערי אורה צב, א. צג, א ואילך. לקמן המשך חייב אדם לברך פי\"ט על יד הערה 690."]]],[2000450146,"<h3>כל העובר כו' ונתנו איש כופר כו'</h3>\nטו) <b>וזהו</b><sup data-n=\"965\">370</sup> שארז\"ל בירושלמי פ\"ק דשקלים ה\"ו<sup data-n=\"966\">371</sup> ע\"פ כל העובר על הפקודים<sup data-n=\"967\">372</sup> מאן דעבר על ימא כו', כי בעברם בים זכו לבחי' ייראו<sup data-n=\"968\">373</sup> את כו' כנ\"ל, והנה בנשמה יש ג\"כ ב' בחי' חלק המלובש בגוף הוא מעלמא דאתגליא, והמקיף מעלמא דאתכסיא וזהו כי תשא את ראש כו' להעלות לקשרם בבחי' מזליה כמ\"ש בקרי\"ס עד יעבור עמך ה'<sup data-n=\"969\">374</sup>, ואזי הם בבחי' התכללות כו' והמספר דבוק בבחי' חד ולא בחושבן כו', והנה כדי להעלות הנשמה שבגוף צריך לשית כופר נפשו, לפדות נפשו האלקית מתוך מאסר הגוף ונפשו הבהמית והפדיון הוא ע\"י צדקה כר\"א דיהיב פרוטי לעני<sup data-n=\"970\">375</sup> והדר מצלי כו' כמ\"ש בלק\"ת סד\"ה וארשתיך כו' בצדק<sup data-n=\"971\">376</sup>. וכמ\"ש באגה\"ק בד\"ה אין ישראל נגאלין אלא בצדקה<sup data-n=\"972\">377</sup> ע\"ש באריכות. וכתיב וצדקה תרומם גוי<sup data-n=\"973\">378</sup> כמ\"ש בת\"א ר\"פ בראשית בענין והארץ הדום רגלי<sup data-n=\"974\">379</sup>.\n<b>ועוד</b> זאת דעיקר הטעם שבדבר המנוי אינו שורה הברכה מחמת ששם יש יניקה לבחי' רע עין כו' שהוא הס\"ם כמ\"ש במאו\"א אות ע' ססעי'<sup data-n=\"975\">380</sup> י\"ד, ועיין ברבות באסתר ע\"פ וירא המן<sup data-n=\"976\">381</sup> כו' ויראו בני האלקים<sup data-n=\"977\">382</sup> את בנות האדם כו' וירא חם אבי כנען<sup data-n=\"978\">383</sup> כו', ועז\"נ תחשכנה עיניהם מראות<sup data-n=\"979\">384</sup> לפי שמראות עיניהם מורידות אותם לגיהנם, ושרש בחי' ראי' זו ז\"ע רע עין הנ\"ל, וז\"ס היזק ראי', והרמ\"ז ס\"פ<sup data-n=\"980\">385</sup> פקודי דף רך\"ה ע\"ב פי' שב' סגולות הן אל העינים א' הוא<sup data-n=\"981\">386</sup>",[["965","370","<b>וזהו</b>: ברשימת המאמרים שמופיע בריש הבוך נרשם כאן מאמר (ה' מההמשך והוא) ד\"ה: כל העובר על הפקודי' (פט\"ו. או כפי הנרשם לעיל במפתח המאמרים שבריש הספר (כנראה ע\"פ ב) פרקים יג—טו).\nלמאמר זה ראה אוה\"ת תשא ע' א'תתלא ואילך."],["966","371","<b>ה\"ו</b>: וכ\"ה באוה\"ת כאן וע' א'תתקד. ולפנינו סה\"ג."],["967","372","<b>כל העובר על הפקודים</b>: תשא ל, יג."],["968","373","<b>ייראו</b>: באוה\"ת כאן: יראו."],["969","374","<b>עד יעבור עמך ה'</b>: בשלח טו, טז."],["970","375","<b>כר\"א דיהיב פרוטי לעני</b>: ב\"ב י, א. באוה\"ת כאן: אלעזר. ובלקו\"ת שבהערה הבאה: אליעזר."],["971","376","<b>בלק\"ת. . בצדק</b>: במדבר ח, סע\"ד ואילך."],["972","377","<b>באגה\"\"ק. . בצדקה</b>: ס\"ד ע' קו."],["973","378","<b>וצדקה תרומם גוי</b>: משלי יד, לד [ושם צדקה — אבל כ\"ה בכ\"מ ומהם: תו\"א וישב כט, ג. לקו\"ת יו\"כ סט, ג. שה\"ש ו, ד. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תשיב וע' תשכג. תק\"ע ע' קכח וע' קנב. מאמרי אדה\"א בראשית ע' שצט. ויקרא ח\"ב ע' תשא. וש\"נ. במדבר ח\"ג ע' א'מז. אוה\"ת כאן. תרומה ע' א'שפ. לקמן מאמר ד\"ה בנים אתם על יד הערה 21. שם בין הערות 125-126. 80-81. 70-71. 65-66. ד\"ה שלש רגלים (בהוספה) על יד הערה 16. המשך תער\"ב ח\"א ע' תקו]."],["974","379","<b>בת\"א. . רגלי</b>: בראשית א, ב. (הובא) לקמן מאמר ד\"ה ומקנה רב על יד הערה 86. ובחלק ההנחות על יד הערה 126."],["975","380","<b>ססעי'</b>: סוף סעיף."],["976","381","<b>ברבות אסתר ע\"פ וירא המן</b>: פ\"ז, ט. אסתר ג, ה."],["977","382","<b>ויראו בני האלקים</b>: בראשית ו, ב."],["978","383","<b>וירא חם אבי כנען</b>: נח ט, כב."],["979","384","<b>תחשכנה עיניהם מראות</b>: תהלים סט, כד."],["980","385","<b>ס\"פ</b>: כ\"ה גם באוה\"ת כאן. וראה אוה\"ת שה\"ש ע' שלא."],["981","386","<b>הוא</b>: ב־ רמ\"ז ובאוה\"ת כאן: היא. אבל באוה\"ת שה\"ש ע' שלח וע' שלט כבפנים."]]],[2000450147,"הראי' וההכרה<sup data-n=\"982\">387</sup> שהדבר הנראה<sup data-n=\"983\">388</sup> מצטייר באשון בת עין של הרואה והמביט<sup data-n=\"984\">390</sup>, ב' היא שהרואה שולח<sup data-n=\"985\">391</sup> ניצוצי אורו שיש בהם עצמיות גמור כמ\"ש הרב ממשל בת היענה כו', וע' מענין רע עין בזהר פ' אחרי דס\"ג ע\"ב, ובמד\"ש פ\"ה דאבות במשנה עין טובה ורוח נמוכה ונפש שפלה מתלמידיו של א\"א פי' כי עין טובה נמשך מבחי' ואהבת לרעיך כמוך<sup data-n=\"986\">392</sup>, ועין רעה בהיפך זה, והרי ואהבת לרעיך כמוך זהו כלל התורה כולה כו' ואידך פירושא היא<sup data-n=\"987\">393</sup>, ולכן איתא פ\"ב דאבות<sup data-n=\"988\">394</sup> איזהו דרך ישרה שידבק בה האדם ר' אליעזר אומר עין טוב, וכן אמרו<sup data-n=\"989\">395</sup> עין הרע ויצה\"ר מוציאין את האדם מן העולם, וז\"ש בגמ' פ\"ט דב\"מ דק\"ז ע\"ב ע\"פ והסיר ה' ממך כל חולי<sup data-n=\"990\">396</sup> אמר רב זו עין כו' צ\"ט בעין הרע כו', דיש לפרש היינו קטרוג הס\"מ שנק' עין הרע כנ\"ל, ובלעם נק' עין רעה י\"ל עין זהו הנבואה כמ\"ש במד\"ר תצוה פל\"ח<sup data-n=\"991\">397</sup> ע\"פ בדד עין יעקב<sup data-n=\"992\">398</sup>, וכתיב ולא קם עוד בישראל נביא כמשה<sup data-n=\"993\">399</sup> וארז\"ל במד\"ר נשא ס\"פ י\"ד<sup data-n=\"994\">400</sup> בישראל לא קם אבל באומות קם ומנו זה בלעם, א\"כ לכן נק' עין המורה על הנבואה, אבל עכ\"ז כיון שהי' רשע ואע\"פ שראה מה שראה לא נתבטל מהיש והתאוה שלו ע\"כ נק' עין רעה כו'.\n<b>והנה</b> איתא בזרעא דיוסף לא שלטי בהו עינא בישא<sup data-n=\"995\">401</sup> שנמשלו לדגים שבים, ופי' הטעם בזח\"ג נשא דק\"ל ע\"ב<sup data-n=\"996\">402</sup> מפני שזכה לאשתגחא בעינא עילאה דע\"ק עינא פקיחא דלא נאים כו' וזהו בן פורת עלי עין<sup data-n=\"997\">403</sup> המאיר בעלמא דאתכסיא בחי' ים וביוסף הי' מאיר בחי' זו גם בעלמא דאתגליא וזהו עיני הוי' אל צדיקים כמ\"ש סד\"ה כי תשמע בקול בפי' לעשות הישר בעיני ה'<sup data-n=\"998\">404</sup>, וכיון שמאיר עליו עיני ה' בב' סגולות שכ' הרמ\"ז כו', ממילא לא יוכל כלל הראי' של עין הרע לנגוע בו כלל, כי האור ההוא מסמא עיניו, במכ\"ש מאור השמש שמכהה הראות כו', והנה יוסף זכה לזה ע\"י הצדקה, וזהו ג\"כ ונתנו איש כופר נפשו כו' שע\"י",[["982","387","<b>וההכרה</b>: ברמ\"ז ובאוה\"ת: והכרה. אבל באוה\"ת שה\"ש ע' שלא. ע' שלח וע' שלט כבפנים."],["983","388","<b>שהדבר הנראה</b>: וכ\"ה באוה\"ת. וברמ\"ז: שהמובט. וכ\"ה באוה\"ת שה\"ש שם.\n389)באשון: ב־ ברמ\"ז ובאוה\"ת כאן: באישון."],["984","390","<b>של הרואה והמביט</b>: וכ\"ה באוה\"ת. וברמ\"ז: ליתא."],["985","391","<b>שהרואה שולח</b>: וכ\"ה באוה\"ת. וברמ\"ז: הסגולה ששולח. ועד\"ז באוה\"ת שה\"ש ע' שלח."],["986","392","<b>ואהבת לרעיך </b>[ב ובאוה\"ת: לרעך]<b> כמוך</b>: קדושים יט, יח."],["987","393","<b>ואהבת. . פירושא היא</b>: ראה שבת לא, א."],["988","394","<b>פ\"ב דאבות</b>: ראה שם מ\"ט. ולגי' אדה\"ז בסידורו מ\"י."],["989","395","<b>וכן אמרו</b>: ראה שם מי\"א."],["990","396","<b>והסיר ה' ממך כל חולי</b>: עקב ז, טו."],["991","397","<b>פל\"ח</b>: ס\"ד."],["992","398","<b>בדד עין יעקב</b>: ברכה לג, כח."],["993","399","<b>ולא קם. . כמשה</b>: וכ\"ה באוה\"ת כאן. ברכה לד, י [ושם: נביא עוד בישראל — וכ\"ה בב]."],["994","400","<b>ס\"פ י\"ד</b>: ס\"כ."],["995","401","<b>בזרעא דיוסף. . עינא בישא</b>: ברכות כ, א."],["996","402","<b>ע\"ב</b>: באוה\"ת כאן: ע\"א."],["997","403","<b>בן פורת עלי עין</b>: ויחי מט, כב."],["998","404","<b>כמ\"ש סד\"ה. . בעיני ה'</b>: לק\"ת תצא כד, ג."]]],[2000450148,"מחצית השקל ימשיך בחי' עיני הוי' אל צדיקים וממילא לא ישלוט בהם עינא בישא ח\"ו, וזהו והסיר ה' ממך כל חולי זו עין, והיינו ע\"י השגחתו ית' בבחי' עיני הוי' אל צדיקים, ועמך כולם צדיקים<sup data-n=\"999\">405</sup>, ועמ\"ש מזה ע\"פ יונתי בחגוי הסלע כו' הראיני<sup data-n=\"1000\">406</sup> כו'.\n<span data-k=\"ks\"><b>קיצור.</b> כל העובר, בים, ויראו<sup data-n=\"1001\">407</sup> את, עד יעבור עמך ה', וצדקה תרומם גוי, ענין טוב עין, ורע עין, הנבואה נק' ראי' ועין, וביוסף עלי עין, ע\"כ וידגו לרוב בקרב הארץ<sup data-n=\"1002\">408</sup>, ועמ\"ש ע\"פ עין בעין<sup data-n=\"1003\">409</sup> נראה אתה ה' ושזה יש בתפלה ב' בחי' עין המתחברים יחד ע' סידור בד\"ה ששת ימים<sup data-n=\"1004\">410</sup> תאכל מצות דרוש הראשון ובהביאורים.</span>",[["999","405","<b>ועמך כולם צדיקים</b>: ישעי' ס, כא."],["1000","406","<b>ע\"פ יונתי. . הראיני</b>: ראה אוה\"ת שה\"ש ח\"א ע' שיד. ע' שלא ואילך. ע' שלז ואילך. ע' שמג ואילך. כרך ג' ס\"ע תתפו ואילך."],["1001","407","<b>ויראו</b>: באוה\"ת כאן: וייראו."],["1002","408","<b>וידגו לרוב בקרב הארץ</b>: ויחי מח, טז."],["1003","409","<b>ע\"פ עין בעין</b>: שלח יד, יד."],["1004","410","<b>בסידור בד\"ה ששת ימים</b>: שער חה\"מ רפז, סע\"ד ואילך."]]],[2000450149,"<h3>חייב אדם לברך ק' ברכות</h3>\n<b>בס\"ד</b>\n&lt;א&gt;\nּ<b>חייב</b> אדם לברך<sup data-n=\"1005\">1</sup> מאה ברכות בכ\"י<sup data-n=\"1006\">2</sup>, שנאמר ועתה ישראל<sup data-n=\"1007\">3</sup> מה ה' אלקיך שואל, א\"ת מ\"ה אלא מאה<sup data-n=\"1008\">4</sup>, ולכאורה צ\"ל הלא כתיב מ\"ה ולא מאה והאיך אומר<sup data-n=\"1009\">5</sup> א\"ת מה אלא מאה כו'. הנה במספר ברכות אלו נכללים ברכת הנהנין וברכת המצות וברכת התפילה, ולכן בשבת שאין מתפללים שמונה עשרה כ\"א ז' ברכות",[["1005","1","<b>חייב אדם לברך</b>: ”מכאן ועד סד\"ה הי' ר\"מ אומר הוא המשך הנודע בשם ”חייב אדם לברך תרל\"ח\" ונדפס בשם: לקו\"ת תורת שמואל ש\"ה. ובו מתבארים בארוכה עניני ד\"ה להבין ענין הברכות שבתו\"א ובלקו\"ת לג\"פ (לקו\"ת תורת שמואל ש\"א)\" — רשימת מאמרי דא\"ח של כ\"ק אדמו\"ר מהר\"ש ע' 46 הערה 5.\nההמשך כולל י\"ט מאמרים (מ\"ב פרקים), להלן באים שמות הדרושים כפי שנרשמו במפתח הבוך 1089 שכולל דרושים של שנה זו תרל\"ח (כשלידם נרשם הדף מקומו של המאמר בהבוך). והתאריכים שנסמנו לקמן הם (פרט במקום שנרשם אחרת) כפי שהם מופיעים בהנחת כ\"ק אדמו\"ר מהורש\"ב. לע\"ע לא נתברר אם רשימה זו היא גוכתי\"ק של כ\"ק אדמו\"ר מהר\"ש, או שזהו כת\"י של המעתיק (הפרקים שצויינו לקמן לא נרשמו במפתח הבוך).\nא) חייב אדם לברך — ש\"פ תזריע (פרקים א-ג).\nב) ברוך ה' אלקי ישראל — ש\"פ מצורע (פרקים ד-ה). ברשימה דלקמן: שה\"ג — פ' מצורע חל בשה\"ג.\nג) להבין ענין אכילת מצה — ליל ב' של חה\"פ (פרקים ו-ח).\nד) ביום ההוא יהי' הוי' א' — ש' חוה\"פ (פ\"ט).\nה) אז ישיר משה ובנ\"י — אחרון ש\"פ (פרקים י-יא). ברשימה דלקמן: שש\"פ.\nו) אר\"א אר\"ח ת\"ח מרבי' שלום (פי\"ב). ברשימת כת\"י מבוך מאסקבא מס' 248: אחרון ש\"פ.\nז) ושמרתם את חוקותי ואת משפטי — ש\"פ אחרי (פרקים יג-טו).\nח) כל הנהנה מעוה\"ז בלא ברכה — ש\"פ קדושים (פרקים טז-יז).\nט) מקום שאמרו להאריך — ש\"פ אמור (פרקים יח-יט).\nי) היושבת בגנים (פרקים כ-כב).\nיא) גל עיני ואביטה נפלאות — ל\"ג בעומר (פרקים כג-כה).\nיב) אם בחוקותי תלכו — ש\"פ בחוקותי (פרקים כו-כח).\nיג) כי ממך הכל (פרקים כט-ל). ברשימה הנ\"ל: במדבר.\nיד) בשחר מברך שתים (פרקים לא-לב).\nטו) גדול העונה אמן (פרקים לג-לד). ברשימה הנ\"ל: בהעלותך.\nטז) שלח לך אנשים (פרקים לה-לו).\nיז) פיה פתחה בחכ' (פרק לז). ברשימה הנ\"ל: קרח.\nיח) צור תעודה חתום תו' — פ' חו\"ב ע\"פ בוך 145 ע' מא — (פרקים לח-לט).\nיט) הי' רמ\"א חייב אדם לברך מ\"ב — פ' פינחס ע\"פ בוך 145 ע' מה — (פרקים מ-מב). ברשימה הנ\"ל: חקת — ראה הנרשם במאמר שלפנ\"ז.\nלמאמר זה לפ\"א — ראה ביאוה\"ז עקב קיח, א-ב. לפ\"ב — ראה ביאוה\"ז שם קיח, ב. ולהצ\"צ כרך א ע' תקעא [נדפס גם באוה\"ת עקב ע' תקמח]. תו\"א בראשית ו, א-ב. לפ\"ג — ראה תו\"א שמות נג, ריש ע\"ב.\nהנחת כ\"ק אדמו\"ר מהורש\"ב נדפסה לקמן בחלק ההנחות.\nההמשך נדפס מבוך 1089 גוכתי\"ק כ\"ק אדמו\"ר מהר\"ש־ ומפכ\"א ואילך כת\"י מעתיק וגוכתי\"ק כמצויין לקמן במקומו. המשך זה הנדפס (כנ\"ל) נסמן לקמן בהערות: ב."],["1006","2","<b>חייב. . מאה ברכות בכ\"י</b>: מנחות מג, ב."],["1007","3","<b>ועתה ישראל</b>: עקב י, יב."],["1008","4","<b>א\"ת מה אלא מאה</b>: ראה לקמן פמ\"ב. שו\"ע אדה\"ז הל' ברכות השחר רסמ\"ו. הנסמן במאמרי אדה\"א דברים ח\"א ע' קכז."],["1009","5","<b>והאיך אומר</b>: ראה גם לקמן פמ\"ב. המשך מים רבים תרל\"ו פקצ\"ח ע' רכח. מאמר ד\"ה ועתה ישראל תשכ\"ח בתחלתו [קונט' כ' מנ\"א תנש\"א — סה\"מ מלוקט ח\"ה ע' שמא]."]]],[2000450150,"מצוה להרבות בשארי ברכות כמו באכילת פירות<sup data-n=\"1010\">6</sup> בכדי להשלים מספר מאה ברכות, ולהבין זה צ\"ל שרש ענין הברכות, הנה בזח\"ג עקב דר\"ע סע\"א<sup data-n=\"1011\">7</sup> פי' בגין<sup data-n=\"1012\">8</sup> דברכתא<sup data-n=\"1013\">9</sup> דבריך ב\"נ לקוב\"ה אתא לאמשכא חיין ממקורא דחיי'<sup data-n=\"1014\">10</sup> לשמי' דקוב\"ה קדישא, פי' מקורא דחיין היינו בחי' אור הכתר דאצי' שהוא נק' בחי' מקור ושרש לכל הנאצלים ולכל המשכת המוחין שבאצי' להביא ולהמשיך בהן תמיד בחי' אור חדש שזהו דוקא הנק' ברכה, והטעם שבבחי' הכתר דוקא ידוע להיותו בחי' הממוצע בין המאציל לנאצלים כמ\"ש בע\"ח<sup data-n=\"1015\">11</sup> וע\"כ גם בחי' תוס' אור חדש הנק' ברכה צריך ג\"כ לבוא ע\"י בחי' הכתר, להיותו בחי' ממוצע לעורר ג\"כ בחי' המשכה חדשה מעצמיות המאציל כו' (ועכ\"ז הברכה אינה כמו תפילה שע\"י התפילה נמשך אור חדש לגמרי<sup data-n=\"1016\">12</sup> כמשי\"ת אי\"ה משא\"כ ע\"י הברכה נמשך רק ממקור לבד כו'), והגם שאמרו בזהר שאו\"א דאצי' נקראו תרין ריעין<sup data-n=\"1017\">13</sup> דלא מתפרשין וזיווגייהו תדיר<sup data-n=\"1018\">14</sup> כו', וא\"כ בהכרח יש אור שפע תמידית מאור הכתר לחו\"ב וכמ\"ש והחכ' מאין תמצא<sup data-n=\"1019\">15</sup>, אך הנה מ\"מ ענין הברכה במצות ברכת המזון להיותו בחי' אור חדש דוקא צריך לעורר ולהביא אור המשכה חדשה ע\"י בחי' הכתר דוקא כדי שיבא אור חדש מעצמיות המאציל (הכוונה מבחי' עתיק שהוא מחצה העליון דכתר בחי' התחתונה שבמאציל, שגם בחי' זו בכלל מקור יחשב, ואינו דבר חדש לגמרי כמו ההמשכה שע\"י התפילה רק לגבי בחי' זיווג דאו\"א שית' נחשב אור חדש להיותו מלמעלה מאצי' שכבר נאצל כו'), משא\"כ בבחי' זיווג דאו\"א אינו מאיר רק מה שכבר נאצל ולא אור חדש, וכמ\"ש בע\"ח דיחוד או\"א<sup data-n=\"1020\">16</sup> אינו אלא לצורך קיום",[["1010","6","<b>בשבת. . באכילת פירות</b>: ראה שו\"ע אדה\"ז הל' ברכות השחר רסמ\"ו. הל' שבת סרפ\"ד, ס\"ז. רסר\"צ."],["1011","7","<b>בזח\"ג עקב דר\"ע סע\"א</b>: וכ\"ה גם בהמשך תער\"ב ח\"ג ע' א'ת [ששם הועתק קטע זה בשינוי קל]. ובביאוה\"ז שבהערה הבאה: [ס]ע\"ב."],["1012","8","<b>בגין</b>: מכאן ועד לקמן פ\"ב על יד הערה 32 הוא לשון הביאורי זהר עקב קיח, א ואילך בשינויים והוספות."],["1013","9","<b>דברכתא</b>: וכ\"ה גם בביאוה\"ז שם. המשך תער\"ב שם. ובהנחה מדרוש זה — שנדפס לקמן בחלק ההנחות — על יד הערה 8. אבל במאמרי אדה\"ז תקס\"ז ע' שלו [שהוא הנחת הר\"מ בן כ\"ק אדה\"ז מדרוש זה] ובזהר: דברכאן."],["1014","10","<b>דחיי'</b>: וכ\"ה גם בביאוה\"ז ובהמשך תער\"ב שם. ב־ תקס\"ז ובזהר: דחיי. וכ\"ה בסמוך בפנים על יד הערה 18. ועוד."],["1015","11","<b>הכתר. . הממוצע. . בע\"ח</b>: ראה שם שער דרושי אבי\"ע שמ\"ב, פ\"א. מאמרי אדה\"א ויקרא ח\"ב ע' תס. וש\"נ. תו\"ח שמות ח\"א יא, ג. וש\"נ. סה\"מ תרכ\"ז ע' שמח."],["1016","12","<b>התפילה נמשך אור חדש לגמרי</b>: ראה לקמן פמ\"א ואילך. סה\"מ תרכ\"ז ע' שצד. וש\"נ. תרכ\"ט ע' ב. וש\"נ."],["1017","13","<b>שאו\"א. . תרין ריעין</b>: ראה זהר בשלח נו, א. ויקרא ד, א. מאמרי אדה\"א דברים ח\"ב ע' שסו. וש\"נ. תו\"ח בראשית כא, ב ובהערה 8."],["1018","14","<b>שאו\"א. . וזיווגייהו תדיר</b>: ראה זהר אד\"ז האזינו רצ, ב. ע\"ח שער הכללים פי\"ג. לקו\"ת שה\"ש כ, ב ואילך. מאמרי אדה\"א בראשית ע' שנו ואילך. דברים ח\"ג ס\"ע תתפט ואילך. הנחות תקע\"ז ע' קיז ואילך. תו\"ח נח מו, ג הערה 25. יתרו ח\"ב עדר, רע\"ד. סה\"מ תרכ\"ט ע' רפח. תרל\"ד ע' עג ובהנסמן בהנ\"ל. לקמן מאמר ד\"ה וידבר וכו' אלה הם מועדי על יד הערה 104 ואילך. ו(בחלק ההנחות) בהנחה שם על יד הערה 82. בסמוך בהערה 16. וראה גם מאמרי אדה\"ז תקס\"ה ח\"ב ע' תשסא הובא לקמן במאמר ד\"ה ישמח משה על יד הערה 99־ ד\"ה מה יפו על יד הערה 40 [ושם: בפע\"ח בהקדמה]."],["1019","15","<b>והחכ' מאין תמצא</b>: איוב כח, יב."],["1020","16","<b>בע\"ח דיחוד או\"א</b>: ראה שם שער הכללים ספ\"ה. פי\"ג. שער הזיווגים שט\"ו, פ\"א. שער הנסירה שכ\"ט, רפ\"ב. לקמן (בחלק ההנחות) הנחה ד\"ה וידבר וכו' אלה הם מועדי ובהערה 82 [ושם: פע\"ח]. פרדס שער מהות והנהגה ש\"ח, פי\"ד. לעיל הערה 14."]]],[2000450151,"העולמות דהיינו לחדש הישנות בלבד (וא\"כ כוונתינו בזה על בחי' יחוד חיצוני דחו\"ב, אבל בחי' יחוד הפנימי דחו\"ב ממשיך אור חדש לגמרי, ובאמת זהו ע\"י מס\"נ דק\"ש והמשכת או\"ח דתפילה<sup data-n=\"1021\">17</sup> שזהו למעלה מבחי' ברכה וכמשי\"ת אי\"ה), וזהו שאמר בזהר דברכתא דבריך ב\"נ לקוב\"ה שהוא בחי' ז\"א אתא לאמשכא חיין ממקורא דחיי<sup data-n=\"1022\">18</sup> פי' בחי' אור חדש ע\"י אמצעית אור הכתר וזהו דכתיב וברכת את ה' אלקיך<sup data-n=\"1023\">19</sup> דקאי על בחי' או\"א שנק' הוי' אלקיך ועליהם ג\"כ יאיר אור חדש הנק' ברכה, ופי' לשמיא<sup data-n=\"1024\">20</sup> דקוב\"ה קדישא תי' קדישא זה קאי אתיבת שמיא, והיינו כאילו אמר לשמיא קדישא דקוב\"ה, ור\"ל בחי' המל' שנק' שמי' דקוב\"ה כידוע בפי' ויעש דוד שם<sup data-n=\"1025\">21</sup> נק' שמי' קדישא להיותה מקבלת משרשה מבחי' אור אבא שנק' קדש<sup data-n=\"1026\">22</sup> כידוע משום דאבא יסד ברתא<sup data-n=\"1027\">23</sup>, וכידוע ששרש הדבור נמשך &lt;ב&gt;\nּ מבחי' חכמה, ועד\"מ התינוק קודם שיגיע לעת החכמה לא יוכל לצרף אותיות הדבור, וכמו שמתרגמינן ויהי האדם לנפש חי' לרוח ממללא<sup data-n=\"1028\">24</sup>, ובכאן שממשיכין או\"ח מבחי' הכתר שנק' מקור, אמר להיכן באה עיקר סיום שפע זאת לזה אמר לשמי' דקוב\"ה קדישא, לפי שנעוץ סופן בתחילתן<sup data-n=\"1029\">25</sup>, ותחילתן בסופן דהיינו מכתר למל', וזהו פי' וברכת את הוי' פי' את היינו את הטפל<sup data-n=\"1030\">26</sup> דהיינו בחי' המל' שעולה למעלה לקבל ברכת הארה המשכה חדשה מעצמיות המאציל, וזהו ג\"כ ענין כוס של ברכה, כוס בגימ' אלקי'<sup data-n=\"1031\">27</sup> בחי' מל'<sup data-n=\"1032\">28</sup> כו' וע\"י הברכה נמשך עד בחי' הכוס בחי' מל', וא\"כ הכוס הוא המקבל הברכה וזהו כוס של ברכה כו'.\n<span data-k=\"ks\"><b>קיצור.</b> שרש ענין הברכות לאמשכא חיין ממקורא דחיי שהוא בחי' אור הכתר, בחי' או\"ח, והגם שגם או\"א זיווגייהו תדיר זהו ממה שכבר נאצל, אבל ע\"י הברכה ממשיכים מהמקור, וההמשכה היא לשמא דקדב\"ה קדישא היינו בחי' המל' שנק' שמא קדישא ששרשה מהחכ', וזהו וברכת את, נסוב\"ת ותחב\"ס.</span>",[["1021","17","<b>יחוד הפנימי. . מס\"נ דק\"ש. . דתפלה</b>: ראה גם לקמן (בחלק ההנחות) בהנחה כאן."],["1022","18","<b>דחיי</b>: ראה לעיל הערה 10."],["1023","19","<b>וברכת את ה' אלקיך</b>: נסמן לקמן בהערה 31."],["1024","20","<b>לשמיא</b>: ב וכן לקמן בפנים: לשמי'."],["1025","21","<b>ויעש דוד שם</b>: שמו\"ב ח, יג. ראה זהר בחוקותי קיג, סע\"א ואילך ובמפרשים שם. ש\"א לו, ב ובהערה 40."],["1026","22","<b>אור אבא שנק' קדש</b>: ראה זהר רע\"מ בא מג, רע\"ב. אמור צד, ב. מאמרי אדה\"א דברים ח\"ג ע' תתקב. וש\"נ. תו\"ח שמות ח\"א נח, ב. וש\"נ."],["1027","23","<b>דאבא יסד ברתא</b>: ראה זהר רע\"מ פינחס רנו, ב. רמח, א. רנח, א. אגה\"ק ס\"ה. מאמרי אדה\"א דברים ח\"ב ע' שפ הערה ד\"ה מצירופי. קונטרסים ס\"ע תקמז ואילך. תו\"ח שמות ח\"א יב, א."],["1028","24","<b>ויהי. . לרוח ממללא</b>: בראשית ב, ז ובתרגום אונקלוס שם."],["1029","25","<b>שנעוץ סופן בתחילתן</b>: ראה ס\"י פ\"א, מ\"ז."],["1030","26","<b>את הטפל</b>: ראה ברכות לו, ב."],["1031","27","<b>כוס בגימ' אלקי'</b>: זהר רע\"מ פינחס רמה, סע\"א. עקב רעג, סע\"א. חידושי אגדות מהרש\"א ברכות נא, ב ד\"ה: עשרה."],["1032","28","<b>אלקי' בחי' מל'</b>: ראה זהר בראשית כב, א. אחרי סה, א. תו\"ח וארא ח\"א עה, ב הערה 202."]]],[2000450152,"ב) <b>ועפ\"ז</b> יובן מארז\"ל בפ\"ו דברכות דל\"ה ע\"ב כל הנהנה מעוה\"ז בלא ברכה כאילו גוזל להקב\"ה ולכנס\"י, שנאמר גוזל אביו ואמו<sup data-n=\"1033\">29</sup>, ואומר אין פשע חבר לאיש<sup data-n=\"1034\">30</sup> משחית, פי' גוזל אביו ואמו היינו בחי' או\"א עילאין, ובגמ' לשון הקב\"ה וכנס\"י היינו כנ\"ל שע\"י הברכה ממשיכים באו\"א וקוב\"ה ושמא קדישא וכשנהנה בלא ברכה, מונע אור חדש לבוא אליהם מאור הכתר ע\"י ברכה זאת כנ\"ל, וממילא בהעדר אור חדש נשפע תוס' יניקה לחיצונים מאכילה זאת מבחי' הרע שבמאכל, וזהו חבר הוא לאיש משחית, ולכן מקדים בזהר ג\"כ פקודא דא לברכא לי' לקוב\"ה על מה דאכיל ושתי דכתיב ואכלת כו'<sup data-n=\"1035\">31</sup> וברכת את כו' ואי לא בריך אקרי גזלן לגבי קוב\"ה דכתיב גוזל אביו ואמו, בגין דברכתא דבריך ב\"נ לקוב\"ה אתי לאמשכה חיין ממקורא דחיי כו' משום דהא בהא תליא שע\"י הברכה נמשך אור חדש ע\"י אמצעות אור הכתר, ע\"כ כשלא מברך ממקורו אקרי גזלן לאביו ולאמו שהם בחי' או\"א כו', דהיינו ג\"כ מה שגוזל להקב\"ה וכנס\"י שהם בחי' זו\"נ דהרי בחי' מוחין דאו\"א נמשכים לזו\"נ לצורך קיום העולמות תמיד<sup data-n=\"1036\">32</sup>, ושרש ענין הברכה להמשיך או\"ח באו\"א ממקורא דחיין הוא בחי' הכתר ושיומשך גם לבחי' המל' כנס\"י כו', וכ\"מ<sup data-n=\"1037\">33</sup> בהרמ\"ז עקב דר\"ע ע\"ב<sup data-n=\"1038\">34</sup> בד\"ה ולנחתא<sup data-n=\"1039\">35</sup> אחרנין מלעילא, והשפע האמיתי הוא מהפנימיות כו', שגם או\"א מקבלין<sup data-n=\"1040\">36</sup> אותו מאריך ואריך מעתיק כו'<sup data-n=\"1041\">37</sup>, ויש ראי' לזה ממ\"ש בזח\"ב פ' בשלח דס\"ג ע\"ב כד עתיקא סדכ\"ס בעי לזמנא ברכאן לעלמא אשרי כולא ואכליל כולא בהאי עמיקא עילאה, מבואר משם אשר מקור הברכה נמשך מע\"ק סדכ\"ס שהוא הכתר אלא שנמשך ע\"י או\"א, כי א\"א לקבל &lt;ג&gt;\nּ מהכתר בעצמו כ\"א ע\"י התלבשותו בחכ', וגם לא מהחכ' עצמה כ\"א ע\"י הבינה כו'. ובמהרש\"א<sup data-n=\"1042\">38</sup> כ' על מארז\"ל דל\"ה ע\"ב פ\"ו דברכות ע\"ד מה שאמרו במשנה פב\"ת דסוטה משנה י\"ב משחרב בהמק\"ד כו' ולא ירד הטל לברכה ונוטל<sup data-n=\"1043\">39</sup> טעם הפירות, כמ\"כ כשאינו מברך על המזון והפירות אינו נמשך הטל של ברכה, ועיקר ענין הברכה הוא המשכת גילוי אלקות כמו ברוך ה' אלקי ישראל<sup data-n=\"1044\">40</sup> מן העולם ועד העולם דהיינו מעלמא דאתכסיא לעלמא דאתגלייא<sup data-n=\"1045\">41</sup> כמ\"ש בזהר ויצא דף קנ\"ח<sup data-n=\"1046\">42</sup>, ולכן נק'",[["1033","29","<b>גוזל אביו ואמו</b>: משלי כח, כד."],["1034","30","<b>לאיש</b>: וכ\"ה לקמן (בחלק ההנחות) בהנחה כאן על יד הערה 27־ ד\"ה כל הנהנה על יד הערה 4. ב: הוא לאיש. וכן הובא בסמוך בפנים. לקמן רפט\"ז."],["1035","31","<b>דכתיב ואכלת כו'</b>: עקב ח, י. כ\"ה גם בביאוה\"ז כאן. והוא לשון הזהר לפנ\"ז."],["1036","32","<b>תמיד</b>: ע\"כ לשון הביאוה\"ז. ראה לעיל הערה 8."],["1037","33","<b>וכ\"מ</b>: מכאן ועד לקמן על יד הערה 42 הוא לשון ביאוה\"ז להצ\"צ כרך א ע' תקעא [נדפס גם באוה\"ת עקב ע' תקמח] בהוספות ושינויים."],["1038","34","<b>דר\"ע ע\"ב</b>: בביאוה\"ז שם: שם, ולפנ\"ז שם: ”דרע\"א א'\"."],["1039","35","<b>ולנחתא</b>: כ\"ה גם בביאוה\"ז כאן. וברמ\"ז: לנחתא."],["1040","36","<b>מקבלין</b>: שם: מקבלים. ב: מקבלי'."],["1041","37","<b>כו'</b>: שם: וכו'."],["1042","38","<b>ובמהרש\"א</b>: ברכות לה, א ד\"ה ל\"ק."],["1043","39","<b>ונוטל</b>: ב־ ובביאוה\"ז: וניטל. וראה שינויי נוסחאות במשנה שם."],["1044","40","<b>ברוך ה' אלקי ישראל</b>: תהלים קו, מח־ דהי\"א טז, לו [בדילוג]."],["1045","41","<b>מעלמא דאתכסיא לעלמא דאתגלייא</b>: ראה גם בנוסף להמצויין בפנים תו\"ח שמות ח\"א יח, ג. וש\"נ."],["1046","42","<b>דף קנ\"ח</b>: ע\"ב — ע\"כ מביאוה\"ז להצ\"צ שבהערה 33."]]],[2000450153,"ה' אלקי ישראל שע\"י ישראל נמצא ריבוי גילוי אלקותו למטה כמו למעלה, כמ\"ש מזה בת\"א בד\"ה ויהי בשלח פרעה<sup data-n=\"1047\">43</sup>, וע' בד\"ה אז ישיר משה ובנ\"י<sup data-n=\"1048\">44</sup>. וביאור הענין<sup data-n=\"1049\">45</sup> דהנה כל ישראל הם מאמינים בני מאמינים<sup data-n=\"1050\">46</sup>, מה שנלאו חכמי הפיליסופי'<sup data-n=\"1051\">47</sup> והמחקרים להבין בשכלם כי האמונה היא למעלה מהשגה ושכל, ואפי' מהשגה שבשרש נפש האלקית שבישראל דמזלייהו חזי<sup data-n=\"1052\">48</sup> כו', שהרי לית מחשבה תפיסא<sup data-n=\"1053\">49</sup> בי' כלל והוא רם ונשא למעלה ממזלייהו<sup data-n=\"1054\">50</sup>, והנה בזמן בית ראשון היו נש\"י במעלה העליונה, והי' אוא\"ס שורה ומתגלה בנפשם להיות אצלם גילוי אמונה זו כאילו רואה כו', אך בזמן ב\"ש לא היו הנשמות במעלה עליונה כ\"כ תקנו אנשי כנסת הגדולה הברכות<sup data-n=\"1055\">52</sup> להמשיך גילוי אמונה זו להיות ברוך ונמשך הוי' אוא\"ס ב\"ה בגילוי למטה<sup data-n=\"1056\">51</sup>, וסדר ההשתלשלות המשכת הגילוי הוא מתחילה להיות ה' אלקינו הוא גילוי אוא\"ס ב\"ה בנש\"י להיות אלקינו ממש בבחי' ביטול לפי שהם מפנימיות העולמות, משא\"כ המלאכים הם מחיצוניות העולמות<sup data-n=\"1057\">53</sup> שעליהם נאמר ומשם יפרד<sup data-n=\"1058\">54</sup> והי' לארבעה ראשים, ארבע נהרות הנ\"ל<sup data-n=\"1059\">56</sup> הם ארבע מחנות שכינה<sup data-n=\"1060\">55</sup> מחנה מיכאל כו', וזש\"א רז\"ל (ברכות ד' ע\"ב<sup data-n=\"1061\">57</sup> מיכאל באחת כו', ולא אמרו איזהו שיעור על נש\"י, לפי שענין טיסה שטסים את העולם לא שייך גבי נשמות כלל שהעולם ומלואה אינם תופסים מקום כלל נגדם, משא\"כ לגבי המלאכים<sup data-n=\"1062\">59</sup> תופס העולם איזה מקום,",[["1047","43","<b>בת\"א בד\"ה ויהי בשלח פרעה</b>: סא, א."],["1048","44","<b>בד\"ה אז ישיר משה ובנ\"י</b>: תו\"א בשלח סב, ב."],["1049","45","<b>הענין</b>: מכאן ועד לקמן על יד הערה 64 הוא לשון התו\"א בראשית ו, א-ב בשינויים והוספות. מובא גם לקמן רפי\"א."],["1050","46","<b>מאמינים בני מאמינים</b>: שבת צז, א. וראה לקמן רפ\"ז [והוא מאוה\"ת בראשית כרך ג כאן ע' 1104 רפ\"ב בהג\"ה]. תשא ע' א'תתעט."],["1051","47","<b>הפיליסופי'</b>: בתו\"א כאן: הפילוסופים."],["1052","48","<b>דמזלייהו חזי</b>: מגילה ג, א. באוה\"ת כאן (ע' 1104) מציין: ”עמ\"ש סד\"ה כיצד מרקדין\" ואולי צ\"ל: רד\"ה — ראה מאמרי אדה\"ז תקס\"ז ע' קפז. לקו\"ת שה\"ש מח, סע\"ב. וראה גם שם טז, ד."],["1053","49","<b>לית מחשבה תפיסא</b>: ת\"ז בהקדמה יז, א."],["1054","50","<b>ונשא למעלה ממזלייהו</b>: ראה אוה\"ת כאן ע' 1104 בהג\"ה."],["1055","52","<b>בזמן ב\"ש. . תקנו. . הברכות</b>: ראה יראים ס\"י. שו\"ע אדה\"ז הל' ברכות השחר סנ\"א, ס\"ה מראה מקום סד. תו\"א כאן בהתחלת המאמר. סידור דרושים לחתונה קלג, ב. לקמן (בחלק ההנחות) בהנחה כאן על יד הערה 36. מאמרי אדה\"א דרושי חתונה ח\"א ס\"ע קפא ואילך וע' רצו. מאמרי אדה\"ז תקס\"ג ח\"א ע' קכד. תו\"ח וארא ח\"א עד, א. ולהעיר מאוה\"ת (כאן) ע' תקנב. (לקמן) רפ\"ד. ופ\"ה. ספ\"ו. שו\"ע אדה\"ז הל' ברכות השחר רסמ\"ו. פע\"ח שער הברכות בתחילתו [ובמהדורת תקמ\"ב: מרע\"ה]. שו\"ת תירוש ויצהר לרצ\"י מיכלזון סצ\"ח."],["1056","51","<b>בית ראשון. . ב\"ש. . למטה</b>: ראה אוה\"ת כאן ע' תקנג בהג\"ה."],["1057","53","<b>בנש\"י. . מפנימיות. . המלאכים הם מחיצוניות העולמות</b>: ראה גם אוה\"ת כאן ע' 1106 ואילך בהג\"ה. ש\"א ח, ב ובהנסמן במ\"מ לשם."],["1058","54","<b>ומשם יפרד</b>: בראשית ב, י. ראה גם לקמן פ\"ט."],["1059","56","<b>הנ\"ל</b>: בתו\"א כאן ליתא."],["1060","55","<b>ארבע נהרות. . שכינה</b>: ראה זהר בראשית כו, ב. אוה\"ת כאן ע' 1108 ואילך. לקמן פי\"ח."],["1061","57","<b>ע\"ב</b>: ב: ע\"ב). וכ\"ה בתו\"א."],["1062","59","<b>נש\"י. . המלאכים</b>: ראה גם אוה\"ת בראשית כאן ע' תקנו ואילך. לקמן פי\"א."]]],[2000450154,"אלא שמיכאל די לו בטיסה אחת וגבריאל בשתים<sup data-n=\"1063\">58</sup> כו', ואלי' בארבע<sup data-n=\"1064\">60</sup> עם גופו שהי' תחילה גשמי ונהפך כו', ואח\"כ מלך העולם שעל העולם הוא גילוי מלכותו ית' לבד שאין מלך בלא עם<sup data-n=\"1065\">61</sup> כו', והנה ע\"י הברכה ממשיך ברכה והמשכה להיות גילוי אוא\"ס בנפש כלל ישראל שתחזק אמונת ה' בלבם בבחי' גילוי כאילו רואה כו', אך כל המוקדם מוקדם לברכה<sup data-n=\"1066\">62</sup>, והמשכת הגילוי השראת אור זה, הוא המברך שהוא הוא העושה המצוה שהם כלים להשראת אוא\"ס ממש והוא המברך הברכה, שבהם וע\"י ממשיך אוא\"ס למטה, וזהו אשר קדשנו במצותיו, אשר הוא מלשון דהא שהוא נתינת טעם לדבר כלומר לפי שקדשנו במצותיו, וציונו מלשון צותא והתקשרות<sup data-n=\"1067\">63</sup> באור א\"ס ב\"ה שרש המצות למעלה, לכך יש לנו כח להמשיך גילוי אור א\"ס ב\"ה בברכה זו<sup data-n=\"1068\">64</sup>, וההמשכה היא מעלמא דאתכסי' בבחי' עלמא דאתגלייא, שיהי' נמשך &lt;ד&gt;\nּ גילוי אמונה זו להיות ברוך ונמשך גילוי אור א\"ס ב\"ה למטה כאילו רואה כו'.\n<span data-k=\"ks\"><b>קיצור.</b> הנהנה מעוה\"ז בלא ברכה גוזל להקב\"ה וכנס\"י שנאמר גוזל אביו ואמו היינו או\"א וזו\"נ ומל', וזהו וברכת את כנ\"ל שהברכה שיומשך באו\"א מהמקור, וז\"ע ולא ירד הטל לברכה, וענין הברכה היא ההמשכה מעלמא דאתכסי' בעלמא דאתגלייא והברכות תקנו בב\"ש בכדי שיומשך גילוי אור האמונה כאילו רואה כו'.</span>\nג) <b>והנה</b> מלבד כל הנ\"ל יש עוד מעלה בברכות, שהברכות<sup data-n=\"1069\">65</sup> שמברכין על המצוות הם מד\"ס<sup data-n=\"1070\">66</sup>, והם למעלה מקיום המצוות עצמן כמ\"ש בע\"ח שע\"י עצם המצוה נמשך בחי' האו\"פ המתלבש בתוך הכלים ממש, וע\"י הברכה שעל המצוה ממשיכים בחי' האו\"מ<sup data-n=\"1071\">67</sup> שהוא למעלה מבחי' האו\"פ שלכך א\"י להתלבש בתוך הכלי, וכמשנ\"ת במ\"א באריכות שענין בחי' אור מקיף הוא מפני",[["1063","58","<b>מיכאל באחת. . וגבריאל בשתים</b>: ראה גם מאמר פסיעותיו שבהערה 60. אוה\"ת כאן ע' תקנז הובא לקמן פי\"ב."],["1064","60","<b>ואלי' בארבע</b>: ראה גם מאמר פסיעותיו של א\"א נדפס בשער מאמרי רז\"ל לב\"ר פמ\"ג (ע' מד)־ בסו\"ס חסד לאברהם (קח, ד. צ\"ל נו, ד)־ כתבים חדשים להרח\"ו (ירושלים תשמ\"ח ע' כ סע\"א). לקמן פי\"ב. ו(בחלק ההנחות) בהנחה כאן (על יד הערות 39-40)."],["1065","61","<b>שאין מלך בלא עם</b>: ראה שער היחוה\"א פ\"ז ובמ\"מ הגהות והע\"ק שם. בחיי וישב לח, ל. הנסמן במאמרי אדה\"ז על פרשיות התורה ח\"ב לע' תרלא."],["1066","62","<b>כל המוקדם מוקדם לברכה</b>: ע\"פ ברכות מא, א."],["1067","63","<b>וציונו מלשון צותא והתקשרות</b>: (צותא) ראה גם תו\"א כאן ו, ב (מובא לקמן פי\"ד). תו\"ח נח סג, ב הערה 28. סה\"מ תרכ\"ז ע' קעו. וש\"נ. תרכ\"ט ע' לח. (והתקשרות) ראה גם תו\"א כאן ו, ב (מובא לקמן פי\"ד). בשלח סא, סע\"ד. לקו\"ת מסעי צב, ג. מאמרי אדה\"ז תקס\"ב ח\"א ע' קפז־ ח\"ב ע' תמב. מובא לקמן פט\"ו. תקס\"ו ע' קמג. וראה גם לקמן פי\"ד ד\"ה ופי' ובהערה 502. לעיל המשך וידבר וגו' ויצוום הערה 253."],["1068","64","<b>זו</b>: ע\"כ הוא לשון התו\"א. ראה לעיל הערה 45."],["1069","65","<b>שהברכות</b>: מכאן ועד להלן על יד הערה 73 הוא לשון התו\"א שמות נג, רע\"ב בשינויים והוספות."],["1070","66","<b>שהברכות. . מד\"ס</b>: ראה ברכות טו, א. רמב\"ם הל' ברכות פ\"א, ה\"ב-ג. שו\"ת פאר הדור להרמב\"ם סכ\"ו. לעיל הערה 52."],["1071","67","<b>בע\"ח. . המצוה. . האו\"פ. . הברכה. . האו\"מ</b>: ראה פע\"ח שער ספירת העומר שכ\"ב קרוב לספ\"ג."]]],[2000450155,"שלעוצם מעלתו א\"י להתלבש בתוך הכלי<sup data-n=\"1072\">68</sup> כו', ולכן נשאר בבחי' מקיף כו', וזשארז\"ל כל המצות מברכין עליהם עובר לעשייתן<sup data-n=\"1073\">69</sup> לשון עובר הוא ענין בחי' מקיף כמו עובר לסוחר<sup data-n=\"1074\">70</sup> שענין עובר הוא מה שעובר עליו בבחי' מקיף, וזהו שאמרו עריבי' עלי ד\"ס<sup data-n=\"1075\">71</sup> אמרו לשון עלי ולא לי כי פי' עלי היינו לומר שההמשכה שע\"י הברכה היא בבחי' מקיף וזהו עלי, ולכך ערבים יותר מיינה של תורה<sup data-n=\"1076\">72</sup> שהם רק בחי' או\"פ כו', ונועם ה' והעריבות הנמשך ע\"י הברכה שהוא מד\"ס הוא מבחי' מקיף, וזהו ערבים עלי<sup data-n=\"1077\">73</sup>. וביאור הענין דהנה כתי' ועל דמות הכסא<sup data-n=\"1078\">74</sup> דמות כמראה אדם עליו מלמעלה, ולכאורה צ\"ל הלא אין לו דמות הגוף<sup data-n=\"1079\">75</sup> ולא גוף, והאיך נא' כמראה אדם עליו מלמעלה, אך הענין יובן ע\"פ מארז\"ל ע\"פ ועשיתם אתם<sup data-n=\"1080\">76</sup> אתם כתיב מעלה אני עליכם כאילו עשאוני<sup data-n=\"1081\">77</sup>, והיינו שע\"י קיום המצות ממשיכים להיות כבי' בחי' אדם עליו מלמעלה, כי רמ\"ח פקודין הם בחי' רמ\"ח איברין<sup data-n=\"1082\">78</sup>, והיינו כמו בציור אדם הנה האדם הוא כלול מרמ\"ח איברין ושס\"ה גידים<sup data-n=\"1083\">79</sup> כן למעלה בחי' רמ\"ח פקודי' הם הם בחי' האיברים דמלכא שנעשה בחי' ציור אדם מבחי' ט\"ס דז\"א, והיינו כי טפ\"ט הם פ\"א ורת\"ס הם רמ\"ג וה\"ח<sup data-n=\"1084\">80</sup> המגדילים זהו מספר רמ\"ח, שע\"י קיום התומ\"צ בגשמי' דוקא עי\"ז נעשה בחי' אדם למעלה, וזהו כאילו עשאוני, היינו לפי שע\"י העבודה ממשיכים המשכת אורות בכלים שהוא בחי' ההיא נביעא דאיהי נשמתא לגופא<sup data-n=\"1085\">81</sup> היינו בחי' מה שגופין תקינת לון<sup data-n=\"1086\">82</sup> חג\"ת, דרועא ימינא, דרועא שמאלא וגופא כו', ועכ\"ז אמר כמראה אדם מפני כי באמת הוא רק כאילו עשאוני, שהרי באמת אין לו דמות הגוף ולא גוף, רק ע\"י שמקיימים רצונו עי\"ז כאילו עשאוני להיות בבחי' כמראה אדם, וזהו ע\"י המצות עצמם שזהו בחי' או\"פ אורות בכלים, וע\"י הברכה ממשיכים עלי בחי' מקיף כו' כנ\"ל ולכן עריבים עלי דוקא, ולכן חייב אדם לברך מאה ברכות בכדי להמשיך בחי' המקיפים כו'.",[["1072","68","<b>אור מקיף. . בתוך הכלי</b>: ראה גם מאמרי אדה\"א נ\"ך ע' קלג ואילך."],["1073","69","<b>כל המצות. . לעשייתן</b>: ראה פסחים ז, ב. לקו\"ת מסעי צב, ג. תו\"ח שמות ח\"א מח, ד. וש\"נ. תצוה ח\"ב שלא, א."],["1074","70","<b>עובר לסוחר</b>: ח\"ש כג, טז."],["1075","71","<b>עריבי' עלי ד\"ס</b>: ראה ע\"ז לה, א וברש\"י שם. לקו\"ת שם."],["1076","72","<b>יותר מיינה של תורה</b>: ע\"ז שם."],["1077","73","<b>עלי</b>: עד כאן לשון התו\"א. ראה לעיל הערה 65."],["1078","74","<b>ועל דמות הכסא</b>: יחזקאל א, כו."],["1079","75","<b>אין לו דמות הגוף</b>: ע\"פ פיוט יגדל. פיה\"מ להרמב\"ם מס' סנהדרין פ\"י היסוד הג'. ראה גם לעיל המשך אם כסף תלוה פ\"ה."],["1080","76","<b>ועשיתם אתם</b>: בחוקותי כו, ג."],["1081","77","<b>אתם. . כאילו עשאוני</b>: ראה זהר שם קיג, סע\"א. הנסמן במאמרי אדה\"א הנחות תקע\"ז ע' רלה."],["1082","78","<b>רמ\"ח פקודין. . איברין</b>: ראה ת\"ז ת\"ל (עד, סע\"א). תניא רפכ\"ג. סידור שער החנוכה רפ, א. שע\"ת עב, ג הערה 17."],["1083","79","<b>האדם. . מרמ\"ח איברין ושס\"ה גידים</b>: אהלות פ\"א, מ\"ח. תרגום יוב\"ע בראשית א, כז. זהר וישלח קע, ב."],["1084","80","<b>טפ\"ט. . וה\"ח</b>: ראה ע\"ח שער פרקי הצלם שכ\"ד, פ\"ו. שע\"ת מב, ב ובהנסמן במ\"מ לשם."],["1085","81","<b>ההיא נביעא דאיהי נשמתא לגופא</b>: ראה ת\"ז בהקדמה יז, א."],["1086","82","<b>שגופין תקינת לון</b>: ת\"ז שם."]]],[2000450156,"&lt;ה&gt;\nּ\n<span data-k=\"ks\"><b>קיצור.</b> שע\"י עצם המצוה עצמה ממשיכים רק בחי' או\"פ, וע\"י הברכה ממשיכים בחי' או\"מ כמ\"ש בע\"ח, ולכן עריבים עלי דוקא בחי' ד\"ס הם גם הברכות שתקנו רבנן כמראה אדם, כאילו עשאוני ע\"י רמ\"ח מצות רמ\"ח איברין ושס\"ה ל\"ת שס\"ה גידים וזהו או\"פ, וע\"י הברכה נמשך או\"מ ולכן חייב אדם לברך מאה כו'. </span>"],[2000450157,"<h3>ולהבין כו' ברוך ה' אלקי ישראל</h3>\nד) <b>ולהבין</b><sup data-n=\"1087\">83</sup> בתוס' ביאור מה שתקנו הברכות בב\"ש, אבל בזמן בית ראשון לא היו מברכין, כן אמר רבינו אדמו\"ר ז\"ל, בד\"ה להבין ענין הברכות שבפ' בראשית<sup data-n=\"1088\">84</sup>, כי הנה נת' לעיל<sup data-n=\"1089\">85</sup> בשם הזהר ויצא דקנ\"ח ע\"ב כי ענין הברכה לש' הוי' היא ע\"ד מ\"ש ברוך ה' אלקי ישראל מן העולם עד<sup data-n=\"1090\">86</sup> העולם היינו מעלמא דאתכסיא שהיא בינה<sup data-n=\"1091\">87</sup> לעלמא דאתגלייא מל'<sup data-n=\"1092\">88</sup>, ושם מבואר<sup data-n=\"1093\">89</sup> ג\"כ אשר ב' שמות הוי' תרין עלמין נינהו, וכמ\"ש בזהר נשא קל\"ח ע\"א בענין הוי' הוי' פסיק טעמא בגווייהו, וכמ\"ש מזה בלק\"ת פ' חקת<sup data-n=\"1094\">90</sup> בביאור ע\"פ זאת חקת התורה אשר ציוה הוי' ע\"ש, שהם בחי' ממכ\"ע וסוכ\"ע, ועמ\"ש בת\"א פ' בשלח בד\"ה וירא ישראל<sup data-n=\"1095\">91</sup> את היד הגדולה, ובד\"ה כי אתה נרי<sup data-n=\"1096\">92</sup>, דהנה פעם כתי' ה' רחום וחנון<sup data-n=\"1097\">93</sup>, ופעם כתיב חנון ורחום הוי'<sup data-n=\"1098\">94</sup>, והענין הוא כי פי' הוי' רחום וחנון שכדי להיות התגלות מדת רחום וחנון מאוא\"ס דלאו מכל אינון מדות<sup data-n=\"1099\">95</sup> איהו כלל הוצרך להיות בחי' הוי' שהוא צמצום והתפשטות המשכה והתפשטות<sup data-n=\"1100\">96</sup>, אך פי' חנון ורחום הוי', היינו שמבחי' חנון",[["1087","83","<b>ולהבין</b>: ברשימת המאמרים שמופיע בריש הבוך 1089 נרשם כאן מאמר (ב' מההמשך והוא) ד\"ה: ברוך ה' אלקי ישראל — ש\"פ מצורע (הכולל פרקים ד — ה). היינו שבעת אמירת הדרוש היתה פתיחא זו, ולע\"ע אין ידוע אם גם פתיחה זו נרשמה בפ\"ע ע\"י כ\"ק אדמו\"ר מהר\"ש. וראה לקמן (בחלק ההנחות) הנחה מדרוש זה מכ\"ק אדמו\"ר מהורש\"ב.\nלמאמר זה לפ\"ד — ראה אוה\"ת בראשית כרך ג' ע' תקנא [והוא לשונו בשינויים והוספות]. תו\"א מקץ מא, א. ג. מאמר ד\"ה ועתה ישראל ש\"מ אלול תשכ\"ח (קונ' כ' מנ\"א תנש\"א — סה\"מ מלוקט ה ע' שמב). הקיצור הוא לשון אוה\"ת שם ע' 1104. לפ\"ה — ראה אוה\"ת שם ואילך. לקו\"ת ר\"ה נז, ג. הקיצור — ראה אוה\"ת שם ע' 1104 בשינויים."],["1088","84","<b>בד\"ה להבין ענין הברכות שבפ' בראשית</b>: תו\"א ו, א."],["1089","85","<b>נת' לעיל</b>: על יד הערות 41-2."],["1090","86","<b>עד</b>: ב וכן לעיל רפ\"ב על יד הערה 40 ובהקיצור כאן: ועד — אבל כ\"ה גם בהנחה כאן (שנדפס לקמן בחלק ההנחות) ובהערה 2 שם."],["1091","87","<b>מעלמא דאתכסיא שהיא בינה</b>: ראה גם לקו\"ת שמע\"צ פח, ד."],["1092","88","<b>מעלמא דאתכסיא שהיא בינה. . מל'</b>: כ\"ה גם באוה\"ת כאן ע' תקנא."],["1093","89","<b>ושם מבואר</b>: בזהר."],["1094","90","<b>בלק\"ת פ' חקת</b>: נז, ג."],["1095","91","<b>בת\"א. . וירא ישראל</b>: סא, ד ואילך."],["1096","92","<b>בת\"א. . כי אתה נרי</b>: מקץ מא, א. ג — נעתק כאן (והוא עד לקמן על יד הערות 98 ו 102) בשינויים והוספות."],["1097","93","<b>ה' רחום וחנון</b>: תשא לד, ו [בדילוג]. ראה גם בהבא לקמן מאמרי אדה\"ז תקס\"ה ח\"ב ע' תתקטו וע' תתקכב. תקס\"ח ח\"ב ע' תרמט וע' תרנז. ש\"א ע' מג. מאמרי אדה\"א נ\"ך ע' תקעא וע' תקפז."],["1098","94","<b>חנון ורחום הוי'</b>: תהלים קיא, ד. קמה, ח. דהי\"ב ל, טו."],["1099","95","<b>דלאו מכל אינון מדות</b>: ת\"ז בהקדמה יז, ב."],["1100","96","<b>הוי' שהוא צמצום. . והתפשטות</b>: ראה אגה\"ת פ\"ד. לקמן פ\"ח הערה 251."]]],[2000450158,"ורחום דהיינו מפני היותו חפץ חסד כמ\"ש כי חפץ חסד הוא<sup data-n=\"1101\">97</sup> נמשך בחי' הוי' שהוא צמצום והתפשטות כו' שבסדר השתלשלות משא\"כ הוי' שקודם רחום וחנון הוא ההוי' שלמעלה מגדר השתלשלות, ושם נעשה בחי' הוי' שהוא ג\"כ צמצום והתפשטות כו' כדי להמשיך מדת חנון ורחום בהוי' שבסדר השתלשלות<sup data-n=\"1102\">98</sup>, כי הנה ב'<sup data-n=\"1103\">99</sup> הוויות א' בז\"א שפי' הוי' ל' מהוה<sup data-n=\"1104\">100</sup>, והיינו להוות עולמות הנבראים, והגם כי זהו בדרך ממילא ומאיליו כמ\"ש כי הוא צוה ונבראו<sup data-n=\"1105\">101</sup> מ\"מ הנה הוי' ל' מהוה כו', והוי' הא' הוא בא\"א להיות חנון ורחום, כי בחי' ש' הוי' זה הוא ב' פיאות דא\"א, להמשיך י\"ג ת\"ד בז\"א, אבל חנון ורחום הוי' היינו המשכת יגת\"ד בז\"א להיות הז\"א בש' הוי' כו'<sup data-n=\"1106\">102</sup>.\n<b>והנה</b> ש' הוי' בחי' סוכ\"ע מאיר בבינה הנק' עלמא עילאה<sup data-n=\"1107\">103</sup> עלמא דאתכסיא כנודע שהתגלות עתיק הוא בבינה<sup data-n=\"1108\">104</sup> ולכן נק' הבינה הוא<sup data-n=\"1109\">105</sup>, וש' הוי' דז\"א שהוא נק' ממכ\"ע מאיר במל' שנק' עלמא תתאה<sup data-n=\"1110\">106</sup>, ונק' עלמא דאתגליא, וע' בלק\"ת פ' ואתחנן בד\"ה וידעת היום והשבות, הראשון<sup data-n=\"1111\">107</sup> שלכן בבחי' ממכ\"ע נאמר ומבשרי אחזה אלקה<sup data-n=\"1112\">108</sup> משא\"כ בבחי' סוכ\"ע נא' ויאמינו בהוי'<sup data-n=\"1113\">109</sup> כו', וע\"כ הברכה היא מן העולם מבחי' בינה, וכמ\"ש בזהר אמור דצ\"ט א' בפי' בעבר הנהר<sup data-n=\"1114\">110</sup> כו' מעולם, ההוא נהר עולם איקרי כו', לבחי' העולם מל' מקור דבי\"ע, והיינו שיומשך ש' הוי' סוכ\"ע בבחי' ממכ\"ע, ולא יהי' הפסיק טעמא מפסיק &lt;ו&gt;\nּ כו' שהו\"ע יהי רקיע ויהי מבדיל<sup data-n=\"1115\">111</sup>, והבדילה הפרוכת<sup data-n=\"1116\">112</sup> כו', וצ\"ע דלקמן יתבאר שהפסיק טעמא<sup data-n=\"1117\">113</sup> מייחדם",[["1101","97","<b>כי חפץ חסד הוא</b>: מיכה ז, יח."],["1102","98","<b>השתלשלות</b>: ע\"כ לשון התו\"א מקץ מא, א. ראה לעיל הערה 92."],["1103","99","<b>ב'</b>: מכאן ועד בסמוך על יד הערה 102 הוא לשון התו\"א מקץ מא, ג בשינויים והוספות."],["1104","100","<b>הוי' ל' מהוה</b>: ראה זהר רע\"מ פינחס רנז, סע\"ב. פרדס שער עשר ולא תשע ש\"א, פ\"ט. שער עצמות וכלים ש\"ד, ספ\"י. שער היחוה\"א פ\"ד. פ\"ז. הערה בסה\"מ ת\"ש ע' 40."],["1105","101","<b>כי הוא צוה ונבראו</b>: תהלים קמח, ה. וראה גם לעיל המשך וידבר וגו' ויצוום ספ\"ה. וש\"נ."],["1106","102","<b>כו'</b>: ע\"כ הוא לשון התו\"א — ראה לעיל הערה 99."],["1107","103","<b>בבינה הנק' עלמא עילאה</b>: ראה זהר בראשית לד, א ובמק\"מ שם. אוה\"ת (יהל אור) תהלים ע' תטו ואילך."],["1108","104","<b>שהתגלות עתיק הוא בבינה</b>: ראה זהר קרח קעח, ב. מאמרי אדה\"א הנחות תקע\"ז ע' ד. וש\"נ. תו\"ח לך פא, ב. ביאוה\"ז להצ\"צ אחרי כרך א ע' שסד. לקמן פל\"ו."],["1109","105","<b>נק' הבינה הוא</b>: ראה ע\"ח שער תיקון הנוקבא של\"ד, ספ\"ב. לקו\"ת קרח נה, ב. תו\"ח לך פא, ב ובהערה 7."],["1110","106","<b>במל' שנק' עלמא תתאה</b>: ראה זהר בראשית לד, א ובמק\"מ שם. אוה\"ת (יהל אור) תהלים ע' תטו ואילך."],["1111","107","<b>בלק\"ת פ' ואתחנן. . הראשון</b>: ד, א. ה, ג."],["1112","108","<b>ומבשרי אחזה אלקה</b>: איוב יט, כו. ראה גם לקמן (בחלק ההנחות) הנחה ד\"ה בנים אתם על יד הערה 17. ד\"ה וידבר וכו' אלה הם מועדי על יד הערה 41. מאמרי אדה\"ז הקצרים ע' רסד. תו\"ח בא ח\"א צח, ב. וש\"נ."],["1113","109","<b>ויאמינו בהוי'</b>: בשלח יד, לא. ראה גם לקמן ספ\"ז. תו\"א בשלח סב, א."],["1114","110","<b>בעבר הנהר</b>: יהושע כד, ב."],["1115","111","<b>יהי רקיע ויהי מבדיל</b>: בראשית א, ו [בדילוג]."],["1116","112","<b>והבדילה הפרוכת</b>: תרומה כו, לג. ראה גם סה\"מ תר\"ל ע' קו."],["1117","113","<b>דלקמן יתבאר שהפסיק טעמא</b>: פ\"ט ד\"ה ואפ\"ל."]]],[2000450159,"ומחברם<sup data-n=\"1118\">114</sup>, ועכ\"ז גם לפ\"ז ענין בחי' הברכה מן העולם ש' הוי' דלעילא עד העולם ש' הוי' שבסדר השתלשלות שיומשך בחי' גילוי סוכ\"ע בממכ\"ע ולא כמו בחי' חיבור הפסיק טעמא לבד כו'.\n<span data-k=\"ks\"><b>קיצור.</b> ענין הברכה הוא ע\"ד ברוך כו' מן העולם ועד העולם היינו מש' הוי' דע\"ק המאיר בבינה סוכ\"ע שיאיר בממכ\"ע ש' הוי' בז\"א ובמל', ושלא יהי' הפסק מחמת הפסיק טעמא, יהי רקיע ויהי מבדיל<sup data-n=\"1119\">115</sup>, או שיומשך תוס' וריבוי בחיבור הפסיק כו'.</span>\nה) <b>ועוי\"ל</b><sup data-n=\"1120\">116</sup> בפי' הברכה מעלמא דאתכסיא ע\"ד מ\"ש האלשיך ר\"פ בראשית בפי' ואהי' אצלו אמון, אומן<sup data-n=\"1121\">117</sup> בהקדמה ב', כי הנה סיפור הדברים הנבראים בשי\"ב<sup data-n=\"1122\">118</sup>, אף שהוא כפשוטו ממש, הלא ירמוז ג\"כ אל הדברים הנאצלים עליונים רוחניים לאין תכלית, ועד לא נברא העולם<sup data-n=\"1123\">119</sup> כו', כי למטה השמים הם כפשוטו, ויש באצילות שמים שהם ז\"א<sup data-n=\"1124\">120</sup> דאצי' אש ומים<sup data-n=\"1125\">121</sup> חו\"ג<sup data-n=\"1126\">122</sup> כו', וכן השמש למטה מאור גשמי, ולמעלה זהו ענין ש' הוי'<sup data-n=\"1127\">123</sup> כמ\"ש שמש ומגן<sup data-n=\"1128\">124</sup> הוי' אלקים, ולכן נמשלה התורה ללוח ופנקס<sup data-n=\"1129\">125</sup> שבו ראה הקב\"ה וברא דוגמתו שמים וארץ גשמיים כו', יעו\"ש. ודפח\"ח<sup data-n=\"1130\">126</sup>. וא\"כ עד\"ז יש לפרש הברכה מעלמא דאתכסיא היינו שיאירו אורות הנאצלים הרוחני' גם בעלמא דאתגליא בכדי שלא יסתירו ולא יעלימו הגשמיים, וע\"ד שנאמר לע\"ל השמים החדשים והארץ החדשה<sup data-n=\"1131\">127</sup>, והיינו שלא יסתירו ולא יעלימו על גילוי אלקותו ית', ועד\"ז נא' ולא יהי' לך עוד השמש לאור יומם והי' לך ה' לאור עולם<sup data-n=\"1132\">128</sup>, והיינו כמו שהוא למעלה שבחי' שמש ומגן ז\"ע הוי' אלקים",[["1118","114","<b>ומחברם</b>: ע\"כ לשון אוה\"ת — ראה לעיל הערה 83."],["1119","115","<b>קיצור. . מבדיל</b>: לשון אוה\"ת כאן ע' 1104."],["1120","116","<b>ועוי\"ל</b>: לשון אוה\"ת כאן ע' תקנא ואילך בשינויים והוספות."],["1121","117","<b>ואהי' אצלו אמון אומן</b>: משלי ח, ל. ב\"ר בתחילתו."],["1122","118","<b>כי. . בשי\"ב</b>: לשון האלשיך."],["1123","119","<b>הלא. . העולם</b>: לשון האלשיך בשינוי קל."],["1124","120","<b>שמים שהם ז\"א</b>: ראה זהר בשלח סב, ב. אד\"ז האזינו רפח, א. סה\"מ תרכ\"ז ע' קעא. תרכ\"ט ע' לב. לעיל המשך אם כסף תלוה ספ\"ב. וש\"נ. לקמן הערה 1291."],["1125","121","<b>שמים. . אש ומים</b>: ראה חגיגה יב, סע\"א. רש\"י בראשית א, ח. לקמן מאמר ד\"ה ואשא אתכם הערה 19."],["1126","122","<b>אש ומים חו\"ג</b>: ראה ס\"י פ\"א, מי\"א-יב ובמפרשים שם. הנסמן במאמרי אדה\"א ויקרא ח\"ב ע' תצח. דברים ח\"ד ע' א'שצב. הנחות תקע\"ז ע' ח. סה\"מ שבהערה 120."],["1127","123","<b>השמש. . ש' הוי'</b>: ראה זהר בראשית כ, א."],["1128","124","<b>שמש ומגן</b>: תהלים פד, יב."],["1129","125","<b>נמשלה התורה ללוח ופנקס</b>: ראה ב\"ר בתחילתו: דיפתראות ופינקסאות, וברש\"י שם: פנקס לוח."],["1130","126","<b>ודפ\"ח</b>: ודברי פי חכם חן."],["1131","127","<b>השמים החדשים והארץ החדשה</b>: ישעי' סו, כב."],["1132","128","<b>ולא יהי'. . לאור עולם</b>: ישעי' ס, יט [בדילוג. ושם: לא יהי' — אבל כ\"ה גם באוה\"ת כאן ע' 1102. לקמן בהקיצור לפכ\"ח. (בחלק הההנחות) בהנחה מדרוש זה על יד הערה 52. ש\"א לג, ב. תו\"ח ויצא קסח, א ובהערה 2. יתרו ח\"ב רסב, ב. ויקהל תג, ב]."]]],[2000450160,"ממש כך יאיר ויתגלה בחי' זו למטה, זהו ענין ברוך ה' לשון בריכה<sup data-n=\"1133\">129</sup> והמשכה<sup data-n=\"1134\">130</sup> בחי' גילוי כו', ועמ\"ש בלק\"ת בד\"ה ואתחנן<sup data-n=\"1135\">131</sup> בפי' ברוך שאמר כו'.\n<b>והנה</b> בית ראשון הוא בינה<sup data-n=\"1136\">132</sup> ה' עילאה, ובית שני הוא מל'<sup data-n=\"1137\">133</sup>, ולכן חסרו ה' דברים בב\"ש<sup data-n=\"1138\">134</sup>, הנמשכים מה\"א עילאה וכמ\"ש מזה בלק\"ת בדרושים לר\"ה בד\"ה יו\"ט של ר\"ה שחל להיות בשבת, ושם פ\"ה ע\"ש. ועמ\"ש המק\"מ על הזהר שמות ד\"ט ע\"ב שבזמן בית ראשון הי' גם המל' אז במדריגת הבינה שהוא ה' עילאה, ועמ\"ש מזה בסד\"ה ששת ימים<sup data-n=\"1139\">136</sup> תאכל מצות, ובמק\"מ פ' תרומה דקמ\"ג ע\"א<sup data-n=\"1140\">135</sup>, וכ\"כ במאו\"א אות ב' סעי' י\"ד בתי ישראל אימא וברתא, בית ראשון בינה בית שני מל', כי בב\"ר הי' המל' מגיע<sup data-n=\"1141\">137</sup> עד אימא שוה לז\"א, ובב\"ש חצי פרצוף שיעור מקום של רחל תמיד ונק' שניהם בתי ישראל אימא וברתא זו בית לישראל סבא, וזו בית לישראל זוטא עכ\"ל. וע' במק\"מ פ' שמות ד\"ט<sup data-n=\"1142\">138</sup>. והנה ישראל סבא זהו בחי' עתיק יומין המאיר ביסוד אבא כו', וע' מענין לשני בתי ישראל בזח\"א פ' בראשית ד\"נ ע\"ב באריכות. ובסה\"מ סי' קל\"ח. ומענין ישראל סבא וישראל זוטא בת\"א סד\"ה ואלה שמות בנ\"י<sup data-n=\"1143\">139</sup>, יעו\"ש. וע' בת\"א פ' ויגש<sup data-n=\"1144\">140</sup> &lt;ז&gt;\nּ בענין משמח חתן וכלה וענין משמח חתן עם הכלה בהשואה אחת כו'.\n<b>ועפ\"ז</b> מה שא' רבינו אדמו\"ר ז\"ל שבבית ראשון לא היו מברכין, כי מאחר שעיקר הברכה הוא להמשיך מבחי' סוכ\"ע המאיר בבינה בש' הוי' דממכ\"ע המאיר במל', והרי בבית ראשון הי' מאיר מעצמו בחי' אור הבינה כנ\"ל שהיא הנק' בית ראשון בחי' בית לישראל סבא כו', א\"כ לא הי' נצרך לברך ולהמשיך בחי' זו, אלא בבית שני שהוא בחי' מל', אשר אין בה אור הבינה ונק' בית לישראל זוטא שהוא ז\"א, בחי' כי נער ישראל<sup data-n=\"1145\">141</sup>, שנק' קטנות לגבי הגדלות דישראל סבא כו', וגם היא חצי פרצוף כו', נגד תנה\"י דז\"א, ע\"כ אז דוקא תקנו הברכות לברך את השם, והיינו להמשיך בחי' ש' הוי' דלעילא הסוכ\"ע המאיר בבינה שיאיר בש' הוי' דז\"א הממכ\"ע וממנו יאיר במל', ולכן כל ברכה שאין בה",[["1133","129","<b>ברוך ה' לשון בריכה</b>: ראה גם סה\"מ תרכ\"ו ע' קלב. תרכ\"ט ע' ב. תרנ\"ד ע' שיב. מאמרי אדה\"א הנחות תקע\"ז ע' רסב. וש\"נ."],["1134","130","<b>ברוך. . והמשכה</b>: ראה זהר עקב ער, סע\"ב הובא בריש ההמשך כאן על יד הערות 9-10. תו\"ח בשלח ח\"א קס, ד הערה 540."],["1135","131","<b>בלק\"ת בד\"ה ואתחנן</b>: ב, א."],["1136","132","<b>בית ראשון הוא בינה</b>: ראה לקו\"ת במדבר יג, ג. אוה\"ת שה\"ש ח\"א ע' קל."],["1137","133","<b>בית. . בינה. . מל'</b>: ראה אוה\"ת חנוכה ע' שא. איכה כרך ב ע' א'נ. סה\"מ תרכ\"ט ע' רפז."],["1138","134","<b>חסרו ה' דברים בב\"ש</b>: יומא כא, ב."],["1139","136","<b>בסד\"ה ששת ימים</b>: לקו\"ת צו טו, סע\"א."],["1140","135","<b>ועמ\"ש. . ע\"א</b>: לשון הלקו\"ת ר\"ה נז, ג בשינוי. ובאוה\"ת כאן ליתא."],["1141","137","<b>מגיע</b>: וכ\"ה גם בלקו\"ת לג\"פ ואוה\"ת כאן. ובמאו\"א: מגעת."],["1142","138","<b>וע'. . ד\"ט</b>: בלקו\"ת לג\"פ ואוה\"ת כאן ניתוסף: ע\"ב. ראה גם לקו\"ת שבהערה 135."],["1143","139","<b>בת\"א סד\"ה ואלה שמות בנ\"י</b>: שמות נ, ד. בלקו\"ת לג\"פ כאן כט, א: בד\"ה אלה, ותיקן הר\"ש סופר על הגליון: סד\"ה ואלה."],["1144","140","<b>בת\"א פ' ויגש</b>: ראה שם מד, ד ואילך."],["1145","141","<b>כי נער ישראל</b>: הושע יא, א."]]],[2000450161,"שם ומל' אינה ברכה<sup data-n=\"1146\">142</sup>, וכ\"כ במאו\"א אות ב' סל\"ה וז\"ל ברכה מצד אימא<sup data-n=\"1147\">143</sup> בריכה העליונה (ע' בסידור בדרוש ברכת הזימון<sup data-n=\"1148\">144</sup> ובזהר ס\"פ בא דמ\"ב ע\"ב מענין מקור מעין ים) ששם מימי החכמה נמשכין<sup data-n=\"1149\">145</sup> לתוכה (וע' בזח\"ב ס\"פ בשלח דס\"ג ע\"ב ההובא לעיל<sup data-n=\"1150\">146</sup> כד ע\"ק סדכ\"ס כו' אשרי כולא ואכליל כולא בהאי עמיקא עילאה), המברכת למל' בריכה התחתונה כו' עכ\"ל. ופי' ברכה זו למל' נראה שבאה ע\"י ז\"א, ולכן איכא מ\"ד דרק כל ברכה שאין בה שם אינה ברכה שאע\"פ שלא הזכיר מל' הוי ברכה, כי מאחר שהזכיר השם הוי' דז\"א ממילא נמשך למל', ויובן זה ע\"פ מ\"ש בת\"א ס\"פ ויגש בענין משמח חתן וכלה שבחי' המל' מקבלת ע\"י ז\"א, ועמ\"ש בלק\"ת שה\"ש<sup data-n=\"1151\">147</sup> בד\"ה צאינה וראינה בפי' שאו ידיכם קדש<sup data-n=\"1152\">148</sup> וברכו את הוי', ולכן גדול העונה אמן<sup data-n=\"1153\">149</sup> יותר מן המברך, כי אמן גימ' הוי' אד'<sup data-n=\"1154\">150</sup> והיינו שיומשך הברכה מז\"א למל', ויהי' יתד במקום נאמן<sup data-n=\"1155\">151</sup>, יתד שלא תמוט, וע\"ז מורה ש' אד' וכמ\"ש במא\"א<sup data-n=\"1156\">152</sup> שז\"ע מאה אדנים שבמשכן<sup data-n=\"1157\">153</sup> לקבל מאה ברכות<sup data-n=\"1158\">154</sup> כו' והיינו האדנים מש' אד'<sup data-n=\"1159\">155</sup> שמקבלים<sup data-n=\"1160\">156</sup> ע\"י אמן הברכה מש' הוי', ועמ\"ש במ\"א בענין זו\"נ שהם הממוצעים לחבר ההמשכה מאא\"ס בבי\"ע וז\"ע כרוב אחד מקצה מזה וכרוב אחד מקצה מזה<sup data-n=\"1161\">157</sup> כמ\"ש בת\"א ס\"פ תרומה בכי\"ק רבינו אדמו\"ר נ\"ע וז\"ל ונודע שהז\"א הוא תכלית ירידת אא\"ס מלמעלה למטה בכדי להאיר אח\"כ לבי\"ע ע\"י הנוקבא כו' ע\"ש. והנה בפי' יברך את הנערים<sup data-n=\"1162\">158</sup> מבואר בזח\"ג קפ\"ז ע\"ב בפ' בלק, ובזח\"א ויחי דרך\"ח ע\"ב דקאי על שנים כרובים שהם הנק' נערים על שהם בחי' קטנות לגבי אוא\"ס הבלתי בע\"ג, ועמ\"ש בת\"א בד\"ה בך\"ה בכסליו<sup data-n=\"1163\">159</sup> גבי חנוך לנער כו', בפי' מי יקום יעקב<sup data-n=\"1164\">160</sup> כי קטן הוא שיעקב הוא בחי' בריח התיכון המבריח מן הקצה אל הקצה, ומאחר שיש קצה וקצה הרי הוא בבחי' קטן לגבי אוא\"ס הבלתי בע\"ג כו'.",[["1146","142","<b>כל ברכה. . ברכה</b>: ראה ברכות יב, א."],["1147","143","<b>אימא</b>: במאו\"א־ לקו\"ת לג\"פ ואוה\"ת כאן ובשמות ע' פג: אימא עילאה."],["1148","144","<b>בסידור בדרוש ברכת הזימון</b>: שער בהמ\"ז קד, א."],["1149","145","<b>נמשכין</b>: במאו\"א־ לקו\"ת לג\"פ ואוה\"ת כאן ובשמות שם: נאספים."],["1150","146","<b>ההובא לעיל</b>: פ\"ב על יד הערות 37-8."],["1151","147","<b>בלק\"ת שה\"ש</b>: כד, ג."],["1152","148","<b>שאו ידיכם קדש</b>: תהלים קלד, ב."],["1153","149","<b>גדול העונה אמן</b>: ברכות נג, ב."],["1154","150","<b>אמן גימ' הוי' אד'</b>: ראה ת\"ז תי\"ט מ, א. תכ\"ו עא, ב. ספר המנהיג דיני תפלה קרוב לתחילתו (ירושלים תשל\"ח ר\"ע לב. וש\"נ). פע\"ח שער כוונת אמן שי\"א, פ\"א — פ\"ד. מאו\"א מערכת אמן אות צד. לקמן ספל\"ד."],["1155","151","<b>יתד במקום נאמן</b>: ישעי' כב, כג."],["1156","152","<b>במא\"א</b>: בלקו\"ת לג\"פ ואוה\"ת בראשית כאן ע' תקנב ניתוסף: שם."],["1157","153","<b>שבמשכן</b>: כ\"ה גם בלקו\"ת לג\"פ ואוה\"ת כאן. ובמאו\"א וכן באוה\"ת עקב ע' תקיח ליתא."],["1158","154","<b>ברכות</b>: באוה\"ת עקב שם: ”והוא מבואר בספר ש\"א שער א\" (ה, ב)."],["1159","155","<b>האדנים מש' אד'</b>: ראה ש\"א שם. לקו\"ת להאריז\"ל תרומה כו, יט. ס\"פ ויקהל. ר\"פ פקודי."],["1160","156","<b>שמקבלים</b>: בלקו\"ת לג\"פ ואוה\"ת כאן: שמקבל."],["1161","157","<b>כרוב אחד מקצה. . מזה</b>: תרומה כה, יט."],["1162","158","<b>יברך את הנערים</b>: ויחי מח, טז."],["1163","159","<b>בת\"א בד\"ה בך\"ה בכסליו</b>: כט סע\"ד בשינוי. ראה גם לקמן מאמר ד\"ה אנכי אנכי על יד הערה 15. בלקו\"ת לג\"פ ואוה\"ת כאן: בכסלו."],["1164","160","<b>מי יקום יעקב</b>: עמוס ז, ה."]]],[2000450162,"&lt;ח&gt;\nּ<b>וענין</b> הברכה בהם היינו שיומשך בהם תוס' וריבוי אור, וכענין פי' ונערים ממשתה נגינתם<sup data-n=\"1165\">161</sup>, כי עכשיו ההשפעה הנמשך ע\"י הנערים שהם מט\"ט וסנד\"ל<sup data-n=\"1166\">162</sup> המשתלשלים מזו\"נ באה בהסתר והעלם אותותינו לא ראינו<sup data-n=\"1167\">163</sup>, וזהו הצמצום והקטנות, והברכה היא שלא יהי' העלם והסתר כ\"כ וכמו בנס דפורים הנה גם בלבוש הטבע נתגלה בחי' נס וגילוי, וכמ\"ש ראו כל אפסי ארץ<sup data-n=\"1168\">164</sup> את ישועת אלקינו, וכן י\"ל ג\"כ בזו\"נ הנק' כרובים יומשך בהם ריבוי אור מנו\"ה דאימא ע' במא\"א אות ך' סעי' מ\"ד ותבין<sup data-n=\"1169\">165</sup>. ועפ\"ז י\"ל שלכן ברוך הוא אותיות כרוב<sup data-n=\"1170\">166</sup>, היינו שיומשך ויאיר הברכה בבחי' כרוב כו'. וכ\"ז בבית שני, אבל בבית ראשון שהי' המל' במדריגת הבינה לא הי' צריכין לברך.\n<b>קיצור</b><sup data-n=\"1171\">167</sup>. בבית ראשון הי' מאיר בינה, ובית שני מל', ולכן בבית ראשון לא הי' צריכים כ\"כ לברך, שהרי בינה היתה מאירה בבית ראשון אבל בבית שני מל', הוצרכו לתקן הברכות, והברכה בשם ומל' זו\"נ שרש ב' כרובים מט\"ט וסנד\"ל, שבהם וע\"י מסתתר השפע, והברכה גילוי, כמ\"ש ראו כל אפסי ארץ, וענין אמן הוי' אד' לכן היו מאה אדנים לקבל מאה ברכות.",[["1165","161","<b>ונערים ממשתה נגינתם</b>: נוסח ברכת נשואין."],["1166","162","<b>הנערים שהם מט\"ט וסנד\"ל</b>: ראה פרדס שער עה\"כ שכ\"ג, פי\"ד מערכת נער."],["1167","163","<b>אותותינו לא ראינו</b>: תהלים עד, ט."],["1168","164","<b>ראו כל אפסי ארץ</b>: תהלים צח, ג. בלקו\"ת לג\"פ כאן כט, ב: וראו [וכ\"ה לקמן בהקיצור כט, ג, ובאוה\"ת שם ע' 1104]."],["1169","165","<b>ותבין</b>: באוה\"ת כאן מעתיק את המאו\"א, וציון לזהר וכו'."],["1170","166","<b>ברוך הוא אותיות כרוב</b>: מובא גם באוה\"ת בראשית כאן ע' תקנב. ש\"א ס, ב. תו\"ח תרומה ח\"ב שיח ב. וראה תוספות השלם תרומה כה, יט: ד\"א כרוב ברוך."],["1171","167","<b>קיצור</b>: ראה אוה\"ת כאן ע' 1104 בשינויים."]]],[2000450163,"<h3>להבין ענין אכילת מצה כו' אך מה שיש</h3>\nוא\"ו) <b>אך</b><sup data-n=\"1172\">168</sup> מה שיש להקשות על מש\"א שבבית ראשון לא הי' מברכין, שהרי ארז\"ל ע\"פ ונאום הגבר הוקם על<sup data-n=\"1173\">169</sup> שדוד הע\"ה תיקן מאה ברכות, כמבואר ברבות פ' קרח<sup data-n=\"1174\">170</sup>, ואפ\"ל כי הנה מבואר בלק\"ת<sup data-n=\"1175\">171</sup> בד\"ה למנצח על השמינית ענין שלע\"ל דוקא יהי' כינור של שמונת נימין, אבל בבית ראשון הי' הכינור של שבעה נימין לבד, והובא במגדל עוז סוף ה' תשובה<sup data-n=\"1176\">172</sup> בשם הרמב\"ן",[["1172","168","<b>אך</b>: ברשימת המאמרים שמופיע בריש הבוך 1089 נרשם כאן מאמר (ג' מההמשך והוא) ד\"ה: להבין ענין אכילת מצה — ליל ב' של חה\"פ (הכולל פרקים ו — ח). היינו שבעת אמירת הדרוש היתה פתיחא זו [ראה גם בהמפתח שנדפס בריש ההמשך הערה ב: ”זו היא התחלת המאמר בעת שנאמר, כפי שמצאתי ברשימת ר\"ש סופר\" ע\"ש], ולע\"ע אין ידוע אם גם פתיחה זו נרשמה בפ\"ע ע\"י כ\"ק אדמו\"ר מהר\"ש. וראה לקמן — בחלק ההנחות — הנחה מדרוש זה מכ\"ק אדמו\"ר מהורש\"ב.\nלמאמר זה לפ\"ו — ראה אוה\"ת בראשית כרך ג' תקנב, א-ב [והוא לשונו בשינויים והוספות]. לפ\"ז — ראה אוה\"ת הנ\"ל. סידור שחה\"מ רפד, א ואילך. לפ\"ח — ראה אוה\"ת הנ\"ל ע' 1104 ואילך [והוא לשונו בשינויים והוספות]. קיצור פ\"ח הוא לשון אוה\"ת כאן ע' תקנה."],["1173","169","<b>ונאום הגבר הוקם על</b>: שמו\"ב כג, א."],["1174","170","<b>ברבות פ' קרח</b>: פי\"ח, כא."],["1175","171","<b>בלק\"ת</b>: תזריע כא, ד. ראה גם סה\"מ תרכ\"ט ע' יד. תר\"ל ס\"ע קו."],["1176","172","<b>במגדל עוז סוף ה' תשובה</b>: פ\"ח, ה\"ב."]]],[2000450164,"ז\"ל<sup data-n=\"1177\">173</sup> שהשבעה נימין הם ז' ספירות שהיו מקבלים מהם כו', ולע\"ל בימוה\"ש תושג הספי' השמינית והיא בינה נמצא עיקר גילוי הבינה לא הי' גם בבית ראשון, רק שהמל' היתה מגעת עד אימא שוה לז\"א כנ\"ל בשם המא\"א<sup data-n=\"1178\">174</sup>, והמק\"מ פ' שמות ד\"ט<sup data-n=\"1179\">175</sup>, אבל לע\"ל יהי' גילוי הבינה ממש וע\"ד ביום ההוא יהי'<sup data-n=\"1180\">176</sup> כו'.\n<b>והנה</b> פי' שמונה נימין היינו ג\"כ חיבור ב' הוויות<sup data-n=\"1181\">177</sup>, וז\"ע אז, וכמ\"ש אז ימלא שחוק פינו<sup data-n=\"1182\">178</sup> כו', והיינו חיבור סוכ\"ע שהוא א' פלא בז\"ת, והא בהא תלי' כי סוכ\"ע מאיר בבינה כנ\"ל, וכיוון שכן גם בבית ראשון הי' צריכין לברך ולהמשיך מבחי' נימא השמינית בז' נימין כו', ולכן תיקן דוד מאה ברכות, ויובן זה יותר ע\"פ מ\"ש האלשיך המובא לעיל<sup data-n=\"1183\">179</sup> שעיקר הברכה זהו שיהי' הגילוי למטה ממש ע\"ד מה שהוא למעלה וזה לא הי' כ\"א<sup data-n=\"1184\">180</sup> בבית ראשון כ\"א לע\"ל דוקא יהי' גילוי בחי' זו, ולכן גם בבית ראשון הי' צריכים לברך שלכן דוד תיקן מאה ברכות כי עיקר בחי' הברכה שיהי' הגילוי בבחי' ראי' ממש וזה יהי' רק לע\"ל שעז\"נ כי עין בעין יראו<sup data-n=\"1185\">182</sup> כו' ונגלה כבוד הוי' וראו<sup data-n=\"1186\">183</sup> כו', והגילוי שהי' בבית ראשון עיקרו בבחי' דעת ולא מערך הגילוי דלע\"ל<sup data-n=\"1187\">181</sup>, ומ\"מ רבינו אדמו\"ר נ\"ע נמשך אחר דעת המקובלים שבית ראשון הוא בחי' בינה ולכן לא הי' צריכין לברך, ואפי' לפי פי' זה הגיע המל' &lt;ט&gt;\nּ למקום הבינה, וא\"כ מאי נפ\"מ הלא האיר אור הבינה, והראי' שהי' החמשה דברי' שחסרו בב\"ש שזהו בחי' ה' עילאה שלא האיר בב\"ש, א\"כ מובן שבבית ראשון האיר ה' עילאה, וכנ\"ל בית לישראל סבא<sup data-n=\"1188\">185</sup>, ואפ\"ל לפי פי' רבינו אדמ\"ו נ\"ע שמה שדוד תיקון<sup data-n=\"1189\">186</sup> מאה זהו לפי שראה ברוה\"ק שבב\"ש לא יאיר אור הבינה לכן תיקון מאה ברכות, ודוחק<sup data-n=\"1190\">184</sup>.\n<span data-k=\"ks\"><b>קיצור.</b> ברבות פ' קרח אמרו שדוד תיקון מאה ברכות, הענין שגם בבית ראשון הי' הכינור כ\"ו נר<sup data-n=\"1191\">188</sup>, כ\"ו מספר ש' הוי' המאיר בנר בחי' כי </span>",[["1177","173","<b>בשם הרמב\"ן ז\"ל</b>: בשער הגמול — במהדורת שעוועל ע' שג."],["1178","174","<b>כנ\"ל בשם המא\"א</b>: על יד הערה 137."],["1179","175","<b>והמק\"מ. . ד\"ט</b>: לעיל על יד הערה 135."],["1180","176","<b>ביום ההוא יהי'</b>: זכרי' יד, ט."],["1181","177","<b>שמונה. . ב' הוויות</b>: ראה גם לקו\"ת תזריע כא, ד."],["1182","178","<b>אז ימלא שחוק פינו</b>: תהלים קכו, ב."],["1183","179","<b>האלשיך המובא לעיל</b>: רפ\"ה."],["1184","180","<b>כ\"א</b>: ב: ליתא. בלקו\"ת לג\"פ ואוה\"ת כאן ר\"ע 1104: גם."],["1185","182","<b>כי עין בעין יראו</b>: ישעי' נב, ח."],["1186","183","<b>ונגלה כבוד הוי' וראו</b>: ישעי' מ, ה."],["1187","181","<b>וזה. . דלע\"ל</b>: לשון אוה\"ת כאן ע' 1104 בסיום הקיצור דפ\"א."],["1188","185","<b>וכנ\"ל בית לישראל סבא</b>: בפ\"ה ד\"ה ועפ\"ז."],["1189","186","<b>תיקון</b>: לעיל וכן בב כאן: תיקן."],["1190","184","<b>ומ\"מ. . ודוחק</b>: כ\"ז ליתא בלקו\"ת לג\"פ ואוה\"ת כאן."],["1191","188","<b>הכינור </b>[בלקו\"ת לג\"פ ואוה\"ת כאן: הכנור]<b> כ\"ו נר</b>: בלקו\"ת תזריע כא, ד־ ועד\"ז מסעי צד, ב: בת\"ז סוף תיקון כ' [והוא במהדורת מנטובה שי\"ח נא, ב]. וראה גם אוה\"ת שה\"ש כרך ג ס\"ע שמה: ומענין כנור בת\"ז סוף תקון עשרים ובפרדס [שעה\"כ שכ\"ג, פ\"כ] ערך כנור ובמא\"א את [כנצ\"ל: אות] כף סל\"ה. באוה\"ת תצוה ע' א'תריג: בתיקוני זהר תיקון עשרה [ואוצ\"ל: עשרים] דנ\"א ע\"ב. ולפנינו תכ\"א נב, א."]]],[2000450165,"<b>אתה</b> נרי, בנר הוי' נשמת אדם, הי' של שבעה נימין, שהם בחי' ממכ\"ע, ולע\"ל יהי' של שמונת נימין גילוי סוכ\"ע המאיר בבינה, ולכן גם בבית ראשון היו צריכים לברך המאה ברכות להמשיך מבחי' סוכ\"ע בממכ\"ע<sup data-n=\"1192\">187</sup>, ורבינו ז\"ל נמשך אחר דעת המקובלים שבית ראשון בינה, או עכ\"פ המל' הי' במקום בחי' הבינה כו'.\nז) <b>והנה</b> המשכת הברכה הוא ע\"י ישראל שהם מאמינים בני מאמינים כמ\"ש במד\"ר פ' בשלח<sup data-n=\"1193\">189</sup> ע\"פ תשורי מראש אמנה<sup data-n=\"1194\">190</sup> כו' בזכות אברהם שהאמין בהוי'<sup data-n=\"1195\">191</sup> כו' היא האמונה שישראל נוחלים. וביאור הענין דהנה<sup data-n=\"1196\">192</sup> מצה נק' בזהר בשם מיכלא דמהימנותא<sup data-n=\"1197\">193</sup>, והיינו שהיא האכילה המחזקת את האמונה שיש בנש\"י בטבע תולדותם, וע\"ד ורעה אמונה<sup data-n=\"1198\">194</sup> שאין הפי' שרועה ומפרנס באמונה כ\"א רועה ומפרנס את האמונה שכבר ישנה, וכמו אכילת האדם שרועה ומפרנס חיות נפשו המחי' את הגוף שהחיות קדם להפרנסה ורק בלתי האכילה הי' נחלש ע\"י שמאבד כוחותיו ע\"י עשיותיו, וע\"י האכילה מתחזק כחו ומתמלא הנפסד בזמן ועשיותיו, כן הוא אכילת המצה לחזק את האמונה שלא יחלש בהאמונה ברבות הימים כו', ואמנם עצם ענין האמונה היא בירושה לנו מאבותינו<sup data-n=\"1199\">195</sup> אברהם הי' מאמין הראשון<sup data-n=\"1200\">197</sup> דכתיב בי' והאמין בהוי'<sup data-n=\"1201\">198</sup>, והוריש לבניו אחריו ענין האמונה<sup data-n=\"1202\">196</sup> להאמין בהוי' אחד כו', וע\"י אכילת המצה מתחזק כח אמונה זו, ושיתוסף אור וחיות באמונה זו להיות צדיק באמונתו יחי'<sup data-n=\"1203\">199</sup> כו', להיות בחי' חיות באמונה זו, וזה פועל אכילת המצה מיכלא דמהימנותא. ולהבין ענין בחי' האמונה, הנה מצות האמונה היא מפסוק אנכי<sup data-n=\"1204\">200</sup> הוי' אלקיך אשר הוצאתיך מארץ מצרים<sup data-n=\"1205\">201</sup>, ולכאורה צ\"ל למה אמר אשר הוצאתיך מאמ\"צ, ולא אמר אשר בראתי<sup data-n=\"1206\">202</sup> יש מאין שמים וארץ וכל אשר בהם שלכאורה זהו יותר",[["1192","187","<b>ברבות. . בממכ\"ע</b>: לשון אוה\"ת כאן ע' 1104 בהקיצור עם הוספות."],["1193","189","<b>במד\"ר פ' בשלח</b>: בלקו\"ת לג\"פ ואוה\"ת כאן ע' 1104: ”פכ\"ג\", ה."],["1194","190","<b>תשורי מראש אמנה</b>: שה\"ש ד, ח."],["1195","191","<b>בהוי'</b>: בשמו\"ר: בהקב\"ה שנאמר והאמין בה'. וכן נעתק באוה\"ת ראה ע' תשכח. בלקו\"ת לג\"פ ואוה\"ת כאן: בה'."],["1196","192","<b>דהנה </b>: להבא לקמן ראה סידור שער חה\"מ רפד, א. סה\"מ תרכ\"ז ע' רלג ואילך. תרל\"ה ח\"א ע' רלה ואילך."],["1197","193","<b>מצה. . מיכלא דמהימנותא</b>: ראה זהר רע\"מ בא מא, א. מאמרי אדה\"א ויקרא ח\"ב ע' תרלו. וש\"נ."],["1198","194","<b>ורעה אמונה</b>: תהלים לז, ג. וראה גם אוה\"ת פ' ראה ע' תשכח."],["1199","195","<b>האמונה היא בירושה לנו מאבותינו</b>: ראה תניא פי\"ח ופל\"ג. מאמרי אדה\"א נ\"ך ע' כח. וש\"נ. שה\"א ו, א ובהערה 13."],["1200","197","<b>אברהם הי' מאמין הראשון</b>: בנוסף להמובא בר\"פ זה, ראה שהש\"ר פ\"ד, ח ג."],["1201","198","<b>והאמין בהוי'</b>: לך טו, ו. וראה גם בסוף הפרק."],["1202","196","<b>אברהם. . והוריש לבניו. . האמונה</b>: ראה גם מאמרי אדה\"א נ\"ך שם. תו\"ח וירא קו, ד. בא ח\"א קטז, ג. תצוה ח\"ב שיח, ג."],["1203","199","<b>צדיק באמונתו יחי'</b>: נסמן לקמן בהערה 233. וראה הערה 1684."],["1204","200","<b>מצות האמונה. . אנכי</b>: ראה ספר המצות להרמב\"ם מ\"ע א. ולהצ\"צ מצות האמנת אלקות מד, ב ואילך. וש\"נ. לקמן בחלק ההנחות בהנחה מדרוש זה."],["1205","201","<b>אנכי. . מארץ מצרים</b>: יתרו כ, ב."],["1206","202","<b>אנכי. . ולא אמר אשר בראתי</b>: ראה גם מאמרי אדה\"א ויקרא ח\"א ע' תא ואילך. וש\"נ. שה\"א יא, ב הערה 13. סה\"מ תרכ\"ז ס\"ע רלג ואילך. וש\"נ. תרכ\"ט ע' רכ. תרל\"ה ח\"א ע' רלו. וש\"נ. תרמ\"ג ע' קטז. תרנ\"ז ע' עד."]]],[2000450166,"פלא מיציאת מצרים, שכל האותות והמופתים שהי' במצרים היו יש מיש עד\"מ מדם נעשה מים<sup data-n=\"1207\">203</sup> וכן כולם, ואפי' קרי\"ס אם כי הוא יוצא מדרכי הטבע לגמרי עכ\"ז ה\"ה יש מיש שהמים קמו כמו נד ונתגלה היבשה, אבל בריאת שמים וארץ ה\"ה יש מאין לגמרי דבר מלא דבר<sup data-n=\"1208\">204</sup> כו', אך הענין הוא דשרש התהוות כל העולמות הם מבחי' דבר ה' כמ\"ש בדבר ה' שמים נעשו<sup data-n=\"1209\">205</sup> וברוח פיו כל צבאם, שכלליות הדבור עד\"מ הוא רק הארת כח &lt;י&gt;\nּ הנפש המדברת ולא עצמותו, ובאמת כלליות הבריאה היא רק מב' אותיות לבד כמ\"ש כי בי\"ה הוי' צור עולמים וארז\"ל ביו\"ד נברא העוה\"ב, ובה' נברא<sup data-n=\"1210\">206</sup> העוה\"ז שרק בשני אותיות נבראו כלליות העוה\"ב והעוה\"ז שאינו תופס מקום כלל, אפי' לגבי דבור האדם וכ\"ש לגבי' ית' כו', ולכן אני הוי' לא שניתי<sup data-n=\"1211\">207</sup> שלא יש שום שינוי כלל לפניו ית' ואתה הוא קודם שנברא העולם ואתה הוא לאחר<sup data-n=\"1212\">208</sup> שנברא העולם בלי שום שינוי כלל כי כלליות ההשתלשלות היא מהארה בעלמא שאינו נוגע כלל, ולכן לא שניתי כלל, וגם כי כלליות ענין הבריאה הוא בכדי שיהי' מלך על עם שזהו רק בחי' התפשטות לבד ולא עצמותו וכנודע כי מלך שמו נק' עליהם<sup data-n=\"1213\">209</sup> שרק התפשטות שמו ולא עצמותו כו', רק מפני שהוא ית' א\"ס לכן גם התפשטות הארתו היא ג\"כ התפשטות עד נון אלפים יובלות<sup data-n=\"1214\">210</sup> שהיא בחי' עליות המדריגות והכל בבחי' שמו היינו מדת מלכותו לבד, בחי' כח הפועל בנפעל<sup data-n=\"1215\">211</sup> כו', אשר בבחי' זו הכל מודים, ואין בזה שבח באמונת נש\"י מאחר שהכל מודים גם חסידי<sup data-n=\"1216\">212</sup> כו', רק מפני שהנה\"א נתלבשה בלבוש שק לכן צריכה להתבוננות בבחי' יש מאין שזהו רק כדי להסיר העורון לבד דעיני בשר שרואים את הטפל לעיקר, ואמנם עיקר בחי' האמונה הוא בבחי' אוא\"ס הסוכ\"ע באמרו ה' אלקינו<sup data-n=\"1217\">213</sup> ה' אחד בחי' אוא\"ס עצמותו ולא מציאותו כמו כח הפועל בנפעל שהיא רק בחי' ידיעת מציאותו לבד כו', ויובן עד\"מ הנשמה שמחי' את הגוף הגם שלא ראה את",[["1207","203","<b>מדם נעשה מים</b>: בסה\"מ תרל\"ה שם: שממים נעשה דם."],["1208","204","<b>דבר מלא דבר</b>: ראה גם לקמן (בחלק ההנחות) בהנחה ד\"ה וידבר וגו' ויצוום בהערה 29."],["1209","205","<b>בדבר ה' שמים נעשו</b>: תהלים לג, ו."],["1210","206","<b>כי בי\"ה. . ובה' נברא</b>: ישעי' כו, ד. ראה מנחות כט, ב."],["1211","207","<b>אני הוי' לא שניתי</b>: מלאכי ג, ו."],["1212","208","<b>ואתה הוא קודם. . לאחר</b>: ראה תפלת השחר. של\"ה ג, ב. מאמרי אדה\"ז מארז\"ל ע' שלו."],["1213","209","<b>מלך שמו נק' עליהם</b>: ראה ד\"ה לכן אמור תקס\"ג בתו\"ח וארא ח\"א סט, ב ואילך. וש\"נ."],["1214","210","<b>נון אלפים יובלות</b>: ראה ש\"ך ר\"פ בהר. מאמרי אדה\"א בראשית ע' רסו. וש\"נ. שע\"ת ע, ג ובהערה 43. ש\"א ח, ב ובהערה 30. תו\"ח ויקהל ח\"ב תלא, א. אוה\"ת פ' ראה ע' תשכט. לקמן (בחלק ההנחות) בהנחה כאן ובהערה 52."],["1215","211","<b>כח הפועל בנפעל</b>: בלקו\"ת שלח מז, א: בספרים. ראה הנסמן במ\"מ לשם. ספר הישר (לר\"ת ) סוף ש\"ג."],["1216","212","<b>שהכל מודים גם חסידי</b>: ראה הנסמן באוה\"ת פ' ראה ע' תשכט. שה\"א מ, א ובהערה 2. וראה גם ספר הערכים חב\"ד כרך ב מערכת אוה\"ע ע' ערב ואילך."],["1217","213","<b>באמרו ה' אלקינו</b>: בק\"ש."]]],[2000450167,"הנשמה מימיו כלל עכ\"ז האם צריך הוא לאמונה שיש בו חיות המחי' את הגוף, כי מאחר שרואה שגופו חי ה\"ה יודע ברור שיש איזהו חיות אשר מחייה אותו, והרי בצאת הנפש מן הגוף ה\"ה נשאר כאבן דומם שאין לו הופכים כלל, וא\"כ כשרואה העולם ומלואה ה\"ז כמו גוף גדול חי שבהכרח לומר שיש דבר המחי' אותו והוא הוא המהוה, כמאמר א\"ת מחי' אלא מהוה<sup data-n=\"1218\">214</sup> וכמ\"ש ובטובו מחדש<sup data-n=\"1219\">215</sup> בכי\"ת מע\"ב שבכל עת ובכל רגע נמשך התחדשות החיות להוות מע\"ב מאין ליש, וזהו סיבת קיומם כו', וע\"ז א\"צ אמונה כלל שהרי נראה ונגלה לעין כל, רק שידיעה זו היא רק בחי' ידיעות המציאות לבד, ולא השגת המהות אבל בחי' יחוד דק\"ש ה' אלקינו ה' אחד הוא בבחי' מהות האוא\"ס הסוכ\"ע שע\"ז שייך אמונה, וז\"ע אמונת נש\"י שהם מאמינים בני מאמינים שמאמינים בבחי' אוא\"ס ב\"ה הסוכ\"ע כו', ולכן באברהם כתי' והאמין בהוי' ש' הוי' דסוכ\"ע וכן ויאמינו בהוי' שבקרי\"ס קאי ג\"כ על בחי' אוא\"ס ב\"ה הסוכ\"ע שע\"ז שייך ענין בחי' האמונה כו'.\n<span data-k=\"ks\"><b>קיצור.</b> מאמינים בני מאמינים, והמצה מיכלא דמהמנותא לחזק האמונה להיות צדיק באמונתו יחי', ובבחי' ממכ\"ע אינו שייך אמונה כשם שאינו שייך אמונה על חיות הנפש המחי' את הגוף, כ\"א האמונה היא בבחי' אוא\"ס הסוכ\"ע כו'.</span>\n&lt;יא&gt;\nּ<b>ח)</b> ועפ\"ז יובן משנת\"ל<sup data-n=\"1220\">216</sup> שהאמונה<sup data-n=\"1221\">217</sup> היא למעלה משרש נש\"י שלכן אפי' בבחי' מזלייהו דחזי היא ג\"כ בבחי' אמונה כו' דהנה בלק\"ת סד\"ה האזינו<sup data-n=\"1222\">218</sup> השמים דרוש הראשון נת' דשרש מזלייהו דנש\"י נמשך מבחי' המזלות דונוצר ונקה, וידוע שהם נק' שערות<sup data-n=\"1223\">219</sup> יגת\"ד, וענין משל השערות מבואר בתו\"א פ' תצוה<sup data-n=\"1224\">220</sup> בד\"ה ועשית בגדי קדש, שאין להם ערך ויחוס כלל עם המוחין שבראש, ואין עיקר וחיות<sup data-n=\"1225\">221</sup> המוחין מתלבש בהם כלל שהרי אם גוזזין שערותיו אינו מרגיש שום כאב כלל, ע\"ש ולכן אפי' חכ' עילאה היונקת ממזל השמיני<sup data-n=\"1226\">222</sup> ונוצר היא כעשייה גופנית<sup data-n=\"1227\">223</sup> לגבי אור א\"ס ב\"ה, ולכן אפי' דעת עליון",[["1218","214","<b>א\"ת מחי' אלא מהוה</b>: ראה שער היחוה\"א פ\"ב ובמ\"מ, הגהות והע\"ק שם. הערה בסה\"מ תש\"ד ע' 20."],["1219","215","<b>וכמ\"ש ובטובו מחדש</b>: ברכות ק\"ש."],["1220","216","<b>משנת\"ל</b>: פ\"ג על יד הערה 45 ואילך."],["1221","217","<b>שהאמונה</b>: מכאן הוא לשון אוה\"ת בראשית ע' 1104 ואילך בשינויים והוספות."],["1222","218","<b>בלק\"ת סד\"ה האזינו</b>: עג, ג. ראה גם שע\"ת פג, רע\"ד."],["1223","219","<b>המזלות דונוצר ונקה. . שערות</b>: ראה לקו\"ת אמור לט, ג. מאמרי אדה\"ז תקס\"ב ח\"א ע' צט. פרשיות התורה ח\"א ע' קכז. שעה\"י קכז, ב."],["1224","220","<b>בתו\"א פ' תצוה</b>: פב, ב."],["1225","221","<b>וחיות</b>: בתו\"א: חיות."],["1226","222","<b>חכ'. . ממזל השמיני</b>: ראה זהר אד\"ז האזינו רפט, ב. ע\"ח שער הכללים פ\"ה. תו\"ח שמות ח\"א לו, א הערה 455."],["1227","223","<b>חכ'. . כעשייה גופנית</b>: ראה תניא פ\"ב בהגהה. אוה\"ת כאן ע' 1104. ע' 1124 הובא לקמן פל\"א [ושם: והעשי' גשמיות]. לעיל המשך וידבר וגו' ויצוום פ\"ט על יד הערה 174. לקמן (בחלק ההנחות) ד\"ה ביום ההוא יהי' על יד הערה 15. ברשימה דר\"י שו\"ב על יד הערה 8. ד\"ה פי' פתחה בחכמה על יד הערה 50. הנסמן במאמרי אדה\"א קונטרסים ע' רנב."]]],[2000450168,"נק' בהמה רבה<sup data-n=\"1228\">224</sup>, ואוא\"ס ב\"ה המאיר בכתר נק' רישא דלא אתיידע<sup data-n=\"1229\">225</sup> כו', שאינו מושג אפי' בחכ' וד\"ע דאצי', וע\"כ האמונה היא למעלה מהחכמה ודעת, וע' בסידור שער הל\"ג בעומר<sup data-n=\"1230\">226</sup> בענין ברכה והודאה, וזהו ועטרותיהם היא האמונה שנק' עטרה<sup data-n=\"1231\">228</sup> היא בראשיהם<sup data-n=\"1232\">227</sup>. וע' בלק\"ת ר\"פ צו<sup data-n=\"1233\">229</sup> בענין נשמות חדשות שכמו שהמלאכים נק' בשם בהמות לגבי הנשמות כן נשמות דעכשיו נק' בשם בהמות נגד הנשמות חדשות, והארה מהם יתלבש בלויתן ושור הבר והנשמות חדשות יעלו אותם ע\"ד שהנשמות דעכשיו מעלים המאכלים שמשתלשלים מהמלאכים, ועכ\"ז בב\"ר שהיו הנשמות גבוהות הי' אצלם בחי' גילוי אמונה זו, ולכן לפי דעת רבינו ז\"ל לא הי' מברכין כלל, אבל בב\"ש שחסר ה' דברים, ונתמעטו הלבבות תקנו הברכות כו'.\n<b>וביאור</b> הענין כי הנה נת\"ל<sup data-n=\"1234\">230</sup> אשר בבית ראשון היתה המל' מקבלת מאימא עילאה כו', משא\"כ בבית שני כו', והנה חו\"ב הם תרדל\"מ, והחכ' נק' ראי'<sup data-n=\"1235\">231</sup> כמארז\"ל איזהו חכם<sup data-n=\"1236\">232</sup> הרואה את הנולד, והיינו כאילו רואה בעין ממש הולדת והתהוות היש מאין, וע\"כ היו הנשמות במעלה עליונה להיות וצדיק באמונתו יחי'<sup data-n=\"1237\">233</sup> כאילו רואה ממש כיון שהי' מאיר בחי' חו\"ב והחכ' נק' ראי' כנ\"ל ולכן במ\"ת הי' רואים את הנשמע<sup data-n=\"1238\">234</sup> שהחו\"ב הם תרדל\"מ, וכל זמן ב\"ר הי' מאיר חו\"ב שהוא ענין ראי' ושמיעה<sup data-n=\"1239\">235</sup> כו', משא\"כ בבית שני שנתמעטה קומת נש\"י ואינה מקבלת המוחין מחו\"ב, כ\"א מהמדות ולכן נפסקה ג\"כ הנבואה<sup data-n=\"1240\">236</sup> ע\"כ אין מאיר בחי' חו\"ב בהנשמות להיות בחי' ראי' ממש, ולכן הגם שכ\"י מאמינים בני מאמינים, עכ\"ז אינה בבחי' כאילו רואה ממש.",[["1228","224","<b>דעת עליון נק' בהמה רבה</b>: ראה תניא ספמ\"ו ובמ\"מ הגהות והע\"ק שם."],["1229","225","<b>רישא דלא אתיידע</b>: ראה זהר אד\"ז האזינו רפח, א. ע\"ח שער א\"א שי\"ג, פ\"ב. לקו\"ת ראה כא, ב. יו\"כ עא, ג-ד."],["1230","226","<b>בסידור שער הל\"ג בעומר</b>: שה, ד ואילך."],["1231","228","<b>האמונה שנק' עטרה</b>: ראה מאמרי אדה\"ז הקצרים ע' תסט. וש\"נ. שה\"א ו, א ובהערה 10. תו\"ח משפטים ח\"ב רפ, ב."],["1232","227","<b>ועטרותיהם. . בראשיהם</b>: ברכות יז, א."],["1233","229","<b>בלק\"ת ר\"פ צו</b>: ז, ג."],["1234","230","<b>נת\"ל</b>: פ\"ה, ד\"ה והנה בית ראשון."],["1235","231","<b>והחכ' נק' ראי'</b>: ראה גם בסמוך הערה 235"],["1236","232","<b>איזהו חכם</b>: תמיד לב, א. ראה תניא פמ\"ג. מאמרי אדה\"א דברים ח\"א ע' רכא. וש\"נ. שע\"ת עא, ג ובהערה 23. תו\"ח תצוה ח\"ב שכט סע\"ד ואילך."],["1237","233","<b>וצדיק באמונתו יחי'</b>: חבקוק ב, ד."],["1238","234","<b>במ\"ת הי' רואים את הנשמע</b>: ראה מכילתא ורש\"י יתרו כ, טו. לקו\"ש יתרו כרך ו ע' 120 בהערה 5-6. ובהשמטה לשם בע' 416. מאמרי אדה\"א במדבר ח\"ב ע' תרכו."],["1239","235","<b>חו\"ב. . ראי' ושמיעה</b>: ראה תו\"א וירא טו, ד. מקץ מ, א. מאמרי אדה\"ז תקס\"ג ח\"א ע' רפז. תקס\"ט ע' פט. שער האמונה מג, ב. תו\"ח שמות ח\"א כז, ג הערות 15-16. לקמן מאמר ד\"ה על חומותיך על יד הערה 17. ו(בחלק ההנחות) בהנחה שם על יד הערה 14."],["1240","236","<b>בבית שני. . נפסקה ג\"כ הנבואה</b>: ראה סוטה מח, ב. לקו\"ש ח\"ש כרך כ ע' 97 הערה 64. שופטים כרך יד ע' 72 ואילך ובהנסמן שם. סה\"ש תנש\"א ח\"ב ע' 788 ואילך."]]],[2000450169,"<b>גם</b> י\"ל שהאמונה נק' עטרה כנ\"ל והוא בחי' כתר שבמל' מקור הנשמות, והרי אז בבית ראשון שהיתה מקבלת מהבינה, א\"כ הי' הכתר שלה מאיר באור גדול יותר, א\"כ הי' אצלם גילוי האמונה כאילו רואה כו'.\n<b>ועוד</b> יובן ענין זה עפמ\"ש בת\"א בד\"ה ואלה המשפטים<sup data-n=\"1241\">237</sup>, בפי' וזרעתי את בית<sup data-n=\"1242\">238</sup> ישראל<sup data-n=\"1243\">239</sup> זרע אדם וזרע בהמה, שיש ב' מדריגות בנש\"י הא' הם הנשמות הגבוהות מאד שהם נשמות דאצי' ונקראו זרע אדם, שיש בהם דעת חזק באלקות, והדעת ממשיך בחי' ראי' בבחי' &lt;יב&gt;\nּ שמיעה וממשיך מהמוחין בהמדות* אבל הבחי' הב' הן נשמות דבי\"ע הנק' זרע בהמה שאין בהם דעת מבחי' אצילות כ\"א מבחי' בי\"ע כו', והנה בבית ראשון שהי' המל' במדריגת הבינה לכן היו נמשכים נשמות גבוהות, וכמו הנשמות שנק' אחים וריעים<sup data-n=\"1244\">241</sup> למקום, וכמ\"ש למען אחיי וריעי<sup data-n=\"1245\">242</sup> כו' למען בית אלקינו<sup data-n=\"1246\">243</sup> כו', שאז בזמן שבית אלקינו הי' קיים הי' נמשכות נשמות הנק' אחים ורעים, וכן הנשמות הנק' בנים היו ג\"כ נשמות גבוהות, אבל בזמן ב\"ש שנתמעטה הקומה, וכתי' ונהר יחרב ויבש<sup data-n=\"1247\">244</sup> לא נמשכו נשמות עליונות כ\"כ, כ\"א נשמות דבי\"ע, תיקנו אנשי כנסה\"ג את הברכות דהנה הברכות הם המשכות חו\"ב, איהו ברוך ואיהי ברכה כמ\"ש בזח\"ב תרומה דקס\"ב א' ובזח\"ג פ' ואתחנן דרס\"ד ב', וחכמה היא בחי' ראי' כנ\"ל, ולכן החכמים שהם עיני העדה<sup data-n=\"1248\">245</sup> תקנו הברכות ועמ\"ש מזה בלק\"ת פ' ואתחנן בד\"ה ואתחנן ובהביאור<sup data-n=\"1249\">246</sup>, גם הנה מבואר בד\"ה וידעת היום והשבות<sup data-n=\"1250\">247</sup> שבחי' ממכ\"ע א\"צ לאמונה וכנ\"ל כי ע\"ז נאמר ומבשרי אחזה אלקה,",[["1241","237","<b>בת\"א בד\"ה ואלה המשפטים</b>: בתחילתו עד, ג."],["1242","238","<b>וזרעתי את בית ישראל</b>: ירמי' לא, כו [בדילוג]."],["1243","239","<b>בית ישראל</b>: באוה\"ת כאן תקנג, א: בני ישראל — בהכתוב ובתו\"א כבפנים. ב: ב\"י."],["1244","241","<b>הנשמות שנק' אחים וריעים</b>: ראה זהר משפטים קכב, רע\"א. ביאוה\"ז פינחס קיד, ד — קטו, ב. ולהצ\"צ כרך א ע' תקמו פ\"ב ופ\"ג. מאמרי אדה\"ז על מארז\"ל ע' רצא. לקו\"ת צו טז, סע\"ב ואילך. שה\"ש יט, סע\"ב ואילך. מאמרי אדה\"ז תקס\"ה ח\"א ע' קכח. תקע\"א ע' קנד. מאמרי אדה\"א ויקרא ח\"א ע' שפז ואילך. שער האמונה ע' צז ואילך."],["1245","242","<b>למען אחיי וריעי </b>[ב: וריעיי]: תהלים קכב, ח."],["1246","243","<b>למען בית אלקינו</b>: תהלים שם ט [בדילוג, וכ\"ה בלקו\"ת לג\"פ ואוה\"ת כאן]."],["1247","244","<b>ונהר יחרב ויבש</b>: איוב יד, יא."],["1248","245","<b>החכמים שהם עיני העדה</b>: שלח טו, ד. ראה מאמרי אדה\"ז על פרשיות התורה ח\"א ע' רסד ובהנסמן במ\"מ לשם. תו\"ח בא ח\"א קב, א ובהערה 248."],["1249","246","<b>בלק\"ת. . בד\"ה ואתחנן ובהביאור</b>: ב, סע\"ד. ג, ג."],["1250","247","<b>בד\"ה וידעת היום והשבות</b>: לקו\"ת ואתחנן ד, א."]]],[2000450170,"אחזה ממש, רק האמונה היא בבחי' סוכ\"ע אני הוי' לא שניתי, וכן נת' בת\"א פ' בשלח<sup data-n=\"1251\">248</sup> בד\"ה וירא ישראל, פי' ויראו<sup data-n=\"1252\">249</sup> העם את הוי'<sup data-n=\"1253\">250</sup> ויאמינו בהוי' היינו ב' שמות הוי' הנז' למעלה, ויראו העם את הוי' היינו ש' הוי' דלתתא המהוה כל העולמות מאין ליש, ע\"י ש' הוי' יו\"ד צמצום ה' התפשטות<sup data-n=\"1254\">251</sup> כו', ונק' עלמא דאתגליא שהוא בחי' השגה ושייך בו לשון יראה יראה בושת כמשל הרואה את המלך כו', ויאמינו בהוי' הוא ש' הוי' דלעילא שהוא בחי' רצון מה שעלה במחשבה להיות הוי' דלתתא להוות העולמות, וע\"ז ארז\"ל עד שלא נברה\"ע<sup data-n=\"1255\">252</sup> הי' הוא ושמו בלבד, וז\"ע עלמא דאתכסיא שאינו נראה ומושג ולא שייך בו בחי' יראה כ\"א אמונה יעו\"ש, נמצא מובן שעיקר ענין האמונה מה שאין בו השגה רק שצ\"ל אמונה זהו בבחי' סוכ\"ע שנק' ש' הוי' דלעילא, והרי זהו ענין הברכות בא\"י שממשיכים מבחי' עלמא דאתכסיא ש' הוי' דלעילא להאיר בעלמא דאתגלי', לכן ע\"י הברכות נמשך בחי' האמונה, וזהו א\"ת מ\"ה אלא מאה שע\"י מאה ברכות נמשך בחי' מ\"ה וביטול היש שזהו ג\"כ ענין בחי' אמונה לבטל שכלו והשגתו, והיינו להיות ומ\"ה שם בנו<sup data-n=\"1256\">253</sup> כו' בחי' בני בכורי ישראל<sup data-n=\"1257\">254</sup>.\n<span data-k=\"ks\"><b>קיצור.</b> מאמינים, מראש אמנה, אמונה למעלה גם ממזלייהו חזי, מזל שערות, בב\"ר נשמות עליונות הנק' אחים למקום שנמשכו מיחוד חו\"ב, ראי' ושמיעה, גם זרע אדם, משא\"כ בב\"ש כענין נשמות דזרע בהמה בי\"ע לכן צריך ברכה להמשיך ויאמינו בהוי' דע\"ק שהוא בחי' סוכ\"ע כו'.</span>",[["1251","248","<b>בת\"א פ' בשלח</b>: סב, א ד\"ה והנה ישראל."],["1252","249","<b>ויראו</b>: ב: וייראו."],["1253","250","<b>וייראו העם את הוי</b>: בשלח יד, לא."],["1254","251","<b>יו\"ד צמצום ה' התפשטות</b>: ראה אגה\"ת פ\"ד. ביאוה\"ז אחרי עו, ג ואילך. ולהצ\"צ שם כרך א ע' שסג ואילך. לקו\"ת שמ\"ע צב, ד. תו\"ח בשלח ח\"א קנ, א ואילך. סה\"מ תרנ\"ו ע' שסח ואילך. תרס\"ו ע' רז ואילך."],["1255","252","<b>עד שלא נברה\"ע</b>: ראה פדר\"א פ\"ג. תו\"ח וארא ח\"א נג, ב הערה 6."],["1256","253","<b>ומ\"ה שם בנו</b>: משלי ל, ד."],["1257","254","<b>בני בכורי ישראל</b>: שמות ד, כב."]]],[2000450171,"<h3>ביום ההוא יהי' כו' וסדר ההמשכה</h3>\nט) <b>וסדר</b><sup data-n=\"1258\">255</sup> ההמשכה הוא תחילה בנש\"י ואח\"כ בעולם שזהו אלקינו מלך העולם ויובן זה ע\"פ מ\"ש בת\"א<sup data-n=\"1259\">256</sup> בד\"ה זכור ושמור בדבור אחד נאמרו, שהמלאכים שרשם מבחי' הדיבור כו', משא\"כ ישראל עלו במח'<sup data-n=\"1260\">257</sup> כו', וזהו נק' איהו וגרמוהי<sup data-n=\"1261\">258</sup> חד &lt;יג&gt;\nּ בהון, ומזה יובן משנת\"ל<sup data-n=\"1262\">259</sup> שעל המלאכים נאמר ומשם יפרד והיינו לפי שנמשכו מבחי' הדבור, אשר הדבור עד\"מ יוצא ונעשה דבר נפרד",[["1258","255","<b>וסדר</b>: ברשימת המאמרים שמופיע בריש הבוך 1089 נרשם כאן מאמר (ד' מההמשך והוא) ד\"ה: ביום ההוא יהי' הוי' א' — ש' חוה\"פ (פרק ט). היינו שבעת אמירת הדרוש היתה פתיחא זו, ולע\"ע אין ידוע אם גם פתיחה זו נרשמה בפ\"ע ע\"י כ\"ק אדמו\"ר מהר\"ש. וראה לקמן (בחלק ההנחות) הנחה מדרוש זה מכ\"ק אדמו\"ר מהורש\"ב.\nלמאמר זה ראה אוה\"ת בראשית כאן ע' 1106 פ\"ג והוא לשונו בשינויים והוספות. הקיצור — אוה\"ת כאן ע' תקנה בשינויים."],["1259","256","<b>בת\"א</b>: יתרו עא, א ד\"ה והנה."],["1260","257","<b>ישראל עלו במח'</b>: ראה ב\"ר פ\"א, ד. לקו\"ת בחוקותי מז, א. שע\"ת קטו, ב. תו\"ח שמות ח\"א לב, ב ובהערה 248."],["1261","258","<b>איהו וגרמוהי</b>: ראה ת\"ז בהקדמה (ג, ב)."],["1262","259","<b>משנת\"ל</b>: פ\"ב."]]],[2000450172,"מהאדם המדבר, משא\"כ המחשבה מתאחדת עם הנפש המשכלת, וכמ\"ש מזה באריכות בלק\"ת פ' נצבים<sup data-n=\"1263\">260</sup> בד\"ה כי כארץ תוציא צמחה, ושם פ\"א שהמחשבה שמתאחדת עם הנפש<sup data-n=\"1264\">261</sup> הנה היא התפשטות השכל ולא התפשטות גופני, וגם אינה<sup data-n=\"1265\">262</sup> נעשית נפרד<sup data-n=\"1266\">263</sup> מעצמיות האדם כי אדרבה היא מיוחדת בעצמותה<sup data-n=\"1267\">264</sup> כו', וע' בלק\"ת בד\"ה מנורת זהב<sup data-n=\"1268\">265</sup>, שלכן הם דוקא הכלי לשמן ואור שבמנורה שהם המצות והתורה, ובודאי שהתומ\"צ נמשכים מש' הוי' דלעילא כמ\"ש בת\"א בד\"ה וירא ישראל הנ\"ל<sup data-n=\"1269\">266</sup>, וכן נת' בלק\"ת שה\"ש<sup data-n=\"1270\">267</sup> בביאור ע\"פ שחורה אני דרוש השני שע\"ז הפסוק בהביאור, ושם פ\"ו יעו\"ש, וא\"כ לפ\"ז פי' הוי' אלקינו קאי על ש' הוי' דלעילא שנמשך ומאיר בנש\"י להיות אלקינו ממש, משא\"כ רם על כל<sup data-n=\"1271\">268</sup> כו' כמ\"ש בת\"א<sup data-n=\"1272\">269</sup> בד\"ה ויקח מן הבא בידו מנחה בת\"א דמ\"ב סע\"ד<sup data-n=\"1273\">270</sup>, ויעקב יוד עקב ה' אלקינו כו' הגם שיו\"ד היא הארה כו' ובד\"ה בשלח פרעה<sup data-n=\"1274\">271</sup> בענין כמה ארך אפים כו' משא\"כ בסטרא דקדושה כו', ולכן נק' יעקב הקטן כו' בחי' צמצום שהרי בעצמותו ומהותו כו', וע' עוד מענין ה' אלקינו בד\"ה כי ביום הזה יכפר דרוש הראשון פ\"ב בלק\"ת פ' אחרי, ומש\"ע<sup data-n=\"1275\">272</sup> ע\"פ עולת תמיד<sup data-n=\"1276\">273</sup> בפי' ישראל לי ראש<sup data-n=\"1277\">274</sup> כמו שעיקר התלבשות אור הנשמה הוא בהמוחין שבראש ומהם נתפשט ונמשך בכל האיברים כך הוא ענין לי ראש שבנש\"י לפי שעלו במח' נמשך בהם התלבשות החיות מאור א\"ס ומשם נמשך ומתפשט כו', וע' בד\"ה והי' ביום ההוא<sup data-n=\"1278\">275</sup> יתקע בשופר גדול שעד\"ז הוא ענין ר\"ה לגבי כל ימות השנה, שנק' ראש שבו נמשך כלליות החיות של כל השנה וממנו נמשך ומתחלק אח\"כ לי\"ב חדשים כו' ע\"ש, ומכ\"ז יובן ענין ה' אלקינו, וע' בד\"ה לבאר ענין יוהכ\"פ<sup data-n=\"1279\">276</sup> ספ\"א גבי ולפי שישראל עלו במח' כו', שבחי' ישראל גבוה מאד נעלה מבחי' התפשטות חיצוני' מלכותו ית' כו' ע\"ש, ועמ\"ש בד\"ה מה טובו<sup data-n=\"1280\">277</sup> ושם פ\"ב וספ\"ג בפי' ברוך אתה ה' אלקינו, אלקינו הוא ממכ\"ע, ושיהי' הוי' אלקינו",[["1263","260","<b>בלק\"ת פ' נצבים</b>: נ, ב. וראה לקמן (בחלק ההנחות) בהנחה כאן על יד הערה 30."],["1264","261","<b>הנפש</b>: ב ובלקו\"ת שם: השכל."],["1265","262","<b>אינה</b>: ב ובלקו\"ת שם: איננה."],["1266","263","<b>נפרד</b>: בלקו\"ת שם: בחי' נפרד."],["1267","264","<b>בעצמותה</b>: בלקו\"ת שם: בעצמותו."],["1268","265","<b>בלק\"ת בד\"ה מנורת זהב</b>: בהעלותך לד, ב פ\"ד."],["1269","266","<b>בת\"א. . הנ\"ל</b>: פ\"ח הערה 248."],["1270","267","<b>בלק\"ת שה\"ש</b>: י, ד."],["1271","268","<b>רם על כל</b>: תהלים קיג, ד."],["1272","269","<b>בת\"א</b>: בלקו\"ת לג\"פ ואוה\"ת כאן ע' תקנד ליתא."],["1273","270","<b>בת\"א דמ\"ב סע\"ד</b>: במהדורת קה\"ת כה, סע\"ג."],["1274","271","<b>ובד\"ה בשלח פרעה</b>: תו\"א בשלח סא, א ד\"ה וביאור."],["1275","272","<b>ומש\"ע</b>: ומה שכתב עוד."],["1276","273","<b>ע\"פ עולת תמיד</b>: ראה מאמרי אדה\"ז תקס\"ט ע' רח. אוה\"ת פינחס ס\"ע א'קמא ואילך. שם כרך ו ס\"ע א'תתקכז ואילך."],["1277","274","<b>ישראל לי ראש</b>: לקמן במאמר ד\"ה ישמח משה על יד הערה 9: כמארז\"ל. ראה פע\"ח שער הלולב שכ\"ט, פ\"א. מאמר פסיעותיו של א\"א להרח\"ו נדפס בשער מאמרי רז\"ל ב\"ר פמ\"ג (לו, א)־ חסד לאברהם בסופו (קו, ג. צ\"ל נד, ג)־ כתבים חדשים להרח\"ו (ירושלים תשמ\"ח ע' ב). הנסמן במאמרי אדה\"א ויקרא ח\"א ע' צה־ שע\"ת צד, ד הערה 26."],["1278","275","<b>והי' ביום ההוא</b>: לקו\"ת ר\"ה נח, א."],["1279","276","<b>בד\"ה לבאר ענין יוהכ\"פ</b>: לקו\"ת יוה\"כ סח, סע\"א ואילך."],["1280","277","<b>בד\"ה מה טובו</b>: לקו\"ת בלק עג, ד. עד, ב."]]],[2000450173,"היינו בחי' סוכ\"ע יומשך להיות בבחי' אלקינו, ופי' ברוך אתה היינו מהותו ועצמותו ית' שלמעלה מבחי' הוי' יומשך להיות ה' אלקינו ממש יעו\"ש. וכיוצא בזה נת' בלק\"ת פ' נצבים<sup data-n=\"1281\">278</sup> בד\"ה כי המצוה הזאת ספ\"א, שביאר תחילה איך ששם הוי' יו\"ד צמצום ה' התפשטות כו', אך הגורם להיות צמצום זה ובחי' הוי' זו שהרי כתי' אני הוי' הוא שמי<sup data-n=\"1282\">279</sup> שאין זה אלא בחי' שם שהוא לזולתו ואינו ממהות עצם הדבר כלל, אלא אנכי מי שאנכי<sup data-n=\"1283\">280</sup> היינו בחי' עצמותו ומהותו כב\"י כו', ולהיות אנכי הוי' היינו<sup data-n=\"1284\">281</sup> שלהיות נמשך להוות<sup data-n=\"1285\">282</sup> העולמות בבחי' ש' הוי' ממכ\"ע בהשתלשלות וירידות המדריגות כו', מבחי' אנכי שאינו נתפס בגדר עלמין והוא קדוש ומובדל ואינו נק' בשם כו' כ\"ז הוא מפני כי אלקיך אנכי שע\"י שאתה ישראל ממשיך בקרבך אלקות הרי בזה ממשיך ג\"כ להיות הוי' מבחי' אנכי, כי באתדל\"ת תלי' מילתא והיינו ע\"י המצות &lt;יד&gt;\nּ שהמצות הם מצות הוי', ועי\"ז גורם צמצום ביו\"ד כו', גם במ\"א נתבאר בפי' ב' שמות הוי'<sup data-n=\"1286\">283</sup> שבפסוק ראשון דק\"ש שה' אלקינו היינו מה שנמשך ש' הוי' יו\"ד צמצום ה' התפשטות כו' להיות בחי' מחשבה עלמא דאתכסיא ששם שרש נש\"י שעלו במחשבה, ואח\"כ כדי להיות בחי' דבור המהוה מלאכים<sup data-n=\"1287\">284</sup> ושאר הנבראים צ\"ל עוד צמצום והתפשטות, והו\"ע ש' הוי' הב' דהיינו ה' אחד כו'. כי החית דאחד מורה על ז' רקיעים<sup data-n=\"1288\">285</sup> וארץ וד' רומז על ד' רוחות העולם, ולפ\"ז ה' אלקינו היינו יחוד חו\"ב<sup data-n=\"1289\">286</sup> הנק' או\"א<sup data-n=\"1290\">287</sup>, כי בינה נק' מחשבה<sup data-n=\"1291\">288</sup> ומקבלת מהחכ' כו', ה' אחד היינו המדות והדבור הנק' זו\"נ<sup data-n=\"1292\">289</sup> כו', וכן משמע הפי' בד\"ה בהעלותך את הנרות, בלק\"ת פ' בהעלותך דרוש הראשון פ\"ב.\n<b>ואפ\"ל</b> עוד בענין ה' אלקינו הוי' אחד כי הנה פי' אלקינו זהו הפסיק טעמא שבין שני הויות דהיינו ענין יהי רקיע ויהי מבדיל בין מים עליונים שהוא טלא עילאה דע\"ק טלא דבדולחא שבמו\"ס, ובין מים דז\"א כדפי' בספד\"צ רפ\"ה<sup data-n=\"1293\">290</sup>, ובאשל אברהם<sup data-n=\"1294\">291</sup> בהטעמים גבי פסיק, אלא לפי שפסיק זה אינה הבדל",[["1281","278","<b>בלק\"ת פ' נצבים</b>: מה, ג (בשינויים קלים)."],["1282","279","<b>אני הוי' הוא שמי</b>: ישעי' מב, ח."],["1283","280","<b>אנכי מי שאנכי</b>: ראה תניא מהדו\"ק ספמ\"ט. לקו\"ת להאריז\"ל תולדות כז, יט בשם הזהר. אבן עזרא תולדות שם. מאמרי אדה\"ז תקס\"ב ח\"א ע' יד. פרשיות התורה ח\"א ע' רט ובהנסמן במ\"מ לשם."],["1284","281","<b>היינו</b>: בלקו\"ת: דהיינו."],["1285","282","<b>להוות</b>: שם: בחי' הוי' להוות."],["1286","283","<b>בפי' ב' שמות הוי'</b>: ראה אוה\"ת ואתחנן ס\"ע רי ואילך."],["1287","284","<b>מחשבה. . נש\"י. . דבור. . מלאכים</b>: ראה גם אגה\"ת פ\"ד. לקו\"ת בהר מא, א. תו\"ח שמות ח\"א לט, ד. וש\"נ."],["1288","285","<b>החית. . ז' רקיעים</b>: ראה שו\"ע אדה\"ז הל' ק\"ש סס\"א, ס\"ו. ראה גם לקו\"ת תזריע כג, ג."],["1289","286","<b>ה' אלקינו. . חו\"ב</b>: ראה פע\"ח שער הק\"ש ש\"ח, פ\"ז. פי\"א. סידור שער הק\"ש עד, סע\"ד."],["1290","287","<b>חו\"ב הנק' או\"א</b>: ראה תניא פ\"ג."],["1291","288","<b>בינה נק' מחשבה</b>: ראה זהר רע\"מ פינחס רכט, סע\"ב. פרדס שעה\"כ שכ\"ג, פי\"ג מערכת מחשבה."],["1292","289","<b>ה' אחד. . זו\"נ</b>: ראה גם זהר ואתחנן רסג, א. לקו\"ת שה\"ש כט, א. תו\"ח פקודי ח\"ב תנא, סע\"ד. וש\"נ."],["1293","290","<b>בספד\"צ רפ\"ה</b>: ראה זהר תרומה קעח, ב ובזהר הרקיע שם קמח, א ואילך."],["1294","291","<b>ובאשל אברהם</b>: סוד טעמים ונקודות — לר' מרדכי בר' יהודה ליב אשכנזי — פיורדא תס\"א קעב, סע\"א."]]],[2000450174,"והפסק גמור כשאר הפרסות והמסכים, וכמ\"ש בספד\"צ שם אתפריש ולא אתפריש כו'<sup data-n=\"1295\">292</sup>, ובפרד\"ס<sup data-n=\"1296\">293</sup> שער הטעמים פ\"ג כ' שהפסיק זה הוא המיחדם ומחברם, וזהו כענין אות אלף שהקו ההולך באלכסון מחבר השני יודי\"ן שהם מ\"ע ומ\"ת והיינו ע\"ק וז\"א כנ\"ל והקו מחברם שיהיו לאחדים ממש כי אלף היינו אחד כו', וכן פי' במא\"א אות אלף ס\"ד גבי אבני שיש, ואין לומר מים מים שהם מ\"ד ומ\"ן ב' גדפי אלף כי העליונה מים זכרי' והתחתונה מים נוקבין והרקיע המבדיל הכל אחדות אחת עכ\"ל וכ\"כ בפרדס<sup data-n=\"1297\">294</sup> סוף ערך מים, ולפ\"ז יובן מה שנק' אלקינו שאינו צמצום גמור כמו שם אלקים<sup data-n=\"1298\">295</sup> כי אלקינו מורה ג\"כ על הגילוי<sup data-n=\"1299\">296</sup> כו', גם סד\"ה וידעת היום<sup data-n=\"1300\">297</sup> פי' ענין כי הוי' הוא האלקים<sup data-n=\"1301\">298</sup> בשמים ממעל היינו שגם בסוכ\"ע יש ב' בחי' הוי' ואלקים, וא\"כ פי' הוי' הוא האלקים זהו ענין הוי' אלקינו שע\"י פסיק טעמא זה נמשך האור מבחי' ע\"ק בז\"א וזהו הוי' אחד, פי' אחד היינו שמתחברים ב' שמות הוי' דע\"ק וז\"א ומתייחדים ממש, ע\"י שנמשך ומתלבש האור מע\"ק בז\"א, וזהו הנק' אור הוי'<sup data-n=\"1302\">299</sup>, דהיינו האור המאיר בש' הוי' דז\"א כמ\"ש בזח\"ג נשא דק\"ל ע\"א, ובפ' אחרי דס\"ו ע\"ב בפי' בי נשבעתי<sup data-n=\"1303\">300</sup>, וכענין שארז\"ל ספ\"ג דפסחים ע\"פ ביום ההוא יהי'<sup data-n=\"1304\">301</sup> הוי' אחד שיהי' הכל הטוב והמטיב, והיינו ע\"י הארת עתיקא דלית שמאלא בהאי עתיקא<sup data-n=\"1305\">302</sup> וכשיאיר בז\"א יהי' כולו הטוב והמטיב<sup data-n=\"1306\">303</sup> וזהו ה' אחד היינו כאשר ממשיכים ע\"ק בז\"א שזהו ע\"י ה' אלקינו כו'. ובכ\"ז יובן מה שאומרים בנוסח הברכה ה' אלקינו שממשיכים מבחי' הכתר, מל' דא\"ס ע\"י הפסיק טעמא לבחי' מלך העולם היינו מל' דאצי' שז\"ע ש' הוי' שבמל', כמ\"ש בפרדס שער הטעמים שם.\n&lt;טו&gt;\nּ\n<span data-k=\"ks\"><b>קיצור.</b> סדר ההמשכה תחלה ה' אלקינו, שנש\"י מפנימיות ומלאכים מחיצוני', מו\"ד שהדבור נעשה נפרד משא\"כ המח', ונק' מנורת זהב כלי לגילוי ש' הוי' דלעילא הנמשך ע\"י תומ\"צ, וכ\"ש לגבי רם על כו', גם פי' ישראל לי ראש, ראש השנה, וא\"כ פי' בא\"י שיומשך מש' הוי' דלעילא, אלקינו הפסיק טעמא שבין ב' הויות שבפסוק ראשון דק\"ש המחברם, ועי\"ז ה' אחד, באור ה' כו'. </span>",[["1295","292","<b>אתפריש ולא אתפריש</b>: בסד\"צ: אתפרש ואתדבק לא אתפרש ממש."],["1296","293","<b>ובפרד\"ס</b>: כ\"ה בכ\"מ — ראה תניא ספמ\"ח (סח, ב) בהגהה (וראה הערות ותיקונים לשם־ מ\"מ הגהות והע\"ק לשם. מ\"מ הגהות והע\"ק לפ\"ב לא, סע\"א ד\"ה בפרד\"ס). תו\"א בראשית ה, ג. שמות קח, א (ב\"פ). לקו\"ת בחוקותי מו, ג [ובהוצאת אותיות מרובעות: בפרדס!]. האזינו עב, א. ועוד."],["1297","294","<b>בפרדס</b>: שעה\"כ שכ\"ג, פי\"ג. בלקו\"ת לג\"פ: בפרד\"ס. ראה הערה שלפנ\"ז."],["1298","295","<b>צמצום. . אלקים</b>: ראה שער היחוה\"א רפ\"ו. תו\"ח שמות ח\"א לד, ד. וש\"נ."],["1299","296","<b>אלקינו. . הגילוי</b>: באוה\"ת כאן ע' 1108 מציין לזח\"ב תרומה קנט, ב."],["1300","297","<b>סד\"ה וידעת היום</b>: לקו\"ת ואתחנן ד, ד."],["1301","298","<b>כי הוי' הוא האלקים</b>: ואתחנן ד, לט."],["1302","299","<b>אור הוי'</b>: ישעי' ב, ה. ראה גם אוה\"ת נ\"ך כרך א ע' קא."],["1303","300","<b>בי נשבעתי</b>: וירא כב, טז."],["1304","301","<b>ביום ההוא יהי'</b>: זכרי' יד, ט."],["1305","302","<b>דלית שמאלא בהאי עתיקא</b>: ראה זהר אד\"ר נשא קכט, א. ע\"ח שער עתיק שי\"ב, פ\"ב. שער הארת המוחין של\"ב, פ\"ז. הנסמן במאמרי אדה\"א דברים ח\"ג ע' תתעא. לקמן פ\"ל ד\"ה וז\"ע."],["1306","303","<b>והמטיב</b>: תוקן ע\"פ ב."]]],[2000450175,"<h3>אז ישיר כו' ומעתה יובן משנת\"ל</h3>\nד) <b>ומעתה</b><sup data-n=\"1307\">304</sup> יובן מה שנת' לעיל<sup data-n=\"1308\">305</sup> שעל המלאכים נאמר ומשם יפרד, ד' נהרות ד' מחנות שכינה מחנה מיכאל כו', ע' בלק\"ת גבי שבועות בד\"ה וספרתם לכם<sup data-n=\"1309\">306</sup> בענין וכנפיהם פרודות<sup data-n=\"1310\">307</sup>, כל אחד מדרגתו מובדלת מחבירו, שהוא לפי שמקבלים מבחי' הדבור, אשר ה' מוצאות הפה ג\"כ כל אחד מובדל מחבירו, ובזח\"ג ואתחנן דרס\"ו סע\"א ההוא<sup data-n=\"1311\">308</sup> נהרא דנגיד ונפיק אשקי לכל גינתא כו' ומתמן אתזנו עילאין ותתאין כמד\"א ומשם יפרד, וע\"ש במק\"מ והרמ\"ז, ובזח\"א ויצא דקנ\"ח ע\"א גבי מכאן ולתתא אקרון הרי בתר דכתיב ומשם יפרד והיו<sup data-n=\"1312\">309</sup> לארבעה ראשים טורי דפרודא, וע' עוד מענין הרי בתר טורי דפרודא בזהר בראשית דך\"ט ע\"ב, ובמא\"א אות ה' ס\"ז הרי בתר נק' ההיכלות טורי דפרודא כי בבריאה לאו איהו וגרמוהי חד בהון עכ\"ל.\n<b>ורבינו</b> אדמו\"ר ז\"ל<sup data-n=\"1313\">310</sup> בד\"ה היושבת בגנים<sup data-n=\"1314\">311</sup> פי' הרי בתר טורי דפרודא הם בק\"נ, והיינו שמבחי' ד' מחנות שכינה בהשתלשלות וירידות המדריגות מדריגה אחר מדריגה נמשך ג\"כ בק\"נ, וכמו שנה\"ב נמשכת מפני שור<sup data-n=\"1315\">312</sup>, וע' בזהר בשלח דמ\"ט ע\"א אעבר וסליק לההוא<sup data-n=\"1316\">313</sup> אתר קדישא עילאה, והיינו משום ששרש יניקתם מש' ב\"ן כו', אכן ע\"י נשמות ששרשם מש' מ\"ה דז\"א, הנה בהם וע\"י דוקא נמשך הביטול למטה לברר ק\"נ, וכמ\"ש מי כעמך כישראל<sup data-n=\"1317\">314</sup> גוי אחד בארץ כי הם עושים וממשיכים בחי' אחד גם בארץ, כמ\"ש בת\"א פ' וישב<sup data-n=\"1318\">315</sup> בד\"ה והנה אנחנו מאלמים אלומים, ויובן זה עוד ע\"פ מ\"ש בזהר פ' ויצא דקנ\"ה ע\"א ר' חזקי' אמר אי הכי הא אתמר כל מה דאוליד עלמא תתאה פרודא איהי<sup data-n=\"1319\">316</sup>",[["1307","304","<b>ומעתה</b>: ברשימת המאמרים שמופיע בריש הבוך 1089 נרשם כאן מאמר (ה' מההמשך והוא) ד\"ה: אז ישיר משה ובנ\"י — אחרון ש\"פ (הכולל פרקים י' — י\"א). היינו שבעת אמירת הדרוש היתה פתיחא זו, ולע\"ע אין ידוע אם גם פתיחה זו נרשמה בפ\"ע ע\"י כ\"ק אדמו\"ר מהר\"ש. וראה לקמן (בחלק ההנחות) התחלת הנחה מדרוש זה מכ\"ק אדמו\"ר מהורש\"ב.\nלמאמר זה לפ\"י — ראה אוה\"ת בראשית כאן ע' 1108 פ\"ג־ ע' תקנה פ\"ג הב' והוא לשונו בשינויים והוספות. הקיצור אוה\"ת שם ע' תקנו בשינוי קל. לפי\"א — ראה תו\"א בראשית כאן ו, ב. אוה\"ת שם ע' תקנו — תקנז בשינוי קל. הקיצור שם ע' 1114 בשינוי קל."],["1308","305","<b>שנת' לעיל</b>: פ\"ב."],["1309","306","<b>בלק\"ת. . וספרתם לכם</b>: במדבר י, א."],["1310","307","<b>וכנפיהם פרודות</b>: יחזקאל א, יא."],["1311","308","<b>ההוא</b>: כגי' ס\"א בזהר שם. ותיבת ת\"ח — בזהר שם — מיותרת. וכ\"ה במק\"מ וברמ\"ז שם."],["1312","309","<b>והיו</b>: ב: והי'."],["1313","310","<b>ורבינו אדמו\"ר ז\"ל</b>: ראה אוה\"ת כאן ע' תקנה פ\"ג הב'."],["1314","311","<b>בד\"ה היושבת בגנים</b>: בהגהת הצ\"צ במאמרי אדה\"ז תקס\"ג ח\"ב ע' תשלו מזכיר [וכן צ\"ל שם]: ”ע' היושבת בגנים דברדיצוב\". דרוש בפתיחה זו נמצא בבוך 269 ע' קנ. ובבוך 1097 ע' עא. והוא נוסח אחר מד\"ה ברח דודי במאמרי אדה\"ז תק\"ע ע' נד [והמובא בפנים הכוונה להנחה הנ\"ל, וראה גם מאמרי אדה\"ז שם ע' נט]. אוה\"ת שה\"ש ח\"ב ע' תשפד. ע' תשפב. ע' תשע. כרך ג' ע' א'יז. ע' א'כב."],["1315","312","<b>שנה\"ב נמשכת מפני שור</b>: ראה סידור שער האלול רל, א. ש\"א יז, א הערה 11. סה\"מ תרכ\"ט ע' קכז. וש\"נ."],["1316","313","<b>לההוא</b>: וכ\"ה גם בלקו\"ת לג\"פ ואוה\"ת. בזהר: ההוא."],["1317","314","<b>מי כעמך כישראל</b>: שמו\"ב ז, כג. באוה\"ת ובלקו\"ת לג\"פ כאן: ישראל — דהי\"א יז, כא. ובהשמטות ותיקונים בלקו\"ת לג\"פ שם כבפנים."],["1318","315","<b>בת\"א פ' וישב</b>: כז, סע\"ד."],["1319","316","<b>איהי</b>: בזהר־ לקו\"ת לג\"פ ואוה\"ת: איהו."]]],[2000450176,"דהכתיב<sup data-n=\"1320\">317</sup> ומשם יפרד, מה תימא ביוסף ובנימין כו', אבל ת\"ח רזא דמלה בכל זמנא צדיק מעלמא תתאה נפק<sup data-n=\"1321\">318</sup> ועייל בי' עייל ומניה נפיק עכ\"ל, ואינו מובן עדיין התירוץ כיון שנמשכו מעלמא תתאה שהיא מל' אמאי אינן בכלל ומשם יפרד כמו ד' מחנות שכינה, ובספר זהרי חמה פי' כיון שע\"י מ\"ן דבנימין ומ\"ד דיוסף מתייחדת עם<sup data-n=\"1322\">319</sup> הת\"ת, וכנודע בענין אלה תולדות יעקב יוסף<sup data-n=\"1323\">320</sup>, ולכן יוסף ובנימין אינם בכלל ומשם יפרד, וכן מצאתי בסה\"מ סי' י\"ז<sup data-n=\"1324\">321</sup> בשם הע\"ח וז\"ל והסוד כי הלא תחלה הנקבה משפעת בעת הזיווג בת\"ת מן<sup data-n=\"1325\">322</sup> בסוד אור חוזר בסוד יסוד אחד &lt;טז&gt;\nּ (ולכן המזבח הי' בחלקו של טורף<sup data-n=\"1326\">323</sup> שהוא בנימין, וכמ\"ש בזח\"א בהשמטות סי' ך\"ה ד\"ט סע\"א<sup data-n=\"1327\">324</sup> וז\"ל בגין כך תנינן היסוד הי' מהלך ע\"פ כל הצפון וע\"פ כל המערב ואוכל בדרום אמה אחת<sup data-n=\"1328\">325</sup>, בגין דחולקא<sup data-n=\"1329\">326</sup> דבנימין הוה<sup data-n=\"1330\">327</sup> בג\"כ אית לי' יסוד, דהא הוא שליט הוה לגבי ההוא צדיק יסוד עולם, אבל בחלקו<sup data-n=\"1331\">328</sup> דיהודה דאיהו מזרח לא ה\"ל יסוד דהא איהו רחקיה מיניה כו', ור\"ל שעיקר צדיק יסוד עולם הוא יוסף<sup data-n=\"1332\">329</sup> יסוד ז\"א<sup data-n=\"1333\">330</sup> המשפיע מ\"ד אלא שבנימין מכוין כנגדו דהיינו שהוא המעלה מ\"ן בחי' יסוד דנוק'<sup data-n=\"1334\">331</sup>, וכמ\"ש מענין פי' יסודות דזו\"נ בדרוש הנותן לשכוי בינה<sup data-n=\"1335\">332</sup> ששניהם בחי' ביטול עצמותו, ההתקשרות להשפיע, וכן ההתקשרות לקבל<sup data-n=\"1336\">333</sup>, וזה הי' טענת יהודה עם יוסף בענין ויגש אליו יהודה<sup data-n=\"1337\">334</sup> כו' כי אחיו מת<sup data-n=\"1338\">335</sup> ויותר הוא לבדו<sup data-n=\"1339\">336</sup> שהוא בנימין",[["1320","317","<b>דהכתיב</b>: בזהר: דהא כתיב. באוה\"ת: דכתיב. בלקו\"ת לג\"פ: כבפנים."],["1321","318","<b>נפק</b>: ב ובלקו\"ת לג\"פ ואוה\"ת: נפיק. בזהר מהדורת קאפוסט תקס\"ט: נפק."],["1322","319","<b>עם</b>: בלקו\"ת לג\"פ ואוה\"ת כאן ע' 1110: כנס\"י עם."],["1323","320","<b>אלה תולדות יעקב יוסף</b>: ראה גם לעיל המשך אם כסף תלוה פ\"ב ד\"ה ועוי\"ל. ובהנסמן שם. תו\"ח תצוה ח\"ב שנה, ד. וש\"נ."],["1324","321","<b>סי' י\"ז</b>: וכ\"ה גם בלקו\"ת לג\"פ ואוה\"ת כאן. ראה שם סי' ז' (ד, א)."],["1325","322","<b>מן</b>: שם ובלקו\"ת לג\"פ ואוה\"ת: מ\"ן."],["1326","323","<b>המזבח הי' בחלקו של טורף</b>: ראה זבחים נג, ב."],["1327","324","<b>ד\"ט סע\"א</b>: במהדורת קאפוסט תקס\"ט. לפנינו רנט, א."],["1328","325","<b>הצפון. . אחת</b>: וכ\"ה גם בלקו\"ת לג\"פ ואוה\"ת [ושם ניתוסף: ובמזרח אמה אחת]. בזהר: המערב ועל פני כל הצפון אוכל במזרח חצי אמה ובדרום חצי אמה. וראה ניצוצי זהר שם."],["1329","326","<b>דחולקא</b>: בזהר ובלקו\"ת לג\"פ ואוה\"ת: דחולקי'."],["1330","327","<b>הוה</b>: וכ\"ה גם בלקו\"ת לג\"פ ואוה\"ת. ובזהר: הוה מערב."],["1331","328","<b>בחלקו</b>: שם: בחולקי'."],["1332","329","<b>צדיק יסוד עולם הוא יוסף </b>: ראה גם לעיל מאמר ד\"ה אם כסף תלוה על יד הערה 31."],["1333","330","<b>יוסף יסוד ז\"א</b>: ראה ע\"ח שער הצלם שכ\"ו, פ\"ג. ביאוה\"ז ויחי כט, ב. ד. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקיז ובהנסמן במ\"מ לשם."],["1334","331","<b>שבנימין. . יסוד דנוק'</b>: ראה זהר ויצא קנג, ב. מק\"מ שם. מאמרי אדה\"ז תקס\"ב כרך ב ע' שלה ואילך. אוה\"ת בהר כרך ב ע' תרב. מקץ כרך ו ע' 2206 ואילך. סה\"מ תרכ\"ח ע' מד ואילך."],["1335","332","<b>בדרוש הנותן לשכוי בינה</b>: מאמרי אדה\"ז תקס\"ב כרך ב ע' שצה. אוה\"ת מסעי ס\"ע א'ת ואילך."],["1336","333","<b>ההתקשרות להשפיע. . לקבל</b>: ראה סידור שער התפלה כו, ב."],["1337","334","<b>ויגש אליו יהודה</b>: ויגש מד, יח."],["1338","335","<b>כי אחיו מת</b>: לשון הכתוב מקץ מב, לח. ראה ויגש מד, כ."],["1339","336","<b>ויותר הוא לבדו</b>: ויגש שם. ראה זהר ויצא קנג, סע\"ב ואילך. ראה גם מאמרי אדה\"ז־ אוה\"ת מקץ וסה\"מ שבהערה 331."]]],[2000450177,"משמש במקום היסוד כו' ולכן היסוד של המזבח הי' בחלקו של בנימין דוקא, ועמ\"ש מענין העלאת מ\"ן דנוק' שהוא מה שמבררת מעולם התהו בביאור ע\"פ אז ישיר<sup data-n=\"1340\">337</sup> ישראל עלי באר כו'), וע\"כ<sup data-n=\"1341\">338</sup> התחיל ואמר צדיק מעלמא תתאה נפיק בסוד אור חוזר, ואח\"כ בי'<sup data-n=\"1342\">339</sup> עייל בסוד אור ישר מ\"ד, הרי יוסף עם היותו בעלמא דנוק' עכ\"ז עלמא דדכורא הוא ולא בעלמא דפרודא תחת המ' כו' עכ\"ל, וכן בבנימין, ועיקר הטעם היינו מפני שע\"י יוסף ובנימין נעשה היחוד עליון דמ\"ה וב\"ן שיומשך הביטול עליון דאצי' דמ\"ה גם למטה בב\"ן, וז\"ע שהמ\"ד מברר הב\"ן כמ\"ש סד\"ה והנה אנחנו מאלמים אלומים<sup data-n=\"1343\">340</sup>, א\"כ ממילא זהו היפך בחי' ומשם יפרד כ\"א אדרבה למהוי אחד באחד<sup data-n=\"1344\">341</sup> כו', וכמ\"ש מזה בד\"ה בן פרת יוסף<sup data-n=\"1345\">342</sup>, אשר ענין יוסף הוא מ\"ש יוסף ה' לי בן אחר<sup data-n=\"1346\">343</sup>, דהיינו שמבחי' אחר שהוא מה שנפל בשה\"כ מעולם התהו בק\"נ, נכלל ע\"י הבירור בבחי' בן היינו מה שם בנו<sup data-n=\"1347\">344</sup>, שם מ\"ה דאצי', והיינו ע\"י מ\"ן דבנימין ומ\"ד דיוסף, הרי עי\"ז נתקן עולם הפירוד ליכלל ביחוד העליון כו', ומכ\"ז מובן ענין הנ\"ל מה שבנוסח הברכה אומרים הוי' אלקינו שנמשך האור בנש\"י, ועי\"ז אח\"כ נמשך בהעולמות, והוא שיתוקן עולם הפירוד כו', והיינו שנש\"י ממשיכים בחי' מדריגה עליונה יותר שבבחי' ונהר יוצא מעדן<sup data-n=\"1348\">345</sup> ממה שנמשך ע\"י המלאכים, כמ\"ש בת\"א פ' יתרו בביאור ע\"פ זכור ושמור בדבור אחד נאמרו<sup data-n=\"1349\">346</sup>, שהמלאכים ממשיכים יחוד חיצוני' דאו\"א, ונק' ג\"כ ונהר יוצא מעדן ומ\"מ ומשם יפרד, אבל נש\"י ממשיכים בחי' יחוד פנימיות חו\"ב, וב' בחי' אלו הם ה' של שם ויו\"ד של שם, ועמ\"ש מזה בביאור ע\"פ ויצום<sup data-n=\"1350\">347</sup> אל בנ\"י ואל פרעה כו', וגם כמ\"ש בלק\"ת פ' בחקתי<sup data-n=\"1351\">348</sup> בענין פי' בעבר הנהר ישבו אבותיכם, ומ\"ש ע\"פ ששים המה מלכות<sup data-n=\"1352\">349</sup> כו' אחת היא יונתי ע\"ש, וצ\"ע בהרמ\"ז ר\"פ עקב בענין הברכות, גם ע\"ד מ\"ש בד\"ה ואלה המשפטים<sup data-n=\"1353\">350</sup> בענין כי תקנה עבד עברי<sup data-n=\"1354\">351</sup>, שאף הנשמות דבי\"ע שהם בחי' ומשם יפרד מ\"מ שרשם למעלה כו' &lt;יז&gt;\nּ גם למעלה מבחי' נהר היוצא מעדן ולכן נק' עברי ע\"ש בעבר הנהר כו' ע\"ש, רק שצריך קנין והמשכה מהעלם לגילוי, ועוד דהא פי' בלק\"ת בד\"ה וספרתם לכם דגבי חה\"ש דגם במלאכים רק וכנפיהם פרודות, משא\"כ ופניהם הפנימיות",[["1340","337","<b>ע\"פ אז ישיר</b>: לקו\"ת חוקת סג, סע\"ב ואילך."],["1341","338","<b>וע\"כ</b>: וכ\"ה גם בלקו\"ת לג\"פ ואוה\"ת כאן. בהדרת מלך שם: ולכן."],["1342","339","<b>בי'</b>: וכ\"ה גם בלקו\"ת לג\"פ ואוה\"ת. שם: ליתא."],["1343","340","<b>סד\"ה והנה. . אלומים</b>: תו\"א וישב כח, ג."],["1344","341","<b>למהוי אחד באחד</b>: זהר תרומה קלה, סע\"א."],["1345","342","<b>בד\"ה בן פרת יוסף</b>: אוה\"ת ויחי שפו סע\"א ואילך."],["1346","343","<b>יוסף ה' לי בן אחר</b>: ויצא ל, כד."],["1347","344","<b>מה שם בנו</b>: משלי ל, ד."],["1348","345","<b>ונהר יוצא מעדן</b>: בראשית ב, י."],["1349","346","<b>בת\"א. . נאמרו</b>: ראה שם עא, א. עב, ג. ד."],["1350","347","<b>בביאור ע\"פ ויצום</b>: ראה אור התורה וארא ע' קמו ואילך. ע' רי."],["1351","348","<b>בלק\"ת פ' בחקתי</b>: מה, א. מז, א."],["1352","349","<b>ששים המה מלכות</b>: לקו\"ת שה\"ש לח, ד ואילך. לט, ב. ד ואילך."],["1353","350","<b>בד\"ה ואלה המשפטים</b>: תו\"א משפטים עה, ג. עו, ג."],["1354","351","<b>כי תקנה עבד עברי</b>: משפטים כא, ב."]]],[2000450178,"שלהם אינם בבחי' פירוד, א\"כ כ\"ש נש\"י שהם מבחי' פנימיות ממש, וע' בבה\"ז פ' בלק<sup data-n=\"1355\">352</sup> על המאמר שם דק\"צ ע\"ב ע\"פ ברכו ה' מלאכיו<sup data-n=\"1356\">353</sup>, ע\"כ הם מתקנים בחי' ומשם יפרד כו'.\n<span data-k=\"ks\"><b>קיצור.</b> טורי דפרודא הם ק\"נ ושרש שרשם מש' ב\"ן מ' ע\"ד עה\"ד חטה היתה<sup data-n=\"1357\">354</sup>, ונש\"י שרשם מש' מ\"ה, ולכן בשבטים לא הי' אותיו' ח\"ט<sup data-n=\"1358\">355</sup>, ולכן יוסף ובנימין אף שנולדו מרחל שהיא מ' אינם בכלל ומשם יפרד, כי אדרבה בהם וע\"י נעשה יחוד מ\"ה וב\"ן והם עצמם הכלי ליחוד זה, וא\"כ הענין שהנשמות ממשיכות בחי' העליונה יותר בנהר היוצא מעדן ועמ\"ש בענין ומעיין מבית ה' יצא<sup data-n=\"1359\">356</sup>, וז\"ע מה שבנוסח הברכה אומרים ה' אלקינו ואח\"כ מלך העולם.</span>\nיא) <b>וזהו</b><sup data-n=\"1360\">*357</sup> שארז\"ל פ\"ק דברכות דף ד' ע\"ב מיכאל באחת, ולא אמרו איזה שיעור על נשמות ישראל לפי שענין טיסה שטסים את העולם לא שייך לגבי נשמות כלל שהעולם ומלואה אינם תופסים מקום כלל נגדם, משא\"כ לגבי המלאכים תופס העולם איזה מקום, אלא שמיכאל די לו בטיסה א' וגבריאל בשתים כו' ואלי' בארבע עם גופו שהי' תחלה גשמי ונהפך<sup data-n=\"1361\">358</sup> כו'<sup data-n=\"1362\">357</sup>, וכה\"ג נת' בלק\"ת ס\"פ הברכה בד\"ה מזמור שיר חנוכת הבית דרוש הראשון פ\"א כי הנה מצינו שהמלאכים אומרים שירה כו', ובאמת גם הנשמות אומרים שירה<sup data-n=\"1363\">359</sup> כו' אלא שלא מצינו מפורש כן במקרא, והטעם מפני ששירת המלאכים נשמעת באזני הנביא<sup data-n=\"1364\">360</sup> כו', והיינו מפני<sup data-n=\"1365\">362</sup> שיש להם גופים<sup data-n=\"1366\">361</sup> כו' מיסוד הרוח הפשוט, ומיסוד האש הפשוט, ולכן המלאכים תופסים מקום שיש מלאך גדול מהלך ת\"ק שנה<sup data-n=\"1367\">363</sup>, ויש",[["1355","352","<b>בבה\"ז פ' בלק</b>: צט, ג."],["1356","353","<b>ברכו ה' מלאכיו</b>: תהלים קג, כ."],["1357","354","<b>עה\"ד חטה היתה</b>: כ\"ה גם בלקו\"ת לג\"פ ואוה\"ת כאן — תיבות אלו לא הובאו לעיל בפנים — ברכות מ, סע\"א. ראה גם לקו\"ת צו יז, ד. מאמרי אדה\"א במדבר ח\"ב ע' תיח."],["1358","355","<b>ולכן בשבטים לא הי' אותיות ח\"ט</b>: כ\"ה גם בלקו\"ת לג\"פ ואוה\"ת כאן — תיבות אלו לא הובאו לעיל בפנים — ראה יומא עג, ב. זהר בהקדמה ג, א. תרומה קנב, א. בלק קפח, ב. לקו\"ת אמור לו, ג ואילך. סה\"מ תרכ\"ז ע' שלח וע' שלט. תרכ\"ט ס\"ע רמג ואילך."],["1359","356","<b>ומעיין מבית ה' יצא</b>: יואל ד, יח. ראה לקו\"ת שה\"ש לט, א ואילך."],["1360","*357","<b>וזהו</b>: להבא לקמן ראה תו\"א בראשית כאן ו, ב. אוה\"ת שם ע' תקנו — תקנז בשינוי קל. הקיצור שם ע' 1114 בשינוי קל."],["1361","358","<b>ואלי'. . גופו שהי' תחילה גשמי ונהפך</b>: ראה מל\"ב ב, יא. פרדס שער היכלות שכ\"ד, פי\"ג. פי\"ד. מאמרי אדה\"א נ\"ך ע' רלא. וש\"נ. סה\"מ תרל\"ב ח\"א ע' קיא. וש\"נ. תו\"ח בשלח ח\"א קצו, ג. וש\"נ."],["1362","357","<b>וזהו שארז\"ל. . ונהפך כו'</b>: לשון התו\"א כאן ו, ב. הובא לעיל פ\"ב."],["1363","359","<b>שהמלאכים. . הנשמות אומרים שירה</b>: ראה גם הנסמן במ\"מ ללקו\"ת ברכה שם."],["1364","360","<b>ששירת המלאכים נשמעת באזני הנביא</b>: ראה לקו\"ת שם."],["1365","362","<b>מפני</b>: וכ\"ה גם באוה\"ת כאן. ובלקו\"ת: לפי. בלקו\"ת לג\"פ: ליתא. והוסיפה הר\"ש סופר עה\"ג."],["1366","361","<b>המלאכים. . גופים</b>: ראה גם לעיל המשך כי תשא פ\"ה על יד הערה 111. וש\"נ."],["1367","363","<b>מלאך. . ת\"ק שנה</b>: ראה חגיגה יג, ב. מאמרי אדה\"א קונטרסים ע' רלב. וש\"נ. סה\"מ תרכ\"ז ע' רסב ובהערה לשם."]]],[2000450179,"מלאך בשליש העולם<sup data-n=\"1368\">364</sup>, והיינו שהגוף<sup data-n=\"1369\">365</sup> שלהם גדול כ\"כ כו', משא\"כ שירת הנשמות אינן נשמעות לפי שאינם בבחי' התלבשות הגוף<sup data-n=\"1370\">366</sup> כלל כו' עכ\"ל יעו\"ש. וכן נתבאר עוד בסידור שער הק\"ש בד\"ה להבין ההפרש בין ק\"ש לשמו\"ע<sup data-n=\"1371\">367</sup>, כי כל מלאך יש לו חומר וצורה כמו נפש וגוף, וגם נת' ששרש התהוותן הוא מבחי' כלים דזו\"נ דאצי' שנעשים נשמה לע\"ס דבי\"ע, יו\"ד כלים הפנימי' נעשים נשמה לע\"ס דבריאה והתיכונים לע\"ס דיצירה, ויו\"ד כלים החיצוני' נעשים נשמה לע\"ס דעשייה, ונז' ג\"כ באגה\"ק סי' ה' בד\"ה ויעש דוד שם בשם האריז\"ל שבחי' חיצוני' הכלים דמ' דאצי' המרומזות בה' של ש' הוי' ירדו<sup data-n=\"1372\">368</sup> ונעשה<sup data-n=\"1373\">369</sup> נשמה לעולם העשייה כו' ע\"ש. ולכן מלאכים דבריאה גבוהים ממלאכים דיצי' לפי ששרשם מכלים הפנימיים, ע\"ש בסידור. ומצד שבהכלים דאצי' יש הארת האור ע\"כ מזה נמשך שיש בהמלאך נשמה וגוף ששרשן מאורות וכלים, אמנם נראה לבאר הענין &lt;יח&gt;\nּ עפמ\"ש במ\"א<sup data-n=\"1374\">370</sup> ע\"פ מאה\"ז ר\"פ ויצא דקמ\"ח ע\"פ קומה ה' למנוחתיך<sup data-n=\"1375\">371</sup>, אפי' במאנין דילי לא אשתמש אלא במאני' דילך, פי' מאנין דילי הם כלים דאצי' שנק' מאנין דילי כי גם הכלים דאצי' הם אלקות דאיהו וגרמוהי חד, והם נעשים נשמה לע\"ס דבי\"ע, ומאנין דילך הם כלים דע\"ס דבי\"ע שאינן אלקות רק נבראים ממש, וכן אפי' האורות נפש רוח דבי\"ע הם נבראים, רק הנשמה דע\"ס דבי\"ע שנמשכה מכלים דאצי' הוא<sup data-n=\"1376\">372</sup> אלקות והנה המלאך נברא ע\"י ע\"ס דבי\"ע, ונשמתו י\"ל נמשך מהנשמה דע\"ס דבי\"ע שהוא<sup data-n=\"1377\">373</sup> אלקות וגופו נמשך מהכלים דבי\"ע שהן נבראים, וע\"כ הגוף שלו תופס איזהו מקום כו', אכן נש\"י שנאמר בה טהורה היא<sup data-n=\"1378\">374</sup> שנמשכה מאצי', רק אח\"כ אתה בראת שנמשכה דרך בי\"ע כו' ע\"כ הם הם למעלה ממדריגת גוף כו'.\n<b>והנה</b> שרש בחי' מקום וזמן נמשך מבחי' מלכותו ית' כמ\"ש בסש\"ב ח\"ב פ\"ז שהוא שם אדנות, אבל ש' הוי' הוא למעלה מבחי' זמן ולמעלה מבחי' מקום כו' ע\"ש. ומבואר באגה\"ת פ\"ד, בענין פי' כי חלק הוי' עמו<sup data-n=\"1379\">375</sup> שהמלאכים שרש התהוותן מבחי' הדבור עליון כנ\"ל שהוא בחי' מל', ונק' ש' אלקים וש' אד'<sup data-n=\"1380\">376</sup>,",[["1368","364","<b>מלאך בשליש העולם</b>: ראה ב\"ר פס\"ח, יב. חולין צא, ב. מורה נבוכים ח\"ב, פ\"י. לקו\"ת נצבים עד, סע\"ד ובהנסמן במ\"מ לשם. מאמרי אדה\"ז תקס\"ו ע' ק ”שהוא ק\"ס שנה\". סידור שער החנוכה רעו, א ”קס\"ו וב\"ש שנה\"."],["1369","365","<b>העולם והיינו שהגוף</b>: כ\"ה גם בלקו\"ת לג\"פ ואוה\"ת. ובלקו\"ת העולם כו' והיינו הגוף."],["1370","366","<b>הגוף</b>: ובאוה\"ת: בגוף. ובהשמטות ותיקונים בלקו\"ת לג\"פ כבפנים."],["1371","367","<b>בסידור. . לשמו\"ע</b>: עג, ג ואילך."],["1372","368","<b>הוי' ירדו</b>: וכ\"ה גם בלקו\"ת לג\"פ ואוה\"ת כאן. ובאגה\"ק: הוי' ב\"ה הם ירדו."],["1373","369","<b>ונעשה</b>: באגה\"ק ובאוה\"ת: ונעשו. ובלקו\"ת לג\"פ: כבפנים."],["1374","370","<b>עפמ\"ש במ\"א</b>: ראה ביאוה\"ז ויצא קלז, ד ואילך. אוה\"ת ויצא ח\"א ע' 364."],["1375","371","<b>קומה ה' למנוחתיך</b>: תהלים קלב, ח."],["1376","372","<b>הוא</b>: באוה\"ת כאן: היא. ובלקו\"ת לג\"פ כבפנים."],["1377","373","<b>שהוא</b>: שם: שהיא."],["1378","374","<b>טהורה היא</b>: ברכת אלקי נשמה. ראה לקו\"ת ראה כז, א ובהנסמן במ\"מ לשם. מאמרי אדה\"א הנחות תקע\"ז ע' רב. וש\"נ."],["1379","375","<b>כי חלק הוי' עמו</b>: האזינו לב, ט."],["1380","376","<b>שהמלאכים. . ושם אד'</b>: כ\"ה גם באוה\"ת כאן ע' 1112."]]],[2000450180,"אבל נשמות נמשכים מפנימיות החיות שהוא ש' הוי', וזהו כי חלק הוי' עמו כו' ועמ\"ש מזה בת\"א פ' מקץ בד\"ה רני ושמחי, דרוש השני, ובהביאור<sup data-n=\"1381\">377</sup> גבי ולכן עבודת המלאכים ג\"כ ברינה שהרי נמשכים ג\"כ<sup data-n=\"1382\">378</sup> מבחי' מל', ומל' דבריאה הוא מקור וחיות המלאכים דבריאה ומל' דיצי' הוא מקור ושרש המלאכים דיצי'<sup data-n=\"1383\">379</sup> כו'<sup data-n=\"1384\">380</sup>, אך המלאכים אין להם אלא בחי' רינה לפי שאין מקורם אלא מבחי' מל' בלבד, משא\"כ נש\"י הם כלולי' מכל הפרצופים, נעשה אדם בצלמינו<sup data-n=\"1385\">381</sup> או\"א וזו\"נ<sup data-n=\"1386\">382</sup>, ולכן יש להם ג\"כ בחי' שמחה, היא בחי' המשכה מלמעלה למטה בתומ\"צ רמ\"ח איברין דמלכא ט\"ס דז\"א כו' עכ\"ל. ועיין במק\"מ פ' בשלח דנ\"ה<sup data-n=\"1387\">383</sup> מענין שרש האדם, ומזה מובן משנת\"ל דלגבי המלאכים תופס העולם איזה מקום, והיינו לפי ששרש המלאכים הוא מבחי' מל' בלבד אשר משם שרש הזמן ומקום כנ\"ל, וכמ\"ש בד\"ה רני ושמחי הנ\"ל<sup data-n=\"1388\">384</sup> בפי' מלכותך מל' כל עולמים<sup data-n=\"1389\">385</sup> וממשלתך בכל דור ודור, עולמים הם<sup data-n=\"1390\">386</sup> בחי' מקום ודור ודור הם בחי' זמן הכל נמשך מבחי' מלכותך שהרי הזמן והמקום הם נבראים ומחודשים מאין ליש שקודם בריאת העולם לא הי' בחי' זמן ומקום כלל ולא היו יכולים להיות נבראים שהם בעלי גבול בבחי' זמן ומקום, אלא ע\"י בחי' מל' ית' שבה שייך בחי' זמן מלך מלך וימלוך<sup data-n=\"1391\">387</sup> כו', משא\"כ באור א\"ס ב\"ה עצמו שכשמו כן הוא אין לו סוף כו' עכ\"ל. ולכן כיון ששרש הזמן ומקום אינו אלא מבחי' המל' לבד וגם המלאכים שרשם מבחי' המל', ע\"כ העולם תופס איזה מקום לגבי המלאכים, משא\"כ לגבי הנשמות ששרשם מש' הוי' ממש שלמעלה מבחי' המל' אשר הוא למעלה מעלה מבחי' מקום וזמן ע\"כ העולם ומלואה אינו תופס מקום כלל &lt;יט&gt;\nּ אצלם כו', כיון שאינו בגדר מקום כלל, וכ\"כ הרמב\"ן בשער הגמול<sup data-n=\"1392\">388</sup> הובא בהרמב\"ם ה' תשובה פ\"ח<sup data-n=\"1393\">389</sup> בהפירוש, וז\"ל אלא כך הוא<sup data-n=\"1394\">390</sup> קבלת רבותינו ז\"ל, הקב\"ה ברא נפשות הצדיקים<sup data-n=\"1395\">391</sup> והן בלי<sup data-n=\"1396\">392</sup> ספק רוח זכה ודקה ביותר שאינה גוף נגבלת<sup data-n=\"1397\">393</sup> ונקשרת<sup data-n=\"1398\">394</sup> בשום מקום<sup data-n=\"1399\">395</sup> כו', והכתוב",[["1381","377","<b>בת\"א פ' מקץ. . ובהביאור</b>: לז, ד."],["1382","378","<b>ג\"כ</b>: בתו\"א שם־ לקו\"ת לג\"פ ואוה\"ת כאן: ליתא."],["1383","379","<b>הוא. . דיצי'</b>: כ\"ה גם בלקו\"ת לג\"פ ואוה\"ת. ובתו\"א שם: ליתא."],["1384","380","<b>כו'</b>: ב: כנ\"ל. בתו\"א וכו'. בלקו\"ת לג\"פ ואוה\"ת כבפנים."],["1385","381","<b>נעשה אדם בצלמינו</b>: בראשית א, כו. בתו\"א באים תיבות אלו בסוגריים."],["1386","382","<b>וזו\"נ</b>: בתו\"א: זו\"נ. בלקו\"ת לג\"פ: כבפנים. ובאוה\"ת כאן: ליתא."],["1387","383","<b>דנ\"ה</b>: ע\"א."],["1388","384","<b>בד\"ה רני ושמחי הנ\"ל</b>: תו\"א מקץ לז, א."],["1389","385","<b>מלכותך מל' כל עולמים</b>: תהלים קמה, יג. ראה גם לקו\"ת אחרי כז, ב. בהעלותך ל, א."],["1390","386","<b>הם</b>: כ\"ה גם בלקו\"ת לג\"פ ואוה\"ת. ובתו\"א: הוא."],["1391","387","<b>וימלוך</b>: בתו\"א: ימלוך. ובלקו\"ת לג\"פ ואוה\"ת כבפנים."],["1392","388","<b>בשער הגמול</b>: כתבי הרמב\"ן ח\"ב ירושלים תשכ\"ד ע' רפה."],["1393","389","<b>בהרמב\"ם ה' תשובה פ\"ח</b>: ה\"א."],["1394","390","<b>הוא</b>: שם ובלקו\"ת לג\"פ ואוה\"ת: היא."],["1395","391","<b>נפשות הצדיקים</b>: כ\"ה גם בלקו\"ת לג\"פ ואוה\"ת כאן ר\"ע תקנז. בהפירוש: נפשות צדיקים. בשער הגמול: נפשותיהם של צדיקים."],["1396","392","<b>והן בלי</b>: בשער הגמול: והיא בלא."],["1397","393","<b>שאינה גוף נגבלת</b>: בשער הגמול: אינה גוף ולא נגבלת."],["1398","394","<b>ונקשרת</b>: בהנ\"ל: ונגדרת. ובשער הגמול: ולא נגדרת."],["1399","395","<b>בשום מקום</b>: בשער הגמול: במקום."]]],[2000450181,"מעיד בו<sup data-n=\"1400\">396</sup> ויפח באפיו נשמת חיים<sup data-n=\"1401\">397</sup> יאמר<sup data-n=\"1402\">398</sup> כי מנשמת<sup data-n=\"1403\">399</sup> אל ניתנה, לא מהשתלשלות הסיבות<sup data-n=\"1404\">400</sup> כו', וא\"ת האיך נגבלת הנפש במקום הנק' גיהנם<sup data-n=\"1405\">401</sup> י\"ל כמו שאנו יודעים שנפש כל אדם שוכנת בו ומחוברת בגופו כו', ועד\"ז צ\"ל ענין הנשמות שבג\"ע התחתון שהוא בגדר מקום קצת, זהו ע\"י שהנשמה מתלבשת בלבוש רוחני מה שהוא בגדר מקום קצת כענין גופות המלאכים כו' ונק' חלוקא דרבנן<sup data-n=\"1406\">402</sup> כו', אבל ג\"ע העליון אינו בגדר מקום כלל כו'.\n<span data-k=\"ks\"><b>קיצור.</b> ולכן אמרו מיכאל באחת כו', משא\"כ לגבי הנשמות אין העולם תופס מקום כלל, ולכן ג\"כ בשירת המלאכים נאמר כקול מים רבים<sup data-n=\"1407\">403</sup>, משא\"כ בנשמות, המלאכים יש להם גוף ונפש ושרשן מאורות וכלים דע\"ס דבי\"ע, גם המלאכים שרשם מש' אלקים והנשמות מש' הוי', ושרש המקום וזמן נמשך מבחי' מל' ש' אלקים ואד', משא\"כ ש' הוי' ולכן לגבי הנשמות אין העולם תופס מקום כו'.</span>",[["1400","396","<b>בו</b>: בשער הגמול: עלי' שנאמר."],["1401","397","<b>ויפח באפיו נשמת חיים</b>: בראשית ב, ז."],["1402","398","<b>יאמר</b>: באוה\"ת: ואמר. ובהנ\"ל: כבפנים."],["1403","399","<b>מנשמת</b>: בלקו\"ת לג\"פ ואוה\"ת: נשמת. ובהנ\"ל: כבפנים."],["1404","400","<b>לא מהשתלשלות הסיבות</b>: וכ\"ה בלקו\"ת לג\"פ ואוה\"ת כאן. בהפירוש: ולא מהשתלשל הסבות. בשער הגמול: ולא מהשתלשלות."],["1405","401","<b>וא\"ת. . גיהנם</b>: בלקו\"ת לג\"פ (הובא באוה\"ת כאן בשולי הגליון): וא\"כ האיך. . גיהנם. בהפירוש: וא\"ת איך. . גיהנם. בשער הגמול ע' רפז: ואם יקשה עלינו האיך הנפש נגבלת. . גיהנם או שאול. נשיב להם. . נפש שוכנת בו ויהי' חבורה בגופו."],["1406","402","<b>בלבוש. . חלוקא דרבנן</b>: זהר נח סו, א."],["1407","403","<b>כקול מים רבים</b>: — וכ\"ה בלקו\"ת לג\"פ ואוה\"ת כאן. תיבות אלו לא הובאו לעיל בפנים — יחזקאל א, כד."]]]]});
